  var yA='Sí  ('+x+' ∈ A)', nA='No  ('+x+' ∉ A)';
  return{q:'A = {x / '+c.rule+'}  →  ¿Pertenece '+x+' a A?',a:useBelongs?yA:nA,opts:[yA,nA],mc:true,
    ste:useBelongs?x+' cumple la condición → sí pertenece.':x+' no cumple la condición → no pertenece.'};
