function _genI1A_EX1_B2(){
  return _i4gpick([
    // Plantilla 1: Producto de misma base
    {_id:1,q:'Calcula: A = x²·x³·x⁴',a:'x⁹',opts:_i4gshuf(['x⁹','x²⁴','x⁵','3x⁹']),mc:true,ste:'Misma base: se suman exponentes. 2+3+4=9.'},
    {_id:2,q:'Simplifica: (a⁵)·(a³)',a:'a⁸',opts:_i4gshuf(['a⁸','a¹⁵','2a⁸','a²']),mc:true,ste:'a⁵·a³ = a^(5+3) = a⁸.'},
    {_id:3,q:'Calcula: (2x³)·(3x⁴)',a:'6x⁷',opts:_i4gshuf(['6x⁷','6x¹²','5x⁷','6x']),mc:true,ste:'2·3=6, x^(3+4)=x⁷. R=6x⁷.'},
    {_id:4,q:'Efectúa: 4x²·3x·5x³',a:'60x⁶',opts:_i4gshuf(['60x⁶','60x⁵','12x⁶','20x⁶']),mc:true,ste:'4·3·5=60. 2+1+3=6.'},
    // Plantilla 2: Productos con signos negativos
    {_id:5,q:'Efectúa: (−2x³)·(−3x⁴)',a:'6x⁷',opts:_i4gshuf(['6x⁷','−6x⁷','6x¹²','−6x¹²']),mc:true,ste:'Dos negativos → positivo. 2·3=6. 3+4=7. R=6x⁷.'},
    {_id:6,q:'Calcula: (−4x²)·(−3x³)',a:'12x⁵',opts:_i4gshuf(['12x⁵','−12x⁵','12x⁶','−12x⁶']),mc:true,ste:'Dos negativos → positivo. 4·3=12. 2+3=5. R=12x⁵.'},
    {_id:7,q:'Efectúa: (−2x²)·(−3x³)·(−x⁴)',a:'−6x⁹',opts:_i4gshuf(['−6x⁹','6x⁹','−6x²⁴','6x²⁴']),mc:true,ste:'Tres negativos → negativo. 2·3·1=6. 2+3+4=9. R=−6x⁹.'},
    {_id:8,q:'Simplifica: (−x²)·(−x³)·(−x⁴)',a:'−x⁹',opts:_i4gshuf(['−x⁹','x⁹','−x²⁴','x²⁴']),mc:true,ste:'Tres negativos→negativo. 2+3+4=9.'},
    // Plantilla 3: Triple producto con signo y regla
    {_id:9,q:'Efectúa: (−2x⁶)·(3x⁴)·(−2x²)',a:'12x¹²',opts:_i4gshuf(['12x¹²','−12x¹²','6x¹²','−6x¹²']),mc:true,ste:'Dos factores negativos → positivo. 2·3·2=12. 6+4+2=12. R=12x¹².'},
    {_id:10,q:'Calcula: (2x⁴)·(−3x³)',a:'−6x⁷',opts:_i4gshuf(['−6x⁷','6x⁷','−6x¹²','6x¹²']),mc:true,ste:'Un factor negativo → negativo. 2·3=6. 4+3=7. R=−6x⁷.'},
    {_id:11,q:'Efectúa: (−x³)·(x²)·(−x⁴)',a:'x⁹',opts:_i4gshuf(['x⁹','−x⁹','x²⁴','−x²⁴']),mc:true,ste:'Dos factores negativos → positivo. 3+2+4=9.'},
    {_id:12,q:'Calcula: (−4x³)·(2x²)',a:'−8x⁵',opts:_i4gshuf(['−8x⁵','8x⁵','−8x⁶','8x⁶']),mc:true,ste:'Un factor negativo → negativo. 4·2=8. 3+2=5. R=−8x⁵.'},
    // Plantilla 4: Suma de productos
    {_id:13,q:'Calcula: 2x³·x⁴·x⁵ + 7x⁶·x⁶ + 6x¹⁰·x²',a:'15x¹²',opts:_i4gshuf(['15x¹²','15x¹⁰','21x¹²','13x¹⁰']),mc:true,ste:'2x¹²+7x¹²+6x¹² = 15x¹². El coeficiente es 15 porque los tres términos se reducen al mismo grado 12.'},
    {_id:14,q:'Simplifica: (2x)(3x²)(x⁴) + 5x⁷',a:'11x⁷',opts:_i4gshuf(['11x⁷','6x⁷','10x⁷','12x⁷']),mc:true,ste:'6x⁷+5x⁷=11x⁷.'},
    {_id:15,q:'Simplifica: 3x²·x³ + 2x·x⁴',a:'5x⁵',opts:_i4gshuf(['5x⁵','5x⁸','3x⁵','6x⁵']),mc:true,ste:'3x⁵+2x⁵=5x⁵.'},
    {_id:16,q:'Calcula: 5x³·x + 3x²·x² − 2x⁴',a:'6x⁴',opts:_i4gshuf(['6x⁴','8x⁴','4x⁴','6x⁸']),mc:true,ste:'5x⁴+3x⁴−2x⁴=6x⁴.'},
    // Plantilla 5: Exponentes literales y grado
    {_id:17,q:'x<sup>?</sup> · x³ = x⁸. ¿Cuál es el exponente que falta?',a:'5',opts:_i4gshuf(['5','3','11','24']),mc:true,ste:'Al multiplicar misma base, se suman exponentes: ?+3=8 → ?=5.'},
    {_id:18,q:'Al multiplicar potencias de igual base, los exponentes se...',a:'Suman',opts:_i4gshuf(['Suman','Multiplican','Restan','Dividen']),mc:true,ste:'Ley del producto: xᵃ·xᵇ = xᵃ⁺ᵇ.'},
    {_id:19,q:'? · 2x³ · x = 12x⁶. ¿Cuál es el término que falta?',a:'6x²',opts:_i4gshuf(['6x²','4x²','6x³','3x²']),mc:true,ste:'Coeficiente: ?·2=12 → ?=6. Exponentes: ?+3+1=6 → ?=2. El término es 6x².'},
    {_id:20,q:'Si xᵃ · xᵇ = x⁰, ¿qué relación hay entre a y b?',a:'a = −b',opts:_i4gshuf(['a = −b','a = b','a · b = 0','a − b = 0']),mc:true,ste:'Al multiplicar se suman exponentes: a+b=0 → a=−b.'},
  ]);
}
