function _genI1A_EX1_B3(){
  return _i4gpick([
    // Plantilla 1: División básica de igual base
    {_id:1,q:'Simplifica: x¹⁰ ÷ x³',a:'x⁷',opts:_i4gshuf(['x⁷','x¹³','x³⁰','x']),mc:true,ste:'Misma base: se restan exponentes. 10−3=7.'},
    {_id:2,q:'Simplifica: x⁸ ÷ x⁵',a:'x³',opts:_i4gshuf(['x³','x¹³','x⁴⁰','x']),mc:true,ste:'8−5=3.'},
    {_id:3,q:'Simplifica: y¹⁵ ÷ y⁷',a:'y⁸',opts:_i4gshuf(['y⁸','y²²','y¹⁰⁵','y']),mc:true,ste:'15−7=8.'},
    {_id:4,q:'Simplifica: z¹² ÷ z⁴',a:'z⁸',opts:_i4gshuf(['z⁸','z¹⁶','z⁴⁸','z³']),mc:true,ste:'12−4=8. Resultado: z⁸.'},
    // Plantilla 2: Cociente de bases negativas
    {_id:5,q:'Simplifica: (−a⁴b⁶) ÷ (a²b³)',a:'−a²b³',opts:_i4gshuf(['−a²b³','a²b³','−a⁶b⁹','a²b⁹']),mc:true,ste:'Negativo ÷ positivo → negativo. a^(4−2)·b^(6−3)=a²b³.'},
    {_id:6,q:'Simplifica: (a⁶b⁴) ÷ (−a³b⁴)',a:'−a³',opts:_i4gshuf(['−a³','a³','−a³b⁸','a⁹b⁸']),mc:true,ste:'Positivo ÷ negativo → negativo. a^(6−3)·b^(4−4)=a³.'},
    {_id:7,q:'Simplifica: (−x³y⁵) ÷ (−xy²)',a:'x²y³',opts:_i4gshuf(['x²y³','−x²y³','x³y⁵','x²y²']),mc:true,ste:'Negativo ÷ negativo → positivo. x^(3−1)·y^(5−2)=x²y³.'},
    {_id:8,q:'Calcula: (−4a⁵b³) ÷ (−2a²b)',a:'2a³b²',opts:_i4gshuf(['2a³b²','−2a³b²','4a³b²','2a⁷b⁴']),mc:true,ste:'Negativo ÷ negativo → positivo. 4/2=2. a^(5−2)=a³. b^(3−1)=b².'},
    // Plantilla 3: Cociente de bases mixtas
    {_id:9,q:'Calcula: (−a³)(b⁵) ÷ (ab²)',a:'−a²b³',opts:_i4gshuf(['−a²b³','a²b³','−a³b⁵','a²b²']),mc:true,ste:'1 factor negativo → resultado negativo. a^(3−1)=a². b^(5−2)=b³.'},
    {_id:10,q:'Calcula: (−a³)(−b⁵) ÷ (ab²)',a:'a²b³',opts:_i4gshuf(['a²b³','−a²b³','a³b⁵','a²b²']),mc:true,ste:'2 factores negativos → resultado positivo. a^(3−1)=a². b^(5−2)=b³.'},
    {_id:11,q:'Calcula: (−a³)(−b⁵) ÷ [(−a)b²]',a:'−a²b³',opts:_i4gshuf(['−a²b³','a²b³','−a³b⁵','−a²b²']),mc:true,ste:'3 factores negativos → resultado negativo. a^(3−1)=a². b^(5−2)=b³.'},
    {_id:12,q:'Calcula: (−a³)(−b⁵) ÷ [(−a)(−b²)]',a:'a²b³',opts:_i4gshuf(['a²b³','−a²b³','a³b⁵','a²b²']),mc:true,ste:'4 factores negativos → resultado positivo. a^(3−1)=a². b^(5−2)=b³.'},
    // Plantilla 4: Suma o resta de divisiones
    {_id:13,q:'Simplifica: a⁵÷a³ + 2a¹⁰÷a⁸ + 3a¹⁵÷a¹³',a:'6a²',opts:_i4gshuf(['6a²','5a²','8a²','4a²']),mc:true,ste:'a²+2a²+3a²=6a².'},
    {_id:14,q:'Calcula: x⁶÷x⁴ − 3x⁴÷x²',a:'−2x²',opts:_i4gshuf(['−2x²','2x²','4x²','−4x²']),mc:true,ste:'x²−3x²=−2x².'},
    {_id:15,q:'Calcula: (−2x⁵)÷x² + 3x⁷÷x⁴',a:'x³',opts:_i4gshuf(['x³','−x³','5x³','−5x³']),mc:true,ste:'−2x³+3x³=x³.'},
    {_id:16,q:'Calcula: (−3x⁷)÷x³ − (−x⁹)÷x⁵',a:'−2x⁴',opts:_i4gshuf(['−2x⁴','2x⁴','−4x⁴','4x⁴']),mc:true,ste:'−3x⁴−(−x⁴)=−3x⁴+x⁴=−2x⁴.'},
    // Plantilla 5: Ecuaciones y casos especiales
    {_id:17,q:'x<sup>?</sup> ÷ x³ = x⁴. ¿Cuál es el exponente que falta?',a:'7',opts:_i4gshuf(['7','1','12','3']),mc:true,ste:'Al dividir misma base, se restan: ?−3=4 → ?=7.'},
    {_id:18,q:'Si x³ ÷ x<sup>?</sup> = x⁸, ¿cuánto vale el exponente que falta?',a:'−5',opts:_i4gshuf(['−5','5','11','−11']),mc:true,ste:'3−?=8 → ?=3−8=−5. El exponente puede ser negativo.'},
    {_id:19,q:'Si xᵃ ÷ xᵇ = x⁰, ¿qué relación hay entre a y b?',a:'a = b',opts:_i4gshuf(['a = b','a = 0','b = 0','a + b = 0']),mc:true,ste:'x^(a−b)=x⁰ → a−b=0 → a=b.'},
    {_id:20,q:'Para dividir potencias de igual base, los exponentes se...',a:'Restan',opts:_i4gshuf(['Restan','Suman','Multiplican','Dividen']),mc:true,ste:'Ley del cociente: xᵃ÷xᵇ = xᵃ⁻ᵇ.'},
  ]);
}
