function _genI1A_EX1_B9(){
  return _i4gpick([
    // Plantilla 1: (a^(n+p)+a^(n+q))/a^(n+r) → fracción (4 qx)
    {_id:1,q:'Reduce: (2<sup>n+1</sup>+2<sup>n+2</sup>) ÷ 2<sup>n+3</sup>',a:'3/4',opts:_i4gshuf(['3/4','3/2','3','6']),mc:true,ste:'Factor 2^(n+1): 2^(n+1)(1+2)/2^(n+3)=3/2²=3/4.'},
    {_id:2,q:'Reduce: (3<sup>n+1</sup>+3<sup>n+2</sup>) ÷ 3<sup>n+3</sup>',a:'4/9',opts:_i4gshuf(['4/9','4/3','9/4','1/3']),mc:true,ste:'Factor 3^(n+1): 3^(n+1)(1+3)/3^(n+3)=4/3²=4/9.'},
    {_id:3,q:'Reduce: (5<sup>n+2</sup>+5<sup>n+1</sup>) ÷ 5<sup>n+3</sup>',a:'6/25',opts:_i4gshuf(['6/25','6/5','1/5','5/6']),mc:true,ste:'Factor 5^(n+1): 5^(n+1)(5+1)/5^(n+3)=6/5²=6/25.'},
    {_id:4,q:'Reduce: (2<sup>n+3</sup>+2<sup>n+1</sup>) ÷ 2<sup>n+2</sup>',a:'5/2',opts:_i4gshuf(['5/2','5','3/2','5/4']),mc:true,ste:'Factor 2^(n+1): 2^(n+1)(4+1)/2^(n+2)=5/2.'},
    // Plantilla 2: cociente (a^(n+p)+a^(n+q))/(a^(n+r)+a^(n+s)) → entero (4 qx)
    {_id:5,q:'Reduce: (5<sup>n+4</sup>+5<sup>n+3</sup>) ÷ (5<sup>n+3</sup>+5<sup>n+2</sup>)',a:'5',opts:_i4gshuf(['5','1','25','10']),mc:true,ste:'Num: 5^(n+3)·6. Den: 5^(n+2)·6. Los 6 se cancelan: 5^(n+3)/5^(n+2)=5.'},
    {_id:6,q:'Reduce: (2<sup>n+3</sup>+2<sup>n+2</sup>) ÷ (2<sup>n+2</sup>+2<sup>n+1</sup>)',a:'2',opts:_i4gshuf(['2','4','8','1']),mc:true,ste:'Num: 2^(n+2)·3. Den: 2^(n+1)·3. Los 3 se cancelan: 2^(n+2)/2^(n+1)=2.'},
    {_id:7,q:'Reduce: (3<sup>n+3</sup>+3<sup>n+2</sup>) ÷ (3<sup>n+1</sup>+3<sup>n</sup>)',a:'9',opts:_i4gshuf(['9','3','27','6']),mc:true,ste:'Num: 3^(n+2)·4. Den: 3^n·4. Los 4 se cancelan: 3^(n+2)/3^n=3²=9.'},
    {_id:8,q:'Reduce: (7<sup>n+2</sup>+7<sup>n+1</sup>) ÷ (7<sup>n</sup>+7<sup>n−1</sup>)',a:'49',opts:_i4gshuf(['49','7','14','21']),mc:true,ste:'Num: 7^(n+1)·8. Den: 7^(n−1)·8. Los 8 se cancelan: 7^(n+1)/7^(n−1)=7²=49.'},
    // Plantilla 3: Z-tipo — conversión cruzada de base + suma (4 qx)
    {_id:9,q:'Reduce: Z = (2<sup>2a+1</sup>+4<sup>a−1</sup>) ÷ 2<sup>2a−2</sup>',a:'9',opts:_i4gshuf(['9','8','10','4']),mc:true,ste:'4^(a−1)=2^(2a−2). Z=(2^(2a+1)+2^(2a−2))/2^(2a−2)=2³+1=9.'},
    {_id:10,q:'Reduce: W = (3<sup>2b+1</sup>+9<sup>b</sup>) ÷ 3<sup>2b</sup>',a:'4',opts:_i4gshuf(['4','3','6','9']),mc:true,ste:'9^b=(3²)^b=3^(2b). W=(3^(2b+1)+3^(2b))/3^(2b)=3+1=4.'},
    {_id:11,q:'Reduce: R = (4<sup>x+1</sup>+2<sup>2x+1</sup>) ÷ 2<sup>2x</sup>',a:'6',opts:_i4gshuf(['6','4','8','2']),mc:true,ste:'4^(x+1)=2^(2x+2). R=(2^(2x+2)+2^(2x+1))/2^(2x)=2²+2=6.'},
    {_id:12,q:'Reduce: V = (2<sup>2k+2</sup>+4<sup>k</sup>) ÷ 2<sup>2k</sup>',a:'5',opts:_i4gshuf(['5','4','6','8']),mc:true,ste:'4^k=2^(2k). V=(2^(2k+2)+2^(2k))/2^(2k)=2²+1=5.'},
    // Plantilla 4: cocientes constantes simples (4 qx)
    {_id:13,q:'Reduce: (3<sup>n+2</sup>+3<sup>n+1</sup>) ÷ (3<sup>n+1</sup>+3<sup>n</sup>)',a:'3',opts:_i4gshuf(['3','9','1','6']),mc:true,ste:'Num: 3^(n+1)·4. Den: 3^n·4. Ratio=3.'},
    {_id:14,q:'Reduce: (2<sup>n+4</sup>+2<sup>n+3</sup>) ÷ (2<sup>n+2</sup>+2<sup>n+1</sup>)',a:'4',opts:_i4gshuf(['4','2','8','16']),mc:true,ste:'Num: 2^(n+3)·3. Den: 2^(n+1)·3. Ratio=2²=4.'},
    {_id:15,q:'Reduce: (5<sup>n+1</sup>+5<sup>n</sup>) ÷ (5<sup>n−1</sup>+5<sup>n−2</sup>)',a:'25',opts:_i4gshuf(['25','5','10','50']),mc:true,ste:'Num: 5^n·6. Den: 5^(n−2)·6. Ratio=5²=25.'},
    {_id:16,q:'Reduce: (2<sup>n</sup>+2<sup>n−1</sup>) ÷ (2<sup>n−2</sup>+2<sup>n−3</sup>)',a:'4',opts:_i4gshuf(['4','2','8','16']),mc:true,ste:'Num: 2^(n−1)·3. Den: 2^(n−3)·3. Ratio=2²=4.'},
    // Plantilla 5: Conceptual sobre el proceso (4 qx)
    {_id:17,q:'Para reducir (2<sup>n+1</sup>+2<sup>n+2</sup>)/2<sup>n+3</sup>, el primer paso es:',a:'Factorizar 2<sup>n+1</sup> en el numerador',opts:_i4gshuf(['Factorizar 2<sup>n+1</sup> en el numerador','Dividir término a término','Convertir a base 4','Restar los exponentes directamente']),mc:true,ste:'Se identifica el factor común más pequeño 2^(n+1) y se saca del numerador.'},
    {_id:18,q:'En (5<sup>n+4</sup>+5<sup>n+3</sup>)/(5<sup>n+3</sup>+5<sup>n+2</sup>), al factorizar ¿qué se cancela?',a:'Se cancelan 5<sup>n+2</sup> y el factor 6; resultado = 5',opts:_i4gshuf(['Se cancelan 5<sup>n+2</sup> y el factor 6; resultado = 5','Solo el factor (5+1)=6','Solo el 5<sup>n</sup>','Nada se cancela']),mc:true,ste:'Num=5^(n+3)·6=5^(n+2)·5·6. Den=5^(n+2)·6. Se cancela 5^(n+2)·6 en ambos. Queda 5^1=5.'},
    {_id:19,q:'¿Qué resultado tiene siempre (a<sup>n+k+1</sup>+a<sup>n+k</sup>) ÷ (a<sup>n+k</sup>+a<sup>n+k−1</sup>)?',a:'a',opts:_i4gshuf(['a','a²','1','2a']),mc:true,ste:'Num: a^(n+k)(a+1). Den: a^(n+k−1)(a+1). El (a+1) se cancela. Ratio=a.'},
    {_id:20,q:'¿Para qué base aplica la técnica de factorizar sumas como (a<sup>n+1</sup>+a<sup>n+2</sup>)/a<sup>n+3</sup>?',a:'Para cualquier base a≠0',opts:_i4gshuf(['Para cualquier base a≠0','Solo para base 2','Solo para bases enteras','Solo cuando n=0']),mc:true,ste:'La propiedad aᵐ·aⁿ=aᵐ⁺ⁿ y el factor común aplican para cualquier a≠0.'},
  ]);
}
