// ===== St. George's College - 3ro Secundaria (Grado 9) - Matemática: Composición de Funciones (Unidad 02) =====

function _genSG3M2_B1(){
  return _i4gpick([
  {_id:1,q:'Dada la función f(x) = 4x - 5, halle f(3).',a:'7',opts:_i4gshuf(['7','11','3','2']),mc:true,ste:'f(3) = 4(3) - 5 = 7.'},
  {_id:2,q:'Dada la función f(x) = 3x + 2, halle f(-2).',a:'-4',opts:_i4gshuf(['-4','-1','-7','-2']),mc:true,ste:'f(-2) = 3(-2) + 2 = -4.'},
  {_id:3,q:'Dada la función f(x) = 2x - 1, halle f(4).',a:'7',opts:_i4gshuf(['7','9','5','6']),mc:true,ste:'f(4) = 2(4) - 1 = 7.'},
  {_id:4,q:'Dada la función f(x) = 5x + 3, halle f(-3).',a:'-12',opts:_i4gshuf(['-12','-7','-17','-9']),mc:true,ste:'f(-3) = 5(-3) + 3 = -12.'},
  {_id:5,q:'Dada la función g(x) = 2x² - 3x + 1, halle g(-2).',a:'15',opts:_i4gshuf(['15','17','18','12']),mc:true,ste:'g(-2) = 2(-2)² - 3(-2) + 1 = 15.'},
  {_id:6,q:'Dada la función g(x) = x² - 2x + 3, halle g(4).',a:'11',opts:_i4gshuf(['11','12','13','14']),mc:true,ste:'g(4) = 1(4)² - 2(4) + 3 = 11.'},
  {_id:7,q:'Dada la función g(x) = 3x² + x - 2, halle g(-1).',a:'0',opts:_i4gshuf(['0','3','-1','-3']),mc:true,ste:'g(-1) = 3(-1)² + 1(-1) - 2 = 0.'},
  {_id:8,q:'Dada la función g(x) = 2x² + 5x - 1, halle g(2).',a:'17',opts:_i4gshuf(['17','19','12','20']),mc:true,ste:'g(2) = 2(2)² + 5(2) - 1 = 17.'},
  {_id:9,q:'Dadas f(x) = 4x - 5 y g(x) = 2x² - 3x + 1, halle f(3) + g(-2).',a:'22',opts:_i4gshuf(['22','-8','24','20']),mc:true,ste:'f(3) = 7, g(-2) = 15 → 7 + 15 = 22.'},
  {_id:10,q:'Dadas f(x) = 3x + 2 y g(x) = x² - 2x + 3, halle f(-1) - g(2).',a:'-4',opts:_i4gshuf(['-4','2','-2','-6']),mc:true,ste:'f(-1) = -1, g(2) = 3 → -1 - 3 = -4.'},
  {_id:11,q:'Dadas f(x) = 2x - 1 y g(x) = 3x² + x - 2, halle f(4) + g(1).',a:'9',opts:_i4gshuf(['9','5','11','7']),mc:true,ste:'f(4) = 7, g(1) = 2 → 7 + 2 = 9.'},
  {_id:12,q:'Dadas f(x) = 5x + 3 y g(x) = 2x² + 5x - 1, halle f(-2) - g(-1).',a:'-3',opts:_i4gshuf(['-3','-11','-1','-5']),mc:true,ste:'f(-2) = -7, g(-1) = -4 → -7 - -4 = -3.'},
  {_id:13,q:'V/F: Si f(x) = 4x - 5, entonces f(3) = 7.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Sustituyendo x = 3 en f(x) = 4x - 5 y calculando, la afirmación es correcta.'},
  {_id:14,q:'V/F: Si f(x) = 4x - 5, entonces f(3) = 10.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Sustituyendo x = 3 en f(x) = 4x - 5 y calculando, la afirmación es incorrecta.'},
  {_id:15,q:'V/F: Si f(x) = 3x + 2, entonces f(-2) = -4.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Sustituyendo x = -2 en f(x) = 3x + 2 y calculando, la afirmación es correcta.'},
  {_id:16,q:'V/F: Si f(x) = 3x + 2, entonces f(-2) = -1.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Sustituyendo x = -2 en f(x) = 3x + 2 y calculando, la afirmación es incorrecta.'},
  {_id:17,q:'Dada la función h(x) = 3x - 4, halle h(2).',a:'2',opts:_i4gshuf(['2','5','-1','4']),mc:true,ste:'h(2) = 3(2) - 4 = 2.'},
  {_id:18,q:'Dada la función h(x) = x² + 4x + 2, halle h(5).',a:'47',opts:_i4gshuf(['47','48','43','50']),mc:true,ste:'h(5) = 1(5)² + 4(5) + 2 = 47.'},
  {_id:19,q:'Dada la función h(x) = - 2x + 7, halle h(3).',a:'1',opts:_i4gshuf(['1','-1','3','0']),mc:true,ste:'h(3) = -2(3) + 7 = 1.'},
  {_id:20,q:'Dada la función h(x) = 3x² + x - 2, halle h(-1).',a:'0',opts:_i4gshuf(['0','3','-1','-2']),mc:true,ste:'h(-1) = 3(-1)² + 1(-1) - 2 = 0.'},
  ]);
}
_SKILL_META['sg3m2_b1']={ico:'🔗',lbl:'Evaluación de funciones algebraicas',qCount:4,gen:_genSG3M2_B1,plantillas:["Dada f(x) lineal, hallar f(a) para un valor numérico", "Dada g(x) cuadrática, hallar g(a) para un valor numérico", "Dadas f(x) y g(x), hallar f(a)+g(b) o f(a)−g(b)", "V/F sobre el resultado de evaluar una función en un punto dado", "Variante de evaluación con otro tipo de función"]};

function _genSG3M2_B2(){
  return _i4gpick([
  {_id:1,q:'Dadas f(x) = 4x - 5 y g(x) = 2x² - 3x + 1, halle f(g(1)).',a:'-5',opts:_i4gshuf(['-5','0','-1','-9']),mc:true,ste:'g(1) = 0; luego f(0) = 4(0) - 5 = -5.'},
  {_id:2,q:'Dadas f(x) = 3x + 2 y g(x) = x² - 2x + 3, halle f(g(-2)).',a:'35',opts:_i4gshuf(['35','11','38','32']),mc:true,ste:'g(-2) = 11; luego f(11) = 3(11) + 2 = 35.'},
  {_id:3,q:'Dadas f(x) = 2x - 1 y g(x) = 3x² + x - 2, halle f(g(4)).',a:'99',opts:_i4gshuf(['99','50','101','97']),mc:true,ste:'g(4) = 50; luego f(50) = 2(50) - 1 = 99.'},
  {_id:4,q:'Dadas f(x) = 3x + 1 y g(x) = 2x² + 5x - 1, halle f(g(-1)).',a:'-11',opts:_i4gshuf(['-11','-4','-8','-14']),mc:true,ste:'g(-1) = -4; luego f(-4) = 3(-4) + 1 = -11.'},
  {_id:5,q:'Dadas f(x) = 4x - 5 y g(x) = 2x² - 3x + 1, halle g(f(1)).',a:'6',opts:_i4gshuf(['6','-1','8','9']),mc:true,ste:'f(1) = -1; luego g(-1) = 2(-1)² - 3(-1) + 1 = 6.'},
  {_id:6,q:'Dadas f(x) = 3x + 2 y g(x) = x² - 2x + 3, halle g(f(-1)).',a:'6',opts:_i4gshuf(['6','-1','7','8']),mc:true,ste:'f(-1) = -1; luego g(-1) = 1(-1)² - 2(-1) + 3 = 6.'},
  {_id:7,q:'Dadas f(x) = 2x - 1 y g(x) = 3x² + x - 2, halle g(f(2)).',a:'28',opts:_i4gshuf(['28','3','31','27']),mc:true,ste:'f(2) = 3; luego g(3) = 3(3)² + 1(3) - 2 = 28.'},
  {_id:8,q:'Dadas f(x) = 3x + 1 y g(x) = 2x² + 5x - 1, halle g(f(0)).',a:'6',opts:_i4gshuf(['6','1','8','-6']),mc:true,ste:'f(0) = 1; luego g(1) = 2(1)² + 5(1) - 1 = 6.'},
  {_id:9,q:'Dadas f(x) = 4x - 5 y g(x) = 2x² - 3x + 1, halle f(g(1)) + g(f(1)).',a:'1',opts:_i4gshuf(['1','-11','3','-1']),mc:true,ste:'f(g(1)) = -5, g(f(1)) = 6 → -5 + 6 = 1.'},
  {_id:10,q:'Dadas f(x) = 3x + 2 y g(x) = x² - 2x + 3, halle f(g(-1)) - g(f(-1)).',a:'14',opts:_i4gshuf(['14','26','16','12']),mc:true,ste:'f(g(-1)) = 20, g(f(-1)) = 6 → 20 - 6 = 14.'},
  {_id:11,q:'Dadas f(x) = 2x - 1 y g(x) = 3x² + x - 2, halle f(g(2)) + g(f(0)).',a:'23',opts:_i4gshuf(['23','25','21','0']),mc:true,ste:'f(g(2)) = 23, g(f(0)) = 0 → 23 + 0 = 23.'},
  {_id:12,q:'Dadas f(x) = 3x + 1 y g(x) = 2x² + 5x - 1, halle f(g(-1)) - g(f(2)).',a:'-143',opts:_i4gshuf(['-143','121','-141','-145']),mc:true,ste:'f(g(-1)) = -11, g(f(2)) = 132 → -11 - 132 = -143.'},
  {_id:13,q:'V/F: Con f(x) = 4x - 5 y g(x) = 2x² - 3x + 1, se cumple que f(g(1)) = g(f(1)).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'f(g(1)) = -5 y g(f(1)) = 6; por lo tanto la afirmación es falsa (la composición no es conmutativa en general).'},
  {_id:14,q:'V/F: Con f(x) = 3x + 2 y g(x) = x² - 2x + 3, se cumple que f(g(1)) = g(f(1)).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'f(g(1)) = 8 y g(f(1)) = 18; por lo tanto la afirmación es falsa (la composición no es conmutativa en general).'},
  {_id:15,q:'V/F: Con f(x) = 2x - 1 y g(x) = 3x² + x - 2, se cumple que f(g(1)) = g(f(1)).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'f(g(1)) = 3 y g(f(1)) = 2; por lo tanto la afirmación es falsa (la composición no es conmutativa en general).'},
  {_id:16,q:'V/F: Con f(x) = 3x + 1 y g(x) = 2x² + 5x - 1, se cumple que f(g(1)) = g(f(1)).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'f(g(1)) = 19 y g(f(1)) = 51; por lo tanto la afirmación es falsa (la composición no es conmutativa en general).'},
  {_id:17,q:'Dadas f(x) = 3x y h(x) = x² + 2, halle f(h(2)).',a:'18',opts:_i4gshuf(['18','6','20','16']),mc:true,ste:'h(2) = 6; luego f(6) = 3(6) + 0 = 18.'},
  {_id:18,q:'Dadas f(x) = 2x + 1 y h(x) = x² - x + 3, halle h(f(1)).',a:'9',opts:_i4gshuf(['9','3','11','7']),mc:true,ste:'f(1) = 3; luego h(3) = 1(3)² - 1(3) + 3 = 9.'},
  {_id:19,q:'Dadas f(x) = x - 1 y h(x) = 2x² - 2, halle f(h(-1)).',a:'-1',opts:_i4gshuf(['-1','0','1','-3']),mc:true,ste:'h(-1) = 0; luego f(0) = 1(0) - 1 = -1.'},
  {_id:20,q:'Dadas f(x) = 2x - 3 y h(x) = x² + 2x, halle h(f(2)).',a:'3',opts:_i4gshuf(['3','1','5','-3']),mc:true,ste:'f(2) = 1; luego h(1) = 1(1)² + 2(1) + 0 = 3.'},
  ]);
}
