_SKILL_META['svr3ar_b3']={ico:'💯',lbl:'¿Qué porcentaje representa un valor de otro?',qCount:4,gen:_genSVR3AR_B3,plantillas:["Hallar qué porcentaje es A de B, con A menor que B", "Hallar qué porcentaje es A de B, con A mayor que B (resultado mayor a 100%)", "V/F sobre el cálculo del porcentaje que representa un valor de otro", "Identificar el porcentaje correcto entre 4 opciones", "Variante con otros valores de A y B"]};

function _genSVR3AR_B4(){
  return _i4gpick([
  {_id:1,q:'Nataly recibe de propina el 30% de 60 soles; y Stephany recibe de propina el 32% de 50 soles. ¿Quién recibe más dinero? (A = Nataly, B = Stephany)',a:'A',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Nataly recibe 30% de 60 = 18 soles; Stephany recibe 32% de 50 = 16 soles.'},
  {_id:2,q:'Renzo recibe de propina el 25% de 80 soles; y Mía recibe de propina el 40% de 60 soles. ¿Quién recibe más dinero? (A = Renzo, B = Mía)',a:'B',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Renzo recibe 25% de 80 = 20 soles; Mía recibe 40% de 60 = 24 soles.'},
  {_id:3,q:'Camila recibe de propina el 60% de 40 soles; y Diego recibe de propina el 45% de 60 soles. ¿Quién recibe más dinero? (A = Camila, B = Diego)',a:'B',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Camila recibe 60% de 40 = 24 soles; Diego recibe 45% de 60 = 27 soles.'},
  {_id:4,q:'Luis recibe de propina el 15% de 200 soles; y Ana recibe de propina el 20% de 160 soles. ¿Quién recibe más dinero? (A = Luis, B = Ana)',a:'B',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Luis recibe 15% de 200 = 30 soles; Ana recibe 20% de 160 = 32 soles.'},
  {_id:5,q:'¿Cuál es mayor: un número cuyo 60% es 240, o un número cuyo 80% es 64?',a:'el primero',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 400; el segundo es 80.'},
  {_id:6,q:'¿Cuál es mayor: un número cuyo 5% del 40% es 80, o un número cuyo 5% del 6% es 3000?',a:'el segundo',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 4000; el segundo es 1000000.'},
  {_id:7,q:'¿Cuál es mayor: un número cuyo 20% es 90, o un número cuyo 30% es 90?',a:'el primero',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 450; el segundo es 300.'},
  {_id:8,q:'¿Cuál es mayor: un número cuyo 10% del 50% es 45, o un número cuyo 0.03% es 150000?',a:'el segundo',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 900; el segundo es 500000000.'},
  {_id:9,q:'V/F: El 60% de 240 es mayor que el 80% de 64.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'60% de 240 = 144, y 80% de 64 = 51.2; por lo tanto, 144 > 51.2, la afirmación es verdadera.'},
  {_id:10,q:'V/F: El 30% de 60 es mayor que el 32% de 50.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'30% de 60 = 18, y 32% de 50 = 16; por lo tanto, 18 > 16, la afirmación es verdadera.'},
  {_id:11,q:'V/F: Un número cuyo 60% es 240 es menor que un número cuyo 80% es 64.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'El primer número es 400 (=240×100/60) y el segundo es 80 (=64×100/80); 400 no es menor que 80, la afirmación es falsa.'},
  {_id:12,q:'V/F: Si dos personas reciben el mismo porcentaje de bases distintas, siempre reciben la misma cantidad de dinero.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: si las bases son distintas, aplicar el mismo porcentaje generalmente da resultados diferentes.'},
  {_id:13,q:'Paolo recibe de propina el 45% de 80 soles; y Sofía recibe de propina el 50% de 70 soles. ¿Quién recibe más dinero? (A = Paolo, B = Sofía)',a:'A',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Paolo recibe 45% de 80 = 36 soles; Sofía recibe 50% de 70 = 35 soles.'},
  {_id:14,q:'Bruno recibe de propina el 12% de 500 soles; y Valeria recibe de propina el 18% de 300 soles. ¿Quién recibe más dinero? (A = Bruno, B = Valeria)',a:'A',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Bruno recibe 12% de 500 = 60 soles; Valeria recibe 18% de 300 = 54 soles.'},
  {_id:15,q:'Iker recibe de propina el 24% de 250 soles; y Zoe recibe de propina el 20% de 300 soles. ¿Quién recibe más dinero? (A = Iker, B = Zoe)',a:'Reciben lo mismo',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Iker recibe 24% de 250 = 60 soles; Zoe recibe 20% de 300 = 60 soles.'},
  {_id:16,q:'Marco recibe de propina el 35% de 120 soles; y Elena recibe de propina el 28% de 150 soles. ¿Quién recibe más dinero? (A = Marco, B = Elena)',a:'Reciben lo mismo',opts:_i4gshuf(['A','B','Reciben lo mismo','No se puede determinar']),mc:true,ste:'Marco recibe 35% de 120 = 42 soles; Elena recibe 28% de 150 = 42 soles.'},
  {_id:17,q:'¿Cuál es mayor: un número cuyo 25% es 100, o un número cuyo 8% del 50% es 40?',a:'el segundo',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 400; el segundo es 1000.'},
  {_id:18,q:'¿Cuál es mayor: un número cuyo 10% del 20% es 60, o un número cuyo 15% es 300?',a:'el primero',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 3000; el segundo es 2000.'},
  {_id:19,q:'¿Cuál es mayor: un número cuyo 40% es 160, o un número cuyo 20% del 50% es 40?',a:'son iguales',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 400; el segundo es 400.'},
  {_id:20,q:'¿Cuál es mayor: un número cuyo 5% del 20% es 20, o un número cuyo 4% es 80?',a:'son iguales',opts:_i4gshuf(['el primero','el segundo','son iguales','no se puede determinar']),mc:true,ste:'El primero es 2000; el segundo es 2000.'},
  ]);
}
_SKILL_META['svr3ar_b4']={ico:'💯',lbl:'Comparar cantidades obtenidas mediante porcentajes',qCount:4,gen:_genSVR3AR_B4,plantillas:["Comparar dos personas/cantidades, cada una definida como el P% de un valor distinto", "Comparar dos números definidos por condiciones anidadas de porcentaje, elegir el mayor", "V/F sobre cuál cantidad es mayor", "Variante de comparación de propinas/cantidades", "Variante de comparación de números por condiciones anidadas"]};

function _genSVR3AR_B5(){
  return _i4gpick([
  {_id:1,q:'Si tuviera 20% menos de la edad que tengo, tendría 48 años. ¿Qué edad tengo actualmente?',a:'60 años',opts:_i4gshuf(['60 años','48 años','80 años','40 años']),mc:true,ste:'48 = N(1 − 20/100) → N = 48 / (1 − 20/100) = 60 años.'},
  {_id:2,q:'Si tuviera 25% menos de la edad que tengo, tendría 45 años. ¿Qué edad tengo actualmente?',a:'60 años',opts:_i4gshuf(['60 años','45 años','85 años','35 años']),mc:true,ste:'45 = N(1 − 25/100) → N = 45 / (1 − 25/100) = 60 años.'},
  {_id:3,q:'Si tuviera 10% menos de la edad que tengo, tendría 54 años. ¿Qué edad tengo actualmente?',a:'60 años',opts:_i4gshuf(['60 años','54 años','70 años','50 años']),mc:true,ste:'54 = N(1 − 10/100) → N = 54 / (1 − 10/100) = 60 años.'},
  {_id:4,q:'Si tuviera 30% menos de la edad que tengo, tendría 56 años. ¿Qué edad tengo actualmente?',a:'80 años',opts:_i4gshuf(['80 años','56 años','110 años','50 años']),mc:true,ste:'56 = N(1 − 30/100) → N = 56 / (1 − 30/100) = 80 años.'},
  {_id:5,q:'Una señora va al mercado, donde por comprar cierto número de naranjas le regalan un 5% de lo comprado, obteniendo así 420 naranjas. ¿Cuántas naranjas compró?',a:'400',opts:_i4gshuf(['400','420','380','440']),mc:true,ste:'N(1 + 5/100) = 420 → N = 420 / (1 + 5/100) = 400.'},
  {_id:6,q:'Una señora va al mercado, donde por comprar cierto número de manzanas le regalan un 10% de lo comprado, obteniendo así 220 manzanas. ¿Cuántas manzanas compró?',a:'200',opts:_i4gshuf(['200','220','180','240']),mc:true,ste:'N(1 + 10/100) = 220 → N = 220 / (1 + 10/100) = 200.'},
  {_id:7,q:'Una señora va al mercado, donde por comprar cierto número de panes le regalan un 20% de lo comprado, obteniendo así 240 panes. ¿Cuántas panes compró?',a:'200',opts:_i4gshuf(['200','240','220','180']),mc:true,ste:'N(1 + 20/100) = 240 → N = 240 / (1 + 20/100) = 200.'},
  {_id:8,q:'Una señora va al mercado, donde por comprar cierto número de huevos le regalan un 8% de lo comprado, obteniendo así 324 huevos. ¿Cuántas huevos compró?',a:'300',opts:_i4gshuf(['300','324','320','280']),mc:true,ste:'N(1 + 8/100) = 324 → N = 324 / (1 + 8/100) = 300.'},
  {_id:9,q:'V/F: Si al comprar N naranjas te regalan el 5% de N y obtienes 420 en total, la ecuación correcta es N(1 + 5/100) = 420.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: el total final (compradas + regaladas) es N más el 5% de N, es decir, N(1 + 5/100) = 420.'},
  {_id:10,q:'V/F: Si al comprar N naranjas te regalan el 5% de N y obtienes 420 en total, la ecuación correcta es N(1 − 5/100) = 420.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: un regalo adicional AUMENTA el total, por lo que se debe usar N(1 + 5/100), no N(1 − 5/100) (que representaría una reducción).'},
  {_id:11,q:'V/F: Si al tener P% menos de mi edad actual tendría X años, la ecuación correcta es N(1 − P/100) = X.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: \'P% menos de N\' significa N menos su P%, es decir, N(1 − P/100), y eso es igual al valor dado X.'},
  {_id:12,q:'V/F: En un problema donde se regala un porcentaje de lo comprado, la cantidad final siempre es menor que la cantidad comprada.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: al regalar una parte ADICIONAL de lo comprado, la cantidad final (comprado + regalado) es mayor que lo comprado, no menor.'},
  {_id:13,q:'Si mi mochila pesara 15% menos de lo que pesa, pesaría 68 kg. ¿Cuánto pesa actualmente mi mochila?',a:'80 kg',opts:_i4gshuf(['80 kg','68 kg','95 kg','65 kg']),mc:true,ste:'68 = N(1 − 15/100) → N = 68 / (1 − 15/100) = 80 kg.'},
  {_id:14,q:'Si la distancia recorrida fuera 20% menor a la real, sería de 96 km. ¿Cuál es la distancia real recorrida?',a:'120 km',opts:_i4gshuf(['120 km','96 km','140 km','100 km']),mc:true,ste:'96 = N(1 − 20/100) → N = 96 / (1 − 20/100) = 120 km.'},
  {_id:15,q:'Si el precio de un producto fuera 25% menor al actual, costaría 90 soles. ¿Cuál es el precio actual?',a:'120 soles',opts:_i4gshuf(['120 soles','90 soles','145 soles','95 soles']),mc:true,ste:'90 = N(1 − 25/100) → N = 90 / (1 − 25/100) = 120 soles.'},
  {_id:16,q:'Si un poste midiera 10% menos de lo que mide, mediría 108 cm. ¿Cuánto mide el poste actualmente?',a:'120 cm',opts:_i4gshuf(['120 cm','108 cm','130 cm','110 cm']),mc:true,ste:'108 = N(1 − 10/100) → N = 108 / (1 − 10/100) = 120 cm.'},
  {_id:17,q:'Un vendedor, por comprar cierto número de lapiceros al por mayor, recibe de regalo un 4% de lo comprado, obteniendo así 260 lapiceros en total. ¿Cuántos lapiceros compró?',a:'250',opts:_i4gshuf(['250','260','275','225']),mc:true,ste:'N(1 + 4/100) = 260 → N = 260 / (1 + 4/100) = 250.'},
  {_id:18,q:'Un vendedor, por comprar cierto número de cuadernos al por mayor, recibe de regalo un 6% de lo comprado, obteniendo así 318 cuadernos en total. ¿Cuántos cuadernos compró?',a:'300',opts:_i4gshuf(['300','318','325','275']),mc:true,ste:'N(1 + 6/100) = 318 → N = 318 / (1 + 6/100) = 300.'},
  {_id:19,q:'Un vendedor, por comprar cierto número de galletas al por mayor, recibe de regalo un 12% de lo comprado, obteniendo así 336 galletas en total. ¿Cuántos galletas compró?',a:'300',opts:_i4gshuf(['300','336','325','275']),mc:true,ste:'N(1 + 12/100) = 336 → N = 336 / (1 + 12/100) = 300.'},
  {_id:20,q:'Un vendedor, por comprar cierto número de caramelos al por mayor, recibe de regalo un 25% de lo comprado, obteniendo así 500 caramelos en total. ¿Cuántos caramelos compró?',a:'400',opts:_i4gshuf(['400','500','425','375']),mc:true,ste:'N(1 + 25/100) = 500 → N = 500 / (1 + 25/100) = 400.'},
  ]);
}
_SKILL_META['svr3ar_b5']={ico:'💯',lbl:'Problemas verbales de porcentaje (edades, compras, regalos)',qCount:4,gen:_genSVR3AR_B5,plantillas:["Edad actual a partir de una reducción porcentual (\'si tuviera P% menos, tendría...\')", "Cantidad comprada a partir de un regalo/bonificación porcentual sobre lo comprado", "V/F sobre el planteamiento correcto del problema verbal", "Variante de P1 con otro contexto (peso, distancia, precio, altura)", "Variante de P2 con otro artículo"]};

function _genSVR3AR_B6(){
  return _i4gpick([
  {_id:1,q:'Si el largo de un rectángulo aumenta en 10% y el ancho disminuye en 10%, ¿cómo varía su área?',a:'-1%',opts:_i4gshuf(['-1%','0%','+1%','+5%']),mc:true,ste:'Factor de variación = (1 + 10/100) × (1 - 10/100) − 1 = -1%.'},
  {_id:2,q:'Si el largo de un rectángulo aumenta en 20% y el ancho disminuye en 20%, ¿cómo varía su área?',a:'-4%',opts:_i4gshuf(['-4%','0%','+4%','+5%']),mc:true,ste:'Factor de variación = (1 + 20/100) × (1 - 20/100) − 1 = -4%.'},
  {_id:3,q:'Si el largo de un rectángulo aumenta en 30% y el ancho disminuye en 10%, ¿cómo varía su área?',a:'+17%',opts:_i4gshuf(['+17%','0%','+20%','-17%']),mc:true,ste:'Factor de variación = (1 + 30/100) × (1 - 10/100) − 1 = +17%.'},
  {_id:4,q:'Si el largo de un rectángulo aumenta en 10% y el ancho disminuye en 30%, ¿cómo varía su área?',a:'-23%',opts:_i4gshuf(['-23%','0%','-20%','+23%']),mc:true,ste:'Factor de variación = (1 + 10/100) × (1 - 30/100) − 1 = -23%.'},
  {_id:5,q:'Si el lado de un cuadrado aumenta en 20%, ¿cómo varía el área de dicho cuadrado?',a:'+44%',opts:_i4gshuf(['+44%','+40%','-44%','+20%']),mc:true,ste:'Factor de variación = (1 + 20/100)² − 1 = +44%.'},
  {_id:6,q:'Si el lado de un cuadrado disminuye en 20%, ¿cómo varía el área de dicho cuadrado?',a:'-36%',opts:_i4gshuf(['-36%','-40%','+36%','-20%']),mc:true,ste:'Factor de variación = (1 - 20/100)² − 1 = -36%.'},
  {_id:7,q:'Si el lado de un cuadrado aumenta en 50%, ¿cómo varía el área de dicho cuadrado?',a:'+125%',opts:_i4gshuf(['+125%','+100%','-125%','+50%']),mc:true,ste:'Factor de variación = (1 + 50/100)² − 1 = +125%.'},
  {_id:8,q:'Si el lado de un cuadrado disminuye en 10%, ¿cómo varía el área de dicho cuadrado?',a:'-19%',opts:_i4gshuf(['-19%','-20%','+19%','-10%']),mc:true,ste:'Factor de variación = (1 - 10/100)² − 1 = -19%.'},
  {_id:9,q:'V/F: Si el largo de un rectángulo aumenta 10% y el ancho disminuye 10%, el área NO varía (0%).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el factor es (1+10/100)(1−10/100) = 1 − 1/100, es decir, el área DISMINUYE 1%, no se mantiene igual.'},
  {_id:10,q:'V/F: Si el lado de un cuadrado aumenta 20%, el área aumenta 44%, no 40%.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: el factor es (1+20/100)² = 1 + 44/100, es decir, +44%; sumar directamente los porcentajes (2×20%=40%) es un error común.'},
  {_id:11,q:'V/F: Para hallar la variación porcentual del área de un cuadrado, basta con multiplicar por 2 el porcentaje de variación del lado.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: como el área depende del cuadrado del lado, el factor correcto es (1 ± p/100)² − 1, que NO es simplemente 2p%.'},
  {_id:12,q:'V/F: Si dos lados de un rectángulo cambian en porcentajes opuestos pero de igual magnitud (por ejemplo +p% y −p%), el área siempre disminuye.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: (1+p/100)(1−p/100) = 1 − (p/100)², que siempre es menor que 1, así que el área siempre disminuye (salvo p=0).'},
  {_id:13,q:'Si el largo de un rectángulo aumenta en 25% y el ancho disminuye en 25%, ¿cómo varía su área?',a:'-6.25%',opts:_i4gshuf(['-6.25%','0%','+6.25%','+7%']),mc:true,ste:'Factor de variación = (1 + 25/100) × (1 - 25/100) − 1 = -6.25%.'},
  {_id:14,q:'Si el largo de un rectángulo aumenta en 40% y el ancho disminuye en 20%, ¿cómo varía su área?',a:'+12%',opts:_i4gshuf(['+12%','+20%','-12%','0%']),mc:true,ste:'Factor de variación = (1 + 40/100) × (1 - 20/100) − 1 = +12%.'},
  {_id:15,q:'Si el largo de un rectángulo aumenta en 15% y el ancho disminuye en 15%, ¿cómo varía su área?',a:'-2.25%',opts:_i4gshuf(['-2.25%','0%','+2.25%','+7%']),mc:true,ste:'Factor de variación = (1 + 15/100) × (1 - 15/100) − 1 = -2.25%.'},
  {_id:16,q:'Si el largo de un rectángulo aumenta en 50% y el ancho disminuye en 50%, ¿cómo varía su área?',a:'-25%',opts:_i4gshuf(['-25%','0%','+25%','+7%']),mc:true,ste:'Factor de variación = (1 + 50/100) × (1 - 50/100) − 1 = -25%.'},
  {_id:17,q:'Si el lado de un cuadrado aumenta en 30%, ¿cómo varía el área de dicho cuadrado?',a:'+69%',opts:_i4gshuf(['+69%','+60%','-69%','+30%']),mc:true,ste:'Factor de variación = (1 + 30/100)² − 1 = +69%.'},
  {_id:18,q:'Si el lado de un cuadrado disminuye en 30%, ¿cómo varía el área de dicho cuadrado?',a:'-51%',opts:_i4gshuf(['-51%','-60%','+51%','-30%']),mc:true,ste:'Factor de variación = (1 - 30/100)² − 1 = -51%.'},
  {_id:19,q:'Si el lado de un cuadrado aumenta en 10%, ¿cómo varía el área de dicho cuadrado?',a:'+21%',opts:_i4gshuf(['+21%','+20%','-21%','+10%']),mc:true,ste:'Factor de variación = (1 + 10/100)² − 1 = +21%.'},
  {_id:20,q:'Si el lado de un cuadrado aumenta en 60%, ¿cómo varía el área de dicho cuadrado?',a:'+156%',opts:_i4gshuf(['+156%','+120%','-156%','+60%']),mc:true,ste:'Factor de variación = (1 + 60/100)² − 1 = +156%.'},
  ]);
}
_SKILL_META['svr3ar_b6']={ico:'💯',lbl:'Variación porcentual de áreas (rectángulo y cuadrado)',qCount:4,gen:_genSVR3AR_B6,plantillas:["Rectángulo: un lado aumenta P%, el otro disminuye Q%; hallar la variación del área", "Cuadrado: el lado aumenta o disminuye P%; hallar la variación del área", "V/F sobre la fórmula/procedimiento de variación porcentual de área", "Variante de rectángulo con otros porcentajes", "Variante de cuadrado con otros porcentajes"]};

