function _genInn5mNP_B5(){
  return _i4gpick([
  {_id:1,q:'V/F: Todo número primo es impar, excepto el 2.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: el 2 es el único primo par; todos los demás primos son impares.'},
  {_id:2,q:'V/F: El número 2 es el único número primo par.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: cualquier otro número par mayor que 2 es divisible entre 2 y por sí mismo, es decir, compuesto.'},
  {_id:3,q:'V/F: Todos los números primos son impares.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el 2 es primo y es par.'},
  {_id:4,q:'V/F: No existe ningún número primo que sea par.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el 2 es primo y es par.'},
  {_id:5,q:'V/F: Los únicos dos números primos consecutivos son 2 y 3.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: a partir de 3, entre dos primos consecutivos siempre hay al menos un número par (no primo, salvo el 2).'},
  {_id:6,q:'V/F: 5 y 7 son números primos consecutivos (uno después del otro sin ningún número entre ellos).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: entre 5 y 7 está el 6, por lo que no son consecutivos como enteros; el único par de primos consecutivos como enteros es 2 y 3.'},
  {_id:7,q:'V/F: No existen dos números primos que sean enteros consecutivos, excepto el par (2, 3).',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: 2 y 3 son los únicos primos consecutivos como números enteros.'},
  {_id:8,q:'V/F: 3 y 5 son números primos consecutivos (enteros consecutivos).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: entre 3 y 5 está el 4; no son enteros consecutivos.'},
  {_id:9,q:'V/F: El número 5 se puede expresar de la forma (4̊+1) o (4̊−1).',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: 5 = 4×1+1, y todo primo mayor que 2 tiene esta forma.'},
  {_id:10,q:'V/F: El número 3 se puede expresar de la forma (4̊+1) o (4̊−1).',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: 3 = 4×1−1, y todo primo mayor que 2 tiene esta forma.'},
  {_id:11,q:'V/F: El número 7 se puede expresar de la forma (4̊+1) o (4̊−1).',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: 7 = 4×2−1, y todo primo mayor que 2 tiene esta forma.'},
  {_id:12,q:'V/F: El número 9 se puede expresar de la forma (4̊+1) o (4̊−1), y por lo tanto es primo.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: 9 = 4×2+1 sí tiene la forma, pero 9 = 3×3 es compuesto; la propiedad dice que todo primo (mayor que 2) tiene esa forma, no que todo número con esa forma sea primo.'},
  {_id:13,q:'V/F: La cantidad de números primos es ilimitada (infinita).',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: no existe un primo mayor que todos los demás; la sucesión de primos es infinita.'},
  {_id:14,q:'V/F: Existe una fórmula que permite generar todos los números primos.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: hasta la actualidad no existe una fórmula conocida que genere todos los números primos.'},
  {_id:15,q:'V/F: El conjunto de los números primos tiene un último elemento (el primo más grande posible).',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: la sucesión de primos no tiene fin, es ilimitada.'},
  {_id:16,q:'V/F: No existe un número primo que sea el mayor de todos.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: la sucesión de primos es ilimitada, por lo tanto no hay un primo \'máximo\'.'},
  {_id:17,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) Todos los números primos son impares.<br>B) El 2 es el único número primo par.<br>C) 2 y 3 no son primos consecutivos.<br>D) La cantidad de números primos es limitada.',a:'El 2 es el único número primo par.',opts:_i4gshuf(['Todos los números primos son impares.','El 2 es el único número primo par.','2 y 3 no son primos consecutivos.','La cantidad de números primos es limitada.']),mc:true,ste:'"El 2 es el único número primo par." es la única afirmación verdadera del grupo.'},
  {_id:18,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) 9 es un número primo.<br>B) Los únicos primos consecutivos son 2 y 3.<br>C) Todo número impar es primo.<br>D) 1 es un número primo.',a:'Los únicos primos consecutivos son 2 y 3.',opts:_i4gshuf(['9 es un número primo.','Los únicos primos consecutivos son 2 y 3.','Todo número impar es primo.','1 es un número primo.']),mc:true,ste:'"Los únicos primos consecutivos son 2 y 3." es la única afirmación verdadera del grupo.'},
  {_id:19,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) 15 es primo absoluto.<br>B) Existe una fórmula que genera todos los primos.<br>C) La sucesión de números primos es ilimitada.<br>D) El número 4 es primo.',a:'La sucesión de números primos es ilimitada.',opts:_i4gshuf(['15 es primo absoluto.','Existe una fórmula que genera todos los primos.','La sucesión de números primos es ilimitada.','El número 4 es primo.']),mc:true,ste:'"La sucesión de números primos es ilimitada." es la única afirmación verdadera del grupo.'},
  {_id:20,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) El 2 es un número compuesto.<br>B) 21 es un número primo.<br>C) El 1 tiene dos divisores.<br>D) El 2 es el único primo que es par.',a:'El 2 es el único primo que es par.',opts:_i4gshuf(['El 2 es un número compuesto.','21 es un número primo.','El 1 tiene dos divisores.','El 2 es el único primo que es par.']),mc:true,ste:'"El 2 es el único primo que es par." es la única afirmación verdadera del grupo.'},
  ]);
}
