_SKILL_META['jb2g_lnt_b4']={ico:'🖼',lbl:'Mediatriz: equidistancia en triángulo isósceles',qCount:4,gen:_genJB2gLNT_B4,plantillas:["Dado PB, hallar PC (equidistancia)", "Ecuación algebraica PB=PC, hallar x", "Dado x, hallar la longitud común de PB y PC", "V/F sobre la propiedad de la mediatriz", "Identificar el valor correcto de PC entre 4 opciones"]};

function _genJB2gLNT_B5(){
  return _i4gpick([
  {_id:1,q:'Un segmento que divide un ángulo interior de un triángulo en dos ángulos de igual medida se llama ¿cuál línea notable es?',a:'Bisectriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Bisectriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:2,q:'El segmento trazado desde un vértice que biseca el ángulo interior correspondiente, dividiéndolo en dos partes congruentes, se llama ¿cuál línea notable es?',a:'Bisectriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Bisectriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:3,q:'Aquella línea notable de un triángulo que corta un ángulo interior en dos ángulos iguales recibe el nombre de ¿cuál línea notable es?',a:'Bisectriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Bisectriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:4,q:'Se llama así al segmento que parte de un vértice y forma dos ángulos congruentes con los lados que concurren en él: ¿cuál línea notable es?',a:'Bisectriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Bisectriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:5,q:'Un segmento que une un vértice de un triángulo con el punto medio del lado opuesto se llama ¿cuál línea notable es?',a:'Mediana',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediana" es la línea notable que corresponde a la descripción dada.'},
  {_id:6,q:'La línea notable que va desde un vértice hasta el punto medio del lado opuesto, y cuya intersección con las otras dos forma el baricentro, se llama ¿cuál línea notable es?',a:'Mediana',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediana" es la línea notable que corresponde a la descripción dada.'},
  {_id:7,q:'Aquel segmento que conecta un vértice con el punto medio del lado que no lo contiene recibe el nombre de ¿cuál línea notable es?',a:'Mediana',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediana" es la línea notable que corresponde a la descripción dada.'},
  {_id:8,q:'Se llama así al segmento trazado desde un vértice hacia el punto medio del lado opuesto: ¿cuál línea notable es?',a:'Mediana',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediana" es la línea notable que corresponde a la descripción dada.'},
  {_id:9,q:'Un segmento perpendicular a un lado de un triángulo, trazado por su punto medio, se llama ¿cuál línea notable es?',a:'Mediatriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediatriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:10,q:'La línea notable que es perpendicular a un lado y pasa exactamente por su punto medio (sin necesariamente pasar por un vértice) se llama ¿cuál línea notable es?',a:'Mediatriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediatriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:11,q:'Aquella recta perpendicular a un lado del triángulo, que lo corta en su punto medio, recibe el nombre de ¿cuál línea notable es?',a:'Mediatriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediatriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:12,q:'Se llama así a la recta que corta perpendicularmente a un lado del triángulo justo en su punto medio: ¿cuál línea notable es?',a:'Mediatriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediatriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:13,q:'V/F: Un segmento que biseca un ángulo interior de un triángulo es una bisectriz.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: esa es exactamente la definición de bisectriz.'},
  {_id:14,q:'V/F: Un segmento que une un vértice con el punto medio del lado opuesto se llama mediatriz.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: esa es la definición de mediana, no de mediatriz.'},
  {_id:15,q:'V/F: La mediatriz de un lado siempre pasa por el vértice opuesto a ese lado.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: eso describe a la mediana; la mediatriz solo pasa por el punto medio del lado, de forma perpendicular, sin necesariamente pasar por el vértice opuesto.'},
  {_id:16,q:'V/F: Las tres medianas de un triángulo se intersecan en el baricentro.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: el punto de intersección de las tres medianas se llama baricentro.'},
  {_id:17,q:'¿Cuál de las siguientes líneas notables divide un ángulo interior en dos partes congruentes?',a:'Bisectriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Bisectriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:18,q:'¿Cuál de las siguientes líneas notables une un vértice con el punto medio del lado opuesto?',a:'Mediana',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediana" es la línea notable que corresponde a la descripción dada.'},
  {_id:19,q:'¿Cuál de las siguientes líneas notables es perpendicular a un lado y pasa por su punto medio?',a:'Mediatriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediatriz" es la línea notable que corresponde a la descripción dada.'},
  {_id:20,q:'¿Cuál de las siguientes líneas notables NO necesariamente pasa por un vértice del triángulo?',a:'Mediatriz',opts:_i4gshuf(['Bisectriz','Mediana','Mediatriz','Altura']),mc:true,ste:'"Mediatriz" es la línea notable que corresponde a la descripción dada.'},
  ]);
}
