function _genJB2gREP_B2(){
  return _i4gpick([
  {_id:1,q:'Halla el complemento de un ángulo que mide 35°',a:'55°',opts:_i4gshuf(['55°','145°','60°','50°']),mc:true,ste:'Complemento = 90° − 35° = 55°.'},
  {_id:2,q:'Halla el complemento de un ángulo que mide 62°',a:'28°',opts:_i4gshuf(['28°','118°','33°','23°']),mc:true,ste:'Complemento = 90° − 62° = 28°.'},
  {_id:3,q:'Halla el complemento de un ángulo que mide 18°',a:'72°',opts:_i4gshuf(['72°','162°','77°','67°']),mc:true,ste:'Complemento = 90° − 18° = 72°.'},
  {_id:4,q:'Halla el complemento de un ángulo que mide 74°',a:'16°',opts:_i4gshuf(['16°','106°','21°','11°']),mc:true,ste:'Complemento = 90° − 74° = 16°.'},
  {_id:5,q:'Halla el suplemento de un ángulo que mide 65°',a:'115°',opts:_i4gshuf(['115°','25°','123°','107°']),mc:true,ste:'Suplemento = 180° − 65° = 115°.'},
  {_id:6,q:'Halla el suplemento de un ángulo que mide 112°',a:'68°',opts:_i4gshuf(['68°','75°','76°','60°']),mc:true,ste:'Suplemento = 180° − 112° = 68°.'},
  {_id:7,q:'Halla el suplemento de un ángulo que mide 38°',a:'142°',opts:_i4gshuf(['142°','52°','150°','134°']),mc:true,ste:'Suplemento = 180° − 38° = 142°.'},
  {_id:8,q:'Halla el suplemento de un ángulo que mide 149°',a:'31°',opts:_i4gshuf(['31°','38°','39°','23°']),mc:true,ste:'Suplemento = 180° − 149° = 31°.'},
  {_id:9,q:'Halla la suma entre el complemento de 75° y el suplemento de 173°',a:'22°',opts:_i4gshuf(['22°','15°','7°','28°']),mc:true,ste:'Complemento de 75° = 90−75 = 15°. Suplemento de 173° = 180−173 = 7°. Suma = 15+7 = 22°.'},
  {_id:10,q:'Halla la suma entre el complemento de 42° y el suplemento de 158°',a:'70°',opts:_i4gshuf(['70°','48°','22°','76°']),mc:true,ste:'Complemento de 42° = 90−42 = 48°. Suplemento de 158° = 180−158 = 22°. Suma = 48+22 = 70°.'},
  {_id:11,q:'Halla la suma entre el complemento de 60° y el suplemento de 140°',a:'70°',opts:_i4gshuf(['70°','30°','40°','76°']),mc:true,ste:'Complemento de 60° = 90−60 = 30°. Suplemento de 140° = 180−140 = 40°. Suma = 30+40 = 70°.'},
  {_id:12,q:'Halla la suma entre el complemento de 28° y el suplemento de 165°',a:'77°',opts:_i4gshuf(['77°','62°','15°','83°']),mc:true,ste:'Complemento de 28° = 90−28 = 62°. Suplemento de 165° = 180−165 = 15°. Suma = 62+15 = 77°.'},
  {_id:13,q:'V/F: Dos ángulos son complementarios si su suma es igual a 90°.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: esa es la definición de ángulos complementarios.'},
  {_id:14,q:'V/F: Dos ángulos son suplementarios si su suma es igual a 180°.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: esa es la definición de ángulos suplementarios.'},
  {_id:15,q:'V/F: El complemento de un ángulo de 100° es 10°.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: un ángulo de 100° no tiene complemento, ya que el complemento requiere que el ángulo sea menor de 90°.'},
  {_id:16,q:'V/F: El suplemento de un ángulo de 30° es 60°.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el suplemento de 30° es 180−30 = 150°, no 60° (60° sería el complemento).'},
  {_id:17,q:'¿Cuál es el valor correcto de la suma entre el complemento de 68° y el suplemento de 151°?',a:'51°',opts:_i4gshuf(['51°','22°','29°','56°']),mc:true,ste:'Complemento de 68° = 22°. Suplemento de 151° = 29°. Suma = 51°.'},
  {_id:18,q:'¿Cuál es el valor correcto de la suma entre el complemento de 55° y el suplemento de 134°?',a:'81°',opts:_i4gshuf(['81°','35°','46°','86°']),mc:true,ste:'Complemento de 55° = 35°. Suplemento de 134° = 46°. Suma = 81°.'},
  {_id:19,q:'¿Cuál es el valor correcto de la suma entre el complemento de 81° y el suplemento de 177°?',a:'12°',opts:_i4gshuf(['12°','9°','3°','17°']),mc:true,ste:'Complemento de 81° = 9°. Suplemento de 177° = 3°. Suma = 12°.'},
  {_id:20,q:'¿Cuál es el valor correcto de la suma entre el complemento de 24° y el suplemento de 163°?',a:'83°',opts:_i4gshuf(['83°','66°','17°','88°']),mc:true,ste:'Complemento de 24° = 66°. Suplemento de 163° = 17°. Suma = 83°.'},
  ]);
}
