function _genJB2gREP_B5(){
  return _i4gpick([
  {_id:1,q:'(Repaso) A, B, C, D son colineales y consecutivos, B es punto medio de AC. Si AB=17 u y CD=9 u, halla AD',a:'43 u',opts:_i4gshuf(['43 u','26 u','48 u','38 u']),mc:true,ste:'AC=2×17=34 u. AD=AC+CD=34+9=43 u.'},
  {_id:2,q:'(Repaso) A, B, C, D son colineales y consecutivos, B es punto medio de AC. Si AB=24 u y CD=11 u, halla AD',a:'59 u',opts:_i4gshuf(['59 u','35 u','64 u','54 u']),mc:true,ste:'AC=2×24=48 u. AD=AC+CD=48+11=59 u.'},
  {_id:3,q:'(Repaso) A, B, C, D son colineales y consecutivos, B es punto medio de AC. Si AB=14 u y CD=16 u, halla AD',a:'44 u',opts:_i4gshuf(['44 u','30 u','49 u','39 u']),mc:true,ste:'AC=2×14=28 u. AD=AC+CD=28+16=44 u.'},
  {_id:4,q:'(Repaso) A, B, C, D son colineales y consecutivos, B es punto medio de AC. Si AB=21 u y CD=5 u, halla AD',a:'47 u',opts:_i4gshuf(['47 u','26 u','52 u','42 u']),mc:true,ste:'AC=2×21=42 u. AD=AC+CD=42+5=47 u.'},
  {_id:5,q:'(Repaso) Halla la suma entre el complemento de 72° y el suplemento de 168°',a:'30°',opts:_i4gshuf(['30°','18°','12°','36°']),mc:true,ste:'Complemento de 72°=18°. Suplemento de 168°=12°. Suma=30°.'},
  {_id:6,q:'(Repaso) Halla la suma entre el complemento de 48° y el suplemento de 155°',a:'67°',opts:_i4gshuf(['67°','42°','25°','73°']),mc:true,ste:'Complemento de 48°=42°. Suplemento de 155°=25°. Suma=67°.'},
  {_id:7,q:'(Repaso) Halla la suma entre el complemento de 65° y el suplemento de 142°',a:'63°',opts:_i4gshuf(['63°','25°','38°','69°']),mc:true,ste:'Complemento de 65°=25°. Suplemento de 142°=38°. Suma=63°.'},
  {_id:8,q:'(Repaso) Halla la suma entre el complemento de 33° y el suplemento de 171°',a:'66°',opts:_i4gshuf(['66°','57°','9°','72°']),mc:true,ste:'Complemento de 33°=57°. Suplemento de 171°=9°. Suma=66°.'},
  {_id:9,q:'(Repaso) Expresa 50ᵍ en el sistema sexagesimal',a:'45°',opts:_i4gshuf(['45°','50°','54°','36°']),mc:true,ste:'50ᵍ × 9/10 = 45°.'},
  {_id:10,q:'(Repaso) Expresa 30ᵍ en el sistema sexagesimal',a:'27°',opts:_i4gshuf(['27°','30°','36°','18°']),mc:true,ste:'30ᵍ × 9/10 = 27°.'},
  {_id:11,q:'(Repaso) Expresa 70ᵍ en el sistema sexagesimal',a:'63°',opts:_i4gshuf(['63°','70°','72°','54°']),mc:true,ste:'70ᵍ × 9/10 = 63°.'},
  {_id:12,q:'(Repaso) Expresa 90ᵍ en el sistema sexagesimal',a:'81°',opts:_i4gshuf(['81°','90°','72°','99°']),mc:true,ste:'90ᵍ × 9/10 = 81°.'},
  {_id:13,q:'(Repaso) Si L1 // L2 y una secante forma un ángulo de 58° con L1, halla el ángulo conjugado interno correspondiente en L2',a:'122°',opts:_i4gshuf(['122°','58°','130°','114°']),mc:true,ste:'180° − 58° = 122°.'},
  {_id:14,q:'(Repaso) Si L1 // L2 y una secante forma un ángulo de 77° con L1, halla el ángulo conjugado interno correspondiente en L2',a:'103°',opts:_i4gshuf(['103°','77°','111°','95°']),mc:true,ste:'180° − 77° = 103°.'},
  {_id:15,q:'(Repaso) Si L1 // L2 y una secante forma un ángulo de 41° con L1, halla el ángulo conjugado interno correspondiente en L2',a:'139°',opts:_i4gshuf(['139°','41°','147°','131°']),mc:true,ste:'180° − 41° = 139°.'},
  {_id:16,q:'(Repaso) Si L1 // L2 y una secante forma un ángulo de 94° con L1, halla el ángulo conjugado interno correspondiente en L2',a:'86°',opts:_i4gshuf(['86°','94°','78°','102°']),mc:true,ste:'180° − 94° = 86°.'},
  {_id:17,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) Si B es punto medio de AC y AB=18, entonces AC=36.<br>B) El complemento de 50° es 50°.<br>C) 100ᵍ equivale a 100° en el sistema sexagesimal.<br>D) Los ángulos correspondientes entre paralelas son suplementarios.',a:'Si B es punto medio de AC y AB=18, entonces AC=36.',opts:_i4gshuf(['Si B es punto medio de AC y AB=18, entonces AC=36.','El complemento de 50° es 50°.','100ᵍ equivale a 100° en el sistema sexagesimal.','Los ángulos correspondientes entre paralelas son suplementarios.']),mc:true,ste:'"Si B es punto medio de AC y AB=18, entonces AC=36." es la única afirmación verdadera del grupo.'},
  {_id:18,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) Si AB=BC=15, entonces B no es punto medio de AC.<br>B) El suplemento de 110° es 70°.<br>C) 1ᵍ equivale exactamente a 1°.<br>D) Los ángulos alternos internos entre paralelas son suplementarios.',a:'El suplemento de 110° es 70°.',opts:_i4gshuf(['Si AB=BC=15, entonces B no es punto medio de AC.','El suplemento de 110° es 70°.','1ᵍ equivale exactamente a 1°.','Los ángulos alternos internos entre paralelas son suplementarios.']),mc:true,ste:'"El suplemento de 110° es 70°." es la única afirmación verdadera del grupo.'},
  {_id:19,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) Si B es punto medio de AC y AC=50, entonces AB=20.<br>B) La suma del complemento de 80° y el suplemento de 80° es 110°.<br>C) 170° equivale a 200ᵍ en el sistema centesimal.<br>D) Los ángulos conjugados internos entre paralelas son congruentes.',a:'La suma del complemento de 80° y el suplemento de 80° es 110°.',opts:_i4gshuf(['Si B es punto medio de AC y AC=50, entonces AB=20.','La suma del complemento de 80° y el suplemento de 80° es 110°.','170° equivale a 200ᵍ en el sistema centesimal.','Los ángulos conjugados internos entre paralelas son congruentes.']),mc:true,ste:'"La suma del complemento de 80° y el suplemento de 80° es 110°." es la única afirmación verdadera del grupo.'},
  {_id:20,q:'¿Cuál de las siguientes afirmaciones es verdadera?<br>A) Si B es punto medio de AC y AB=22, entonces BC=22.<br>B) Un ángulo de 95° tiene complemento, ya que 95°<90°.<br>C) 40ᵍ equivale a 40° exactamente en el sistema sexagesimal.<br>D) Los ángulos conjugados internos entre paralelas cortadas por una secante son congruentes.',a:'Si B es punto medio de AC y AB=22, entonces BC=22.',opts:_i4gshuf(['Si B es punto medio de AC y AB=22, entonces BC=22.','Un ángulo de 95° tiene complemento, ya que 95°<90°.','40ᵍ equivale a 40° exactamente en el sistema sexagesimal.','Los ángulos conjugados internos entre paralelas cortadas por una secante son congruentes.']),mc:true,ste:'"Si B es punto medio de AC y AB=22, entonces BC=22." es la única afirmación verdadera del grupo.'},
  ]);
}
