function _genI1trSma_B1(){
  return _i4gpick([
  {_id:1,q:'Convierte 80° a radianes.',a:'4π/9 rad',opts:_i4gshuf(['4π/9 rad','16π/27 rad','8π/27 rad','8π/9 rad']),mc:true,ste:'R = 80°×(π/180°) = 4π/9 rad.'},
  {_id:2,q:'Convierte 160° a radianes.',a:'8π/9 rad',opts:_i4gshuf(['8π/9 rad','32π/27 rad','16π/27 rad','16π/9 rad']),mc:true,ste:'R = 160°×(π/180°) = 8π/9 rad.'},
  {_id:3,q:'Convierte 54° a radianes.',a:'3π/10 rad',opts:_i4gshuf(['3π/10 rad','2π/5 rad','π/5 rad','3π/5 rad']),mc:true,ste:'R = 54°×(π/180°) = 3π/10 rad.'},
  {_id:4,q:'Convierte 108° a radianes.',a:'3π/5 rad',opts:_i4gshuf(['3π/5 rad','4π/5 rad','2π/5 rad','6π/5 rad']),mc:true,ste:'R = 108°×(π/180°) = 3π/5 rad.'},
  {_id:5,q:'Convierte 40ᵍ a radianes.',a:'π/5 rad',opts:_i4gshuf(['π/5 rad','π/4 rad','3π/20 rad','2π/5 rad']),mc:true,ste:'R = 40ᵍ×(π/200ᵍ) = π/5 rad.'},
  {_id:6,q:'Convierte 60ᵍ a radianes.',a:'3π/10 rad',opts:_i4gshuf(['3π/10 rad','3π/8 rad','9π/40 rad','3π/5 rad']),mc:true,ste:'R = 60ᵍ×(π/200ᵍ) = 3π/10 rad.'},
  {_id:7,q:'Convierte 120ᵍ a radianes.',a:'3π/5 rad',opts:_i4gshuf(['3π/5 rad','3π/4 rad','9π/20 rad','6π/5 rad']),mc:true,ste:'R = 120ᵍ×(π/200ᵍ) = 3π/5 rad.'},
  {_id:8,q:'Convierte 150ᵍ a radianes.',a:'3π/4 rad',opts:_i4gshuf(['3π/4 rad','15π/16 rad','9π/16 rad','3π/2 rad']),mc:true,ste:'R = 150ᵍ×(π/200ᵍ) = 3π/4 rad.'},
  {_id:9,q:'Convierte π/6 rad a grados sexagesimales.',a:'30°',opts:_i4gshuf(['30°','40°','20°','15°']),mc:true,ste:'D = (π/6 rad)×(180°/π) = 30°.'},
  {_id:10,q:'Convierte 2π/5 rad a grados sexagesimales.',a:'72°',opts:_i4gshuf(['72°','82°','62°','36°']),mc:true,ste:'D = (2π/5 rad)×(180°/π) = 72°.'},
  {_id:11,q:'Convierte 3π/4 rad a grados sexagesimales.',a:'135°',opts:_i4gshuf(['135°','145°','125°','135/2°']),mc:true,ste:'D = (3π/4 rad)×(180°/π) = 135°.'},
  {_id:12,q:'Convierte 5π/6 rad a grados sexagesimales.',a:'150°',opts:_i4gshuf(['150°','160°','140°','75°']),mc:true,ste:'D = (5π/6 rad)×(180°/π) = 150°.'},
  {_id:13,q:'Convierte 45° a grados centesimales.',a:'50ᵍ',opts:_i4gshuf(['50ᵍ','58ᵍ','42ᵍ','45ᵍ']),mc:true,ste:'C = 45°×(200ᵍ/180°) = 50ᵍ.'},
  {_id:14,q:'Convierte 100ᵍ a grados sexagesimales.',a:'90°',opts:_i4gshuf(['90°','98°','82°','100°']),mc:true,ste:'D = 100ᵍ×(180°/200ᵍ) = 90°.'},
  {_id:15,q:'Convierte 72° a grados centesimales.',a:'80ᵍ',opts:_i4gshuf(['80ᵍ','88ᵍ','72ᵍ','75ᵍ']),mc:true,ste:'C = 72°×(200ᵍ/180°) = 80ᵍ.'},
  {_id:16,q:'Convierte 150ᵍ a grados sexagesimales.',a:'135°',opts:_i4gshuf(['135°','143°','127°','150°']),mc:true,ste:'D = 150ᵍ×(180°/200ᵍ) = 135°.'},
  {_id:17,q:'¿Cuál es la conversión correcta de 40° a radianes?',a:'2π/9 rad',opts:_i4gshuf(['2π/9 rad','4π/15 rad','5π/27 rad','4π/9 rad']),mc:true,ste:'R = 40°×(π/180°) = 2π/9 rad.'},
  {_id:18,q:'¿Cuál es la conversión correcta de 200° a radianes?',a:'10π/9 rad',opts:_i4gshuf(['10π/9 rad','4π/3 rad','25π/27 rad','20π/9 rad']),mc:true,ste:'R = 200°×(π/180°) = 10π/9 rad.'},
  {_id:19,q:'¿Cuál es la conversión correcta de 135° a radianes?',a:'3π/4 rad',opts:_i4gshuf(['3π/4 rad','9π/10 rad','5π/8 rad','3π/2 rad']),mc:true,ste:'R = 135°×(π/180°) = 3π/4 rad.'},
  {_id:20,q:'¿Cuál es la conversión correcta de 300° a radianes?',a:'5π/3 rad',opts:_i4gshuf(['5π/3 rad','2π rad','25π/18 rad','10π/3 rad']),mc:true,ste:'R = 300°×(π/180°) = 5π/3 rad.'},
  ]);
}
