function _genI1trSma_B2(){
  return _i4gpick([
  {_id:1,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: J = (S+C)/(C−S)',a:'19',opts:_i4gshuf(['19','20','18','38']),mc:true,ste:'Como S=9k y C=10k para un mismo ángulo, sustituyendo: (S+C)/(C−S) = 19 (independiente de k).'},
  {_id:2,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: J = (2C+3S)/(C−S)',a:'47',opts:_i4gshuf(['47','48','46','94']),mc:true,ste:'Como S=9k y C=10k para un mismo ángulo, sustituyendo: (2C+3S)/(C−S) = 47 (independiente de k).'},
  {_id:3,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: J = (3C−S)/(C−S)',a:'21',opts:_i4gshuf(['21','22','20','42']),mc:true,ste:'Como S=9k y C=10k para un mismo ángulo, sustituyendo: (3C−S)/(C−S) = 21 (independiente de k).'},
  {_id:4,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: J = (S+2C)/(2S−C)',a:'29/8',opts:_i4gshuf(['29/8','37/8','21/8','29/4']),mc:true,ste:'Como S=9k y C=10k para un mismo ángulo, sustituyendo: (S+2C)/(2S−C) = 29/8 (independiente de k).'},
  {_id:5,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: M = (C²−S²)/C²',a:'19/100',opts:_i4gshuf(['19/100','69/100','-3/50','19/50']),mc:true,ste:'Sustituyendo S=9k, C=10k: (C²−S²)/C² = 19/100.'},
  {_id:6,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: M = (C²−S²)/S²',a:'19/81',opts:_i4gshuf(['19/81','119/162','-5/324','38/81']),mc:true,ste:'Sustituyendo S=9k, C=10k: (C²−S²)/S² = 19/81.'},
  {_id:7,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: M = (2C²−2S²)/(C²−S²)',a:'2',opts:_i4gshuf(['2','5/2','7/4','4']),mc:true,ste:'Sustituyendo S=9k, C=10k: (2C²−2S²)/(C²−S²) = 2.'},
  {_id:8,q:'Siendo S y C lo conocido para un ángulo no nulo, reduce: M = (C²+S²)/(C²−S²)',a:'181/19',opts:_i4gshuf(['181/19','381/38','705/76','362/19']),mc:true,ste:'Sustituyendo S=9k, C=10k: (C²+S²)/(C²−S²) = 181/19.'},
  {_id:9,q:'Siendo S, C y R lo conocido para un ángulo no nulo, reduce: A = 60R/(C−S)',a:'3π',opts:_i4gshuf(['3π','4π','6π','7π/2']),mc:true,ste:'Sustituyendo S=9k, C=10k, R=(π/20)k: 60R/(C−S) = 3π.'},
  {_id:10,q:'Siendo S, C y R lo conocido para un ángulo no nulo, reduce: A = 20R/(C−S)',a:'π',opts:_i4gshuf(['π','2π','3π/2','4π']),mc:true,ste:'Sustituyendo S=9k, C=10k, R=(π/20)k: 20R/(C−S) = π.'},
  {_id:11,q:'Siendo S, C y R lo conocido para un ángulo no nulo, reduce: A = 40R/(2C−2S)',a:'π',opts:_i4gshuf(['π','2π','3π/2','4π']),mc:true,ste:'Sustituyendo S=9k, C=10k, R=(π/20)k: 40R/(2C−2S) = π.'},
  {_id:12,q:'Siendo S, C y R lo conocido para un ángulo no nulo, reduce: A = 100R/(C−S)',a:'5π',opts:_i4gshuf(['5π','6π','10π','11π/2']),mc:true,ste:'Sustituyendo S=9k, C=10k, R=(π/20)k: 100R/(C−S) = 5π.'},
  {_id:13,q:'V/F: Si S y C son lo conocido de un mismo ángulo, la expresión (S+C)/(C−S) siempre da el mismo valor numérico, sin importar la medida del ángulo.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: al sustituir S=9k y C=10k, la k se cancela y el resultado es constante.'},
  {_id:14,q:'V/F: La expresión S/C (con S y C del mismo ángulo) depende de qué tan grande sea el ángulo.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: S/C = 9k/10k = 9/10, un valor constante que no depende de k (ni del ángulo).'},
  {_id:15,q:'V/F: Toda expresión homogénea (mismo grado en numerador y denominador) formada con S, C y R de un mismo ángulo se reduce a una constante.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: al ser homogénea, la variable k se cancela al dividir.'},
  {_id:16,q:'V/F: Una expresión como S+C (sin dividir entre otra expresión en S o C) da siempre el mismo valor sin importar el ángulo.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: S+C = 19k depende de k, es decir, del ángulo; sin una división que cancele la k, no es constante.'},
  {_id:17,q:'Siendo S y C lo conocido para un ángulo no nulo, ¿cuál es el valor correcto de la reducción de J = (3C−2S)/(C−S)?',a:'12',opts:_i4gshuf(['12','13','11','24']),mc:true,ste:'Sustituyendo S=9k, C=10k: (3C−2S)/(C−S) = 12.'},
  {_id:18,q:'Siendo S y C lo conocido para un ángulo no nulo, ¿cuál es el valor correcto de la reducción de J = (C+4S)/(2C−S)?',a:'46/11',opts:_i4gshuf(['46/11','57/11','35/11','92/11']),mc:true,ste:'Sustituyendo S=9k, C=10k: (C+4S)/(2C−S) = 46/11.'},
  {_id:19,q:'Siendo S y C lo conocido para un ángulo no nulo, ¿cuál es el valor correcto de la reducción de J = (5C−4S)/(C−S)?',a:'14',opts:_i4gshuf(['14','15','13','28']),mc:true,ste:'Sustituyendo S=9k, C=10k: (5C−4S)/(C−S) = 14.'},
  {_id:20,q:'Siendo S y C lo conocido para un ángulo no nulo, ¿cuál es el valor correcto de la reducción de J = (C−S)/(10S−8C)?',a:'1/10',opts:_i4gshuf(['1/10','11/10','-9/10','1/5']),mc:true,ste:'Sustituyendo S=9k, C=10k: (C−S)/(10S−8C) = 1/10.'},
  ]);
}
_SKILL_META['i1tr_sma_b2']={ico:'📐',lbl:'Reducción de expresiones algebraicas conociendo S y C (o R) de un ángulo',qCount:4,gen:_genI1trSma_B2,plantillas:["Reducir una expresión racional en S y C (mismo ángulo) a un valor numérico", "Reducir una expresión con potencias de S y C", "Reducir una expresión que combina R (radianes) con S y/o C", "V/F sobre la validez de una reducción algebraica S, C, R", "Identificar el valor correcto de la reducción entre 4 opciones"]};

function _genI1trSma_B3(){
  return _i4gpick([
  {_id:1,q:'Un ángulo mide 37° y su complemento es (3x+4)°. ¿Cuál es el valor de x?',a:'16.33',opts:_i4gshuf(['16.33','53','19.33','13.33']),mc:true,ste:'El complemento de 37° es 90−37 = 53°. Entonces 3x+4 = 53 → x = 16.33.'},
  {_id:2,q:'Un ángulo mide 25° y su complemento es (2x+15)°. ¿Cuál es el valor de x?',a:'25',opts:_i4gshuf(['25','65','28','22']),mc:true,ste:'El complemento de 25° es 90−25 = 65°. Entonces 2x+15 = 65 → x = 25.'},
  {_id:3,q:'Un ángulo mide 48° y su complemento es (5x-2)°. ¿Cuál es el valor de x?',a:'8.8',opts:_i4gshuf(['8.8','42','11.8','5.8']),mc:true,ste:'El complemento de 48° es 90−48 = 42°. Entonces 5x-2 = 42 → x = 8.8.'},
  {_id:4,q:'Un ángulo mide 16° y su complemento es (4x+8)°. ¿Cuál es el valor de x?',a:'16.5',opts:_i4gshuf(['16.5','74','19.5','13.5']),mc:true,ste:'El complemento de 16° es 90−16 = 74°. Entonces 4x+8 = 74 → x = 16.5.'},
  {_id:5,q:'Un ángulo mide 70° y su suplemento es (11x+7)°. ¿Cuál es el valor de x?',a:'9.36',opts:_i4gshuf(['9.36','70','11.36','7.36']),mc:true,ste:'El suplemento de 70° es 180−70 = 110°. Entonces 11x+7 = 110 → x = 9.36.'},
  {_id:6,q:'Un ángulo mide 55° y su suplemento es (6x+4)°. ¿Cuál es el valor de x?',a:'20.17',opts:_i4gshuf(['20.17','55','22.17','18.17']),mc:true,ste:'El suplemento de 55° es 180−55 = 125°. Entonces 6x+4 = 125 → x = 20.17.'},
  {_id:7,q:'Un ángulo mide 95° y su suplemento es (7x-3)°. ¿Cuál es el valor de x?',a:'12.57',opts:_i4gshuf(['12.57','95','14.57','10.57']),mc:true,ste:'El suplemento de 95° es 180−95 = 85°. Entonces 7x-3 = 85 → x = 12.57.'},
  {_id:8,q:'Un ángulo mide 120° y su suplemento es (4x+10)°. ¿Cuál es el valor de x?',a:'12.5',opts:_i4gshuf(['12.5','120','14.5','10.5']),mc:true,ste:'El suplemento de 120° es 180−120 = 60°. Entonces 4x+10 = 60 → x = 12.5.'},
  {_id:9,q:'La diferencia de las medidas de dos ángulos complementarios es 10°. ¿Cuál es la medida del ángulo mayor?',a:'50',opts:_i4gshuf(['50','40','55','45']),mc:true,ste:'Sean A y B: A+B=90, A−B=10. Sumando: 2A=90+10 → A=50°.'},
  {_id:10,q:'La diferencia de las medidas de dos ángulos complementarios es 20°. ¿Cuál es la medida del ángulo mayor?',a:'55',opts:_i4gshuf(['55','35','60','50']),mc:true,ste:'Sean A y B: A+B=90, A−B=20. Sumando: 2A=90+20 → A=55°.'},
  {_id:11,q:'La diferencia de las medidas de dos ángulos suplementarios es 30°. ¿Cuál es la medida del ángulo mayor?',a:'105',opts:_i4gshuf(['105','75','110','100']),mc:true,ste:'Sean A y B: A+B=180, A−B=30. Sumando: 2A=180+30 → A=105°.'},
  {_id:12,q:'La diferencia de las medidas de dos ángulos suplementarios es 60°. ¿Cuál es la medida del ángulo mayor?',a:'120',opts:_i4gshuf(['120','60','125','115']),mc:true,ste:'Sean A y B: A+B=180, A−B=60. Sumando: 2A=180+60 → A=120°.'},
  {_id:13,q:'V/F: Dos ángulos son complementarios si la suma de sus medidas es 90°.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: esa es la definición de ángulos complementarios.'},
  {_id:14,q:'V/F: Dos ángulos son suplementarios si la suma de sus medidas es 90°.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: los ángulos suplementarios suman 180°, no 90°.'},
  {_id:15,q:'V/F: El complemento de un ángulo de 40° mide 50°.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: 90−40=50°.'},
  {_id:16,q:'V/F: El suplemento de un ángulo de 110° mide 80°.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el suplemento de 110° es 180−110 = 70°, no 80°.'},
  {_id:17,q:'Un ángulo mide 42° y su complemento es (2x+6)°. ¿Cuál es el valor correcto de x?',a:'21',opts:_i4gshuf(['21','48','25','17']),mc:true,ste:'90−42 = 48 = 2x+6 → x = 21.'},
  {_id:18,q:'Un ángulo mide 33° y su complemento es (5x-1)°. ¿Cuál es el valor correcto de x?',a:'11.6',opts:_i4gshuf(['11.6','57','15.6','7.6']),mc:true,ste:'90−33 = 57 = 5x-1 → x = 11.6.'},
  {_id:19,q:'Un ángulo mide 18° y su complemento es (3x+12)°. ¿Cuál es el valor correcto de x?',a:'20',opts:_i4gshuf(['20','72','24','16']),mc:true,ste:'90−18 = 72 = 3x+12 → x = 20.'},
  {_id:20,q:'Un ángulo mide 61° y su complemento es (7x+4)°. ¿Cuál es el valor correcto de x?',a:'3.57',opts:_i4gshuf(['3.57','29','7.57','-0.43']),mc:true,ste:'90−61 = 29 = 7x+4 → x = 3.57.'},
  ]);
}
_SKILL_META['i1tr_sma_b3']={ico:'📐',lbl:'Ángulos complementarios o suplementarios en distintos sistemas',qCount:4,gen:_genI1trSma_B3,plantillas:["Ángulo en sexagesimales y su complemento con incógnita x: despejar x", "Ángulo en sexagesimales y su suplemento con incógnita x: despejar x", "Diferencia entre dos ángulos complementarios/suplementarios: hallar el mayor", "V/F sobre la propiedad de ángulos complementarios/suplementarios en sistemas mixtos", "Identificar el valor correcto de x entre 4 opciones"]};

