_SKILL_META['i1tr_asc_b6']={ico:'🖼',lbl:'Área del trapecio circular (diferencia de sectores)',qCount:4,gen:_genI1trAsc_B6,plantillas:["Dado R₁, R₂ y θ, hallar el área del trapecio (diferencia de sectores)", "Variante numérica de P1", "Problema tipo con lados etiquetados (como el ejemplo del PDF)", "V/F sobre la fórmula del trapecio circular", "Identificar el valor correcto entre 4 opciones"]};

function _genI1trAsc_B7(){
  return _i4gpick([
  {_id:1,q:'Un sector circular tiene área S. Si su radio se duplica (manteniendo el ángulo central constante), ¿cuál es la nueva área en términos de S?',a:'4S',opts:_i4gshuf(['4S','2S','8S','16S']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 2, el área se multiplica por (2)² → nueva área = 4S.'},
  {_id:2,q:'Un sector circular tiene área S. Si su radio se triplica (manteniendo el ángulo central constante), ¿cuál es la nueva área en términos de S?',a:'9S',opts:_i4gshuf(['9S','3S','18S','27S']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 3, el área se multiplica por (3)² → nueva área = 9S.'},
  {_id:3,q:'Un sector circular tiene área S. Si su radio se reduce a la mitad (manteniendo el ángulo central constante), ¿cuál es la nueva área en términos de S?',a:'S/4',opts:_i4gshuf(['S/4','S/2','S/8','3S/4']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 1/2, el área se multiplica por (1/2)² → nueva área = S/4.'},
  {_id:4,q:'Un sector circular tiene área S. Si su radio se multiplica por 5 (manteniendo el ángulo central constante), ¿cuál es la nueva área en términos de S?',a:'25S',opts:_i4gshuf(['25S','5S','50S','75S']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 5, el área se multiplica por (5)² → nueva área = 25S.'},
  {_id:5,q:'Dos sectores circulares tienen el mismo ángulo central. El radio del segundo es 2 veces el del primero (R₂=2R₁). Calcula S₂/S₁',a:'4',opts:_i4gshuf(['4','2','6','8']),mc:true,ste:'Como S∝R², S₂/S₁=(R₂/R₁)²=(2/1)²=4.'},
  {_id:6,q:'Dos sectores circulares tienen el mismo ángulo central. El radio del segundo es 3 veces el del primero (R₂=3R₁). Calcula S₂/S₁',a:'9',opts:_i4gshuf(['9','3','11','18']),mc:true,ste:'Como S∝R², S₂/S₁=(R₂/R₁)²=(3/1)²=9.'},
  {_id:7,q:'Dos sectores circulares tienen el mismo ángulo central. El radio del segundo es 3/2 veces el del primero (R₂=3/2·R₁). Calcula S₂/S₁',a:'9/4',opts:_i4gshuf(['9/4','1.5','4.25','4.5']),mc:true,ste:'Como S∝R², S₂/S₁=(R₂/R₁)²=(3/2)²=2.25.'},
  {_id:8,q:'Dos sectores circulares tienen el mismo ángulo central. El radio del segundo es 4 veces el del primero (R₂=4R₁). Calcula S₂/S₁',a:'16',opts:_i4gshuf(['16','4','18','32']),mc:true,ste:'Como S∝R², S₂/S₁=(R₂/R₁)²=(4/1)²=16.'},
  {_id:9,q:'¿Cuánto debe medir el radio (en m) de un sector circular para que su área sea numéricamente igual a la longitud de su arco?',a:'2 m',opts:_i4gshuf(['2 m','1 m','3 m','4 m']),mc:true,ste:'S=θR²/2 y L=θR. Igualando S=L: θR²/2=θR → R/2=1 → R=2 m (válido para cualquier θ≠0).'},
  {_id:10,q:'Halla el radio (en m) de un sector circular tal que el valor numérico de su área coincida con el de su arco.',a:'2 m',opts:_i4gshuf(['2 m','1 m','3 m','4 m']),mc:true,ste:'S=θR²/2 y L=θR. Igualando S=L: θR²/2=θR → R/2=1 → R=2 m (válido para cualquier θ≠0).'},
  {_id:11,q:'¿Qué valor debe tener el radio (en m) de un sector circular para que el área y la longitud del arco sean numéricamente iguales?',a:'2 m',opts:_i4gshuf(['2 m','1 m','3 m','4 m']),mc:true,ste:'S=θR²/2 y L=θR. Igualando S=L: θR²/2=θR → R/2=1 → R=2 m (válido para cualquier θ≠0).'},
  {_id:12,q:'Determina el radio (en m) de un sector circular sabiendo que su área es numéricamente igual a la longitud de su arco.',a:'2 m',opts:_i4gshuf(['2 m','1 m','3 m','4 m']),mc:true,ste:'S=θR²/2 y L=θR. Igualando S=L: θR²/2=θR → R/2=1 → R=2 m (válido para cualquier θ≠0).'},
  {_id:13,q:'V/F: Si el ángulo central se mantiene constante, el área de un sector circular es directamente proporcional al cuadrado del radio.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: S=θR²/2, con θ constante, S es proporcional a R².'},
  {_id:14,q:'V/F: Si el radio de un sector circular se triplica (con θ constante), su área también se triplica.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el área se multiplica por 3²=9, no por 3.'},
  {_id:15,q:'V/F: La razón entre las áreas de dos sectores con el mismo ángulo central es igual al cuadrado de la razón entre sus radios.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: S₂/S₁=(R₂/R₁)².'},
  {_id:16,q:'V/F: Si el radio de un sector circular se reduce a la mitad (con θ constante), su área se reduce a la cuarta parte.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: (1/2)²=1/4.'},
  {_id:17,q:'Un sector circular tiene área S. Si su radio se multiplica por 4 (manteniendo el ángulo central constante), ¿cuál es el valor correcto de la nueva área en términos de S?',a:'16S',opts:_i4gshuf(['16S','4S','32S','64S']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 4, el área se multiplica por (4)² → nueva área = 16S.'},
  {_id:18,q:'Un sector circular tiene área S. Si su radio se reduce a la tercera parte (manteniendo el ángulo central constante), ¿cuál es el valor correcto de la nueva área en términos de S?',a:'S/9',opts:_i4gshuf(['S/9','S/3','S/27','2S/9']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 1/3, el área se multiplica por (1/3)² → nueva área = S/9.'},
  {_id:19,q:'Un sector circular tiene área S. Si su radio se multiplica por 6 (manteniendo el ángulo central constante), ¿cuál es el valor correcto de la nueva área en términos de S?',a:'36S',opts:_i4gshuf(['36S','6S','72S','108S']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 6, el área se multiplica por (6)² → nueva área = 36S.'},
  {_id:20,q:'Un sector circular tiene área S. Si su radio se reduce a la cuarta parte (manteniendo el ángulo central constante), ¿cuál es el valor correcto de la nueva área en términos de S?',a:'S/16',opts:_i4gshuf(['S/16','S/4','S/64','3S/16']),mc:true,ste:'Como S=θR²/2, el área es proporcional a R². Si el radio se multiplica por 1/4, el área se multiplica por (1/4)² → nueva área = S/16.'},
  ]);
}
_SKILL_META['i1tr_asc_b7']={ico:'🖼',lbl:'Relación S∝R² (razón entre áreas al variar el radio)',qCount:4,gen:_genI1trAsc_B7,plantillas:["Si se duplica el radio, hallar la nueva área en términos de S", "Dado un factor de escala k del radio, hallar S₂/S₁", "Problema verbal (radio para que S sea numéricamente igual a L)", "V/F sobre la relación S∝R²", "Identificar el valor correcto entre 4 opciones"]};

