function _genI1arNmr_B1(){
  return _i4gpick([
  {_id:1,q:'Convierte 321(base 5) al sistema decimal.',a:'86',opts:_i4gshuf(['86','87','85','91']),mc:true,ste:'321(base 5) = 3×5^2 + 2×5^1 + 1×5^0 = 86.'},
  {_id:2,q:'Convierte 243(base 6) al sistema decimal.',a:'99',opts:_i4gshuf(['99','100','98','105']),mc:true,ste:'243(base 6) = 2×6^2 + 4×6^1 + 3×6^0 = 99.'},
  {_id:3,q:'Convierte 252(base 7) al sistema decimal.',a:'135',opts:_i4gshuf(['135','136','134','142']),mc:true,ste:'252(base 7) = 2×7^2 + 5×7^1 + 2×7^0 = 135.'},
  {_id:4,q:'Convierte 423(base 8) al sistema decimal.',a:'275',opts:_i4gshuf(['275','276','274','283']),mc:true,ste:'423(base 8) = 4×8^2 + 2×8^1 + 3×8^0 = 275.'},
  {_id:5,q:'Convierte 150 al sistema de base 4.',a:'2112',opts:_i4gshuf(['2112','3112','2212','2122']),mc:true,ste:'Dividiendo sucesivamente 150 entre 4, los restos en orden inverso dan: 2112(base 4).'},
  {_id:6,q:'Convierte 200 al sistema de base 6.',a:'532',opts:_i4gshuf(['532','032','542','533']),mc:true,ste:'Dividiendo sucesivamente 200 entre 6, los restos en orden inverso dan: 532(base 6).'},
  {_id:7,q:'Convierte 89 al sistema de base 3.',a:'10022',opts:_i4gshuf(['10022','20022','11022','10122']),mc:true,ste:'Dividiendo sucesivamente 89 entre 3, los restos en orden inverso dan: 10022(base 3).'},
  {_id:8,q:'Convierte 175 al sistema de base 5.',a:'1200',opts:_i4gshuf(['1200','2200','1300','1210']),mc:true,ste:'Dividiendo sucesivamente 175 entre 5, los restos en orden inverso dan: 1200(base 5).'},
  {_id:9,q:'Convierte 342(base 8) al sistema de base 5.',a:'1401',opts:_i4gshuf(['1401','2401','1001','1411']),mc:true,ste:'342(base 8) = 226 en decimal; convirtiendo 226 a base 5 se obtiene 1401(base 5).'},
  {_id:10,q:'Convierte 213(base 6) al sistema de base 4.',a:'1101',opts:_i4gshuf(['1101','2101','1201','1111']),mc:true,ste:'213(base 6) = 81 en decimal; convirtiendo 81 a base 4 se obtiene 1101(base 4).'},
  {_id:11,q:'Convierte 431(base 7) al sistema de base 9.',a:'262',opts:_i4gshuf(['262','362','272','263']),mc:true,ste:'431(base 7) = 218 en decimal; convirtiendo 218 a base 9 se obtiene 262(base 9).'},
  {_id:12,q:'Convierte 152(base 9) al sistema de base 3.',a:'11202',opts:_i4gshuf(['11202','21202','12202','11002']),mc:true,ste:'152(base 9) = 128 en decimal; convirtiendo 128 a base 3 se obtiene 11202(base 3).'},
  {_id:13,q:'V/F: Para convertir un numeral de base n a base decimal, se multiplica cada cifra por la potencia de n correspondiente a su posición y se suma.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: ese es el método de descomposición polinómica para pasar de base n a base 10.'},
  {_id:14,q:'V/F: Para convertir un número decimal a base n, se divide sucesivamente entre n y los restos, leídos de abajo hacia arriba, forman el numeral.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: ese es el método de divisiones sucesivas.'},
  {_id:15,q:'V/F: Para convertir un numeral de base n1 a base n2 (ambas distintas de 10), el camino más directo es pasar primero a base decimal y luego a base n2.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: convertir directamente entre dos bases distintas de 10 sin pasar por decimal es más propenso a error; el método estándar usa el decimal como paso intermedio.'},
  {_id:16,q:'V/F: Al convertir un decimal a base n, el primer resto obtenido en las divisiones sucesivas es la cifra de mayor orden (más a la izquierda) del numeral resultante.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el primer resto obtenido corresponde a la cifra de MENOR orden (la de las unidades, más a la derecha); el numeral se lee de abajo hacia arriba.'},
  {_id:17,q:'Halla el equivalente decimal de 234(base 5).',a:'69',opts:_i4gshuf(['69','70','68','74']),mc:true,ste:'234(base 5) = 2×5^2 + 3×5^1 + 4×5^0 = 69.'},
  {_id:18,q:'Halla el equivalente decimal de 312(base 7).',a:'156',opts:_i4gshuf(['156','157','155','163']),mc:true,ste:'312(base 7) = 3×7^2 + 1×7^1 + 2×7^0 = 156.'},
  {_id:19,q:'Halla el equivalente decimal de 521(base 6).',a:'193',opts:_i4gshuf(['193','194','192','199']),mc:true,ste:'521(base 6) = 5×6^2 + 2×6^1 + 1×6^0 = 193.'},
  {_id:20,q:'Halla el equivalente decimal de 143(base 8).',a:'99',opts:_i4gshuf(['99','100','98','107']),mc:true,ste:'143(base 8) = 1×8^2 + 4×8^1 + 3×8^0 = 99.'},
  ]);
}
_SKILL_META['i1ar_nmr_b1']={ico:'🔢',lbl:'Conversión de bases',qCount:4,gen:_genI1arNmr_B1,plantillas:["Convertir un numeral en base n a base decimal", "Convertir un número decimal a una base n dada", "Convertir un numeral de base n1 a base n2 (no decimal)", "V/F sobre el procedimiento de conversión de bases", "Variante numérica de P1"]};

function _genI1arNmr_B2(){
  return _i4gpick([
  {_id:1,q:'Dado el numeral 471538, halla la suma del valor relativo de la cifra de las centenas y el valor relativo de la cifra de las decenas de millar.',a:'70500',opts:_i4gshuf(['70500','70510','70490','500']),mc:true,ste:'En 471538: V.R.(centenas)=500, V.R.(decenas de millar)=70000. Suma = 500+70000 = 70500.'},
  {_id:2,q:'Dado el numeral 826914, halla la suma del valor relativo de la cifra de las unidades y el valor relativo de la cifra de las centenas de millar.',a:'800004',opts:_i4gshuf(['800004','800014','799994','4']),mc:true,ste:'En 826914: V.R.(unidades)=4, V.R.(centenas de millar)=800000. Suma = 4+800000 = 800004.'},
  {_id:3,q:'Dado el numeral 395027, halla la suma del valor relativo de la cifra de las decenas y el valor relativo de la cifra de las unidades de millar.',a:'5020',opts:_i4gshuf(['5020','5030','5010','20']),mc:true,ste:'En 395027: V.R.(decenas)=20, V.R.(unidades de millar)=5000. Suma = 20+5000 = 5020.'},
  {_id:4,q:'Dado el numeral 708653, halla la suma del valor relativo de la cifra de las centenas y el valor relativo de la cifra de las unidades.',a:'603',opts:_i4gshuf(['603','613','593','600']),mc:true,ste:'En 708653: V.R.(centenas)=600, V.R.(unidades)=3. Suma = 600+3 = 603.'},
  {_id:5,q:'Dado el numeral 583294, halla el valor relativo de la cifra de las centenas de millar menos el valor relativo de la cifra de las unidades.',a:'499996',opts:_i4gshuf(['499996','499997','499995','500004']),mc:true,ste:'En 583294: valor relativo(centenas de millar)=500000, valor relativo(unidades)=4. Diferencia = 500000−4 = 499996.'},
  {_id:6,q:'Dado el numeral 167452, halla el valor relativo de la cifra de las decenas de millar menos el valor relativo de la cifra de las centenas.',a:'59600',opts:_i4gshuf(['59600','59601','59599','60400']),mc:true,ste:'En 167452: valor relativo(decenas de millar)=60000, valor relativo(centenas)=400. Diferencia = 60000−400 = 59600.'},
  {_id:7,q:'Dado el numeral 924816, halla el valor absoluto de la cifra de las unidades de millar menos el valor absoluto de la cifra de las decenas.',a:'3',opts:_i4gshuf(['3','4','2','5']),mc:true,ste:'En 924816: valor absoluto(unidades de millar)=4, valor absoluto(decenas)=1. Diferencia = 4−1 = 3.'},
  {_id:8,q:'Dado el numeral 350798, halla el valor absoluto de la cifra de las centenas menos el valor absoluto de la cifra de las unidades de millar.',a:'7',opts:_i4gshuf(['7','8','6']),mc:true,ste:'En 350798: valor absoluto(centenas)=7, valor absoluto(unidades de millar)=0. Diferencia = 7−0 = 7.'},
  {_id:9,q:'Halla el numeral que corresponde a la siguiente descomposición: 3CM + 5DM + 2UM + 4C + 7D + 1U',a:'352471',opts:_i4gshuf(['352471','352481','352461','352571']),mc:true,ste:'Sumando cada término según su valor posicional (U=1, D=10, C=100, UM=1000, DM=10000, CM=100000): 3CM + 5DM + 2UM + 4C + 7D + 1U = 352471.'},
  {_id:10,q:'Halla el numeral que corresponde a la siguiente descomposición: 2DM + 1CM + 3D + 2U',a:'120032',opts:_i4gshuf(['120032','120042','120022','120132']),mc:true,ste:'Sumando cada término según su valor posicional (U=1, D=10, C=100, UM=1000, DM=10000, CM=100000): 2DM + 1CM + 3D + 2U = 120032.'},
  {_id:11,q:'Halla el numeral que corresponde a la siguiente descomposición: 4UM + 5CM + 3D + 3C + 4U',a:'504334',opts:_i4gshuf(['504334','504344','504324','504434']),mc:true,ste:'Sumando cada término según su valor posicional (U=1, D=10, C=100, UM=1000, DM=10000, CM=100000): 4UM + 5CM + 3D + 3C + 4U = 504334.'},
  {_id:12,q:'Halla el numeral que corresponde a la siguiente descomposición: 6CM + 2UM + 8D',a:'602080',opts:_i4gshuf(['602080','602090','602070','602180']),mc:true,ste:'Sumando cada término según su valor posicional (U=1, D=10, C=100, UM=1000, DM=10000, CM=100000): 6CM + 2UM + 8D = 602080.'},
  {_id:13,q:'V/F: El valor absoluto (V.A.) de una cifra es el valor que representa por su forma o símbolo, sin importar la posición que ocupa.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: el V.A. es simplemente el dígito en sí, independiente de su posición en el numeral.'},
  {_id:14,q:'V/F: El valor relativo (V.R.) de una cifra depende de la posición que ocupa dentro del numeral.',a:'Verdadero',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es verdadero: el V.R. se obtiene multiplicando el V.A. de la cifra por la potencia de 10 correspondiente a su posición.'},
  {_id:15,q:'V/F: En el numeral 4 525, el valor relativo de la primera cifra \'4\' es igual a su valor absoluto.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el \'4\' está en la posición de las unidades de millar, por lo que su V.R. es 4×1000=4000, distinto de su V.A. que es 4.'},
  {_id:16,q:'V/F: Si dos cifras de un numeral son iguales (mismo dígito), sus valores relativos también son siempre iguales.',a:'Falso',opts:_i4gshuf(['Verdadero','Falso']),mc:true,ste:'Es falso: el V.R. depende de la posición; dos cifras iguales en posiciones distintas tienen valores relativos distintos.'},
  {_id:17,q:'Dado el numeral 639814, halla la suma del valor relativo de la cifra de las decenas y el valor relativo de la cifra de las centenas de millar.',a:'600010',opts:_i4gshuf(['600010','600020','600000','10']),mc:true,ste:'En 639814: V.R.(decenas)=10, V.R.(centenas de millar)=600000. Suma = 10+600000 = 600010.'},
  {_id:18,q:'Dado el numeral 275963, halla la suma del valor relativo de la cifra de las unidades y el valor relativo de la cifra de las decenas de millar.',a:'70003',opts:_i4gshuf(['70003','70013','69993','3']),mc:true,ste:'En 275963: V.R.(unidades)=3, V.R.(decenas de millar)=70000. Suma = 3+70000 = 70003.'},
  {_id:19,q:'Dado el numeral 804257, halla la suma del valor relativo de la cifra de las centenas y el valor relativo de la cifra de las unidades de millar.',a:'4200',opts:_i4gshuf(['4200','4210','4190','200']),mc:true,ste:'En 804257: V.R.(centenas)=200, V.R.(unidades de millar)=4000. Suma = 200+4000 = 4200.'},
  {_id:20,q:'Dado el numeral 516830, halla la suma del valor relativo de la cifra de las unidades de millar y el valor relativo de la cifra de las unidades.',a:'6000',opts:_i4gshuf(['6000','6010','5990','0']),mc:true,ste:'En 516830: V.R.(unidades de millar)=6000, V.R.(unidades)=0. Suma = 6000+0 = 6000.'},
  ]);
}
_SKILL_META['i1ar_nmr_b2']={ico:'🔢',lbl:'Descomposición polinómica de un numeral',qCount:4,gen:_genI1arNmr_B2,plantillas:["Suma de valores relativos de dos cifras de un numeral", "Diferencia de valores absolutos o relativos de dos cifras", "Reconstruir el numeral a partir de su descomposición polinómica dada en palabras", "V/F sobre valor absoluto (V.A.) vs valor relativo (V.R.)", "Variante numérica de P1"]};

