    const _retoRgbMap={Suma:'34,211,238',Resta:'236,72,153','Multiplicación':'251,191,36','División':'168,85,247',Multiplicacion:'251,191,36',Division:'168,85,247','Op. Combinada':'249,115,22',Ecuación:'16,185,129'};
