  const _hEd = _hMeta.editorial && PREP_EDITORIALS[_hMeta.editorial] ? ' · ' + (PREP_EDITORIALS[_hMeta.editorial].abbr || PREP_EDITORIALS[_hMeta.editorial].lbl) : '';
