// realmente cambió, para no generar escrituras de sobra.
function _prepSyncTorneoElig() {
  try {
    if (isAdmin()) return;
    const uid = getLoggedId();
    if (uid === null || uid === undefined || uid === 0) return; // invitados no participan del torneo
    if (!Array.isArray(_prepHistoryData)) return;
    const n = _prepUnitsFullyDoneForMe(uid);
    _prepMyUnitsFullyDone = n;
    if (n === _prepTorneoElig_lastSynced) return;
    _prepTorneoElig_lastSynced = n;
    if (typeof db === 'undefined' || !db) return;
    db.collection('torneoElig').doc(String(uid)).set({
      units: n,
      cumple: n >= TORNEO_MIN_UNIDADES,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }, { merge:true }).catch(e => console.error('torneoElig sync', e));
  } catch(e) { console.error('_prepSyncTorneoElig', e); }
}
// Misma lógica de formato que _prepLastDate, pero para el ÚLTIMO intento directo del examen de
// unidad (igual filtro que _prepLastUnitExamPct) — usado en el popup del cuadradito ★.
function _prepLastUnitExamDate(firstSkill) {
  if (!Array.isArray(_prepHistoryData) || !firstSkill) return null;
  const entries = _prepHistoryData.filter(h => h.isUnitExam && h.topic === firstSkill && !h.autoFromExam && !h.autoFromQuiz);
  if (!entries.length) return null;
  const sec = entries[0]?.completedAt?.seconds;
  if (!sec) return null;
  const d = new Date(sec*1000);
  const diffMs = Math.max(0, Date.now() - d.getTime());
  const diffMin = Math.floor(diffMs/60000);
  const diffH = Math.floor(diffMs/3600000);
  if (diffMin < 1) return 'Resuelto justo ahora';
  if (diffMin < 60) return 'Resuelto hace unos minutos';
  if (diffH < 24) return diffH===1 ? 'Resuelto hace una hora' : `Resuelto hace ${diffH} horas`;
  const months=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  const dateStr = d.getDate()+'-'+months[d.getMonth()]+'-'+d.getFullYear();
  let h = d.getHours();
  const mins = String(d.getMinutes()).padStart(2,'0');
  const ampm = h >= 12 ? 'p. m.' : 'a. m.';
  h = h % 12; if (h === 0) h = 12;
  return dateStr+' · '+h+':'+mins+' '+ampm;
}
function _prepCalcStreak() {
  if (!Array.isArray(_prepHistoryData) || !_prepHistoryData.length) return 0;
  const DAY = 86400000;
  const tod = new Date(); tod.setHours(0,0,0,0);
  const todMs = tod.getTime();
  // Conjunto de días (ms medianoche) con al menos una sesión
  const days = new Set(_prepHistoryData.map(h => {
    const d = new Date((h.completedAt?.seconds||0)*1000); d.setHours(0,0,0,0); return d.getTime();
  }));
  // Empezar desde hoy; si hoy no tiene sesión, empezar desde ayer
  let cur = days.has(todMs) ? todMs : todMs - DAY;
  let streak = 0;
  while (days.has(cur)) { streak++; cur -= DAY; }
  return streak;
}
function _prepCourseScore(topicKeys) {
  const W={dominado:100,competente:75,familiar:50,intentado:25,pendiente:0,unknown:0};
  if (!topicKeys.length) return 0;
  return Math.round(topicKeys.map(k=>W[_prepMasteryLevel(k)]||0).reduce((a,b)=>a+b,0)/topicKeys.length);
}
// ── Reporte semanal de progreso (para enviar a los padres por WhatsApp) ──────────
// Mismas reglas que _prepMasteryLevel/_prepLastPct/_prepCalcStreak pero operando sobre un
// array de historial explícito, para poder generar el reporte de un alumno que NO es el que
// está logueado (se usa _prepAdminHistData filtrado por uid, cargado por el admin).
function _prepMasteryLevelH(topicKey, hist) {
  if (!Array.isArray(hist)) return 'unknown';
  const isQuiz = !!BINGO_TOPICS[topicKey]?.quiz;
  // IMPORTANTE: ordenar siempre de más reciente a más antiguo antes de tomar sessions[0].
  // Si el `hist` recibido viene en orden ASCENDENTE (como histAsc en _ptsFirstDominatedDate,
  // que evalúa prefijos crecientes hist.slice(0,i+1) para "revivir" el historial día a día),
  // sin este sort sessions[0] quedaría fijo en el PRIMER intento de esa habilidad para
  // siempre (nunca cambia al crecer el prefijo), así que un alumno que no dominó una
  // habilidad en su primer intento pero sí en uno posterior NUNCA se detectaba como
  // "dominado" por esta función, aunque el panel de mastery actual sí lo mostrara dominado.
  let sessions = hist.filter(h=>h.topic===topicKey).slice().sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  if (isQuiz) {
    const boost = _prepQuizExamBoost(topicKey, hist);
    if (boost) sessions = sessions.concat([boost]).sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  }
  if (!sessions.length) return 'sinIntentos';
  if (isQuiz) {
    // Un cuestionario cuenta si el alumno lo hizo directamente, O si un examen de unidad
    // perfecto (100%) lo propagó como dominado (autoFromExam, real o derivado vía
    // _prepQuizExamBoost, para que también aplique a exámenes rendidos antes de esta
    // corrección) — igual criterio que _prepMasteryLevel en producción. Nunca cuenta una
    // propagación desde OTRO cuestionario.
    const quizSessions = sessions.filter(h=>!h.autoFromQuiz);
    if (!quizSessions.length) return 'sinIntentos';
    const pct = _prepReEvalPct(quizSessions[0]);
    if (pct>=100) return 'dominado';
    if (pct>=75)  return 'competente';
    if (pct>=50)  return 'familiar';
    if (pct>=25)  return 'intentado';
    return 'pendiente';
  }
  // Habilidades normales: usar la sesión más reciente (directa o propagada por examen/
  // cuestionario) — igual criterio que _prepMasteryLevel en producción. Antes esta versión
  // del reporte priorizaba cualquier sesión DIRECTA aunque fuera más antigua que una
  // propagación reciente, así que una habilidad recién dominada por el examen de unidad
  // seguía contando con su nivel viejo (más bajo) y el reporte mostraba, p.ej., "8/9" en
  // Habilidades cuando en realidad ya eran 9/9.
  const pct = _prepReEvalPct(sessions[0]);
  if (pct>=100) return 'dominado';
  if (pct>=75)  return 'competente';
  if (pct>=50)  return 'familiar';
  if (pct>=25)  return 'intentado';
  return 'pendiente';
}
function _prepLastPctH(topicKey, hist) {
  if (!Array.isArray(hist)) return null;
  const isQuiz = !!BINGO_TOPICS[topicKey]?.quiz;
  // Mismo fix que en _prepMasteryLevelH: forzar orden descendente antes de usar allSess[0],
  // para que funcione igual sin importar si `hist` viene ascendente o descendente.
  let allSess = hist.filter(h=>h.topic===topicKey).slice().sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  if (isQuiz) {
    const boost = _prepQuizExamBoost(topicKey, hist);
    if (boost) allSess = allSess.concat([boost]).sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  }
  if (!allSess.length) return null;
  if (isQuiz) {
    const quizSess = allSess.filter(h=>!h.autoFromQuiz);
    if (!quizSess.length) return null;
    return _prepReEvalPct(quizSess[0]);
  }
  // Habilidades normales: mismo criterio que _prepMasteryLevelH — la sesión más reciente,
  // directa o propagada.
  return _prepReEvalPct(allSess[0]);
}
function _prepCalcStreakH(hist) {
  if (!Array.isArray(hist) || !hist.length) return 0;
  const DAY = 86400000;
  const tod = new Date(); tod.setHours(0,0,0,0);
  const todMs = tod.getTime();
  const days = new Set(hist.map(h => {
    const d = new Date((h.completedAt?.seconds||0)*1000); d.setHours(0,0,0,0); return d.getTime();
  }));
  let cur = days.has(todMs) ? todMs : todMs - DAY;
  let streak = 0;
  while (days.has(cur)) { streak++; cur -= DAY; }
  return streak;
}
// Retorna la unidad completa del currículo (con .skills) que contiene ese topicKey, para el nivel dado.
function _prepTopicUnit(topic, level) {
  const levelData = PREP_CURRICULUM[level] || {};
  for (const units of Object.values(levelData)) {
    for (const u of units) {
      if (Array.isArray(u.skills) && u.skills.includes(topic)) return u;
    }
  }
  return null;
}
// Arma el texto del reporte semanal (últimos 7 días) de un alumno, listo para copiar/enviar por WhatsApp.
// `hist` debe ser el historial COMPLETO de ESE alumno (ver _prepOpenWeeklyReport, que lo trae con una
// consulta propia filtrada por uid — no usar _prepAdminHistData aquí: esa lista global está topada a 200
// documentos COMPARTIDOS entre todos los alumnos y sin orden por fecha en la consulta, así que puede
// faltarle actividad reciente de un alumno específico si otros alumnos generaron muchas sesiones).
function _prepBuildWeeklyReportText(uid, hist) {
  const students = getStudents();
  const stu = students.find(s=>String(s.id)===String(uid));
  const name = stu ? stu.name : 'Alumno';
  hist = Array.isArray(hist) ? hist : [];
  const nowSec = Math.floor(Date.now()/1000);
  const weekAgoSec = nowSec - 7*86400;
  const last7 = hist.filter(h=>h.completedAt?.seconds && h.completedAt.seconds>=weekAgoSec);
  // Filtrar por cursos asignados: solo mostrar actividades de los cursos asignados al alumno.
  const _myCourses = _prepMyCourses(uid);
  const _isAssignedCourse = h => {
    if (!_myCourses.length) return true;
    const u = _prepTopicUnit(h.topic, h.level);
    if (!u) return false;
    return _myCourses.some(c =>
      c.level === h.level &&
      String(c.grade||'') === String(h.grade||'') &&
      (c.editorial||null) === (u.editorial||null) &&
      (c.area||null) === (u.area||null)
    );
  };
  // "Directas": el alumno hizo el ejercicio/cuestionario/examen él mismo esta semana.
  const direct7 = last7.filter(h=>!h.autoFromExam && !h.autoFromQuiz && _isAssignedCourse(h));
  // "Tocadas": directas + las que llegaron a un nivel nuevo esta semana de forma automática al
  // aprobar el examen/cuestionario de la unidad (autoFromExam/autoFromQuiz) — cuentan igual como
  // practicadas/dominadas esta semana, aunque no se hayan resuelto sueltas ejercicio por ejercicio.
  const touched7 = last7.filter(_isAssignedCourse);

  const todayStr = new Date().toLocaleDateString('es-PE',{day:'2-digit',month:'long'});
  const weekAgoStr = new Date(weekAgoSec*1000).toLocaleDateString('es-PE',{day:'2-digit',month:'long'});

  if (!direct7.length) {
    return `📊 *REPORTE SEMANAL - ${name.toUpperCase()}*\n📅 ${weekAgoStr} al ${todayStr}\n\n${name} no registró actividad en Level Up esta semana.\n\n_MATHS LEVEL UP_`;
  }

  // "Cursos y unidades practicadas" es el TOTAL acumulado de todo el historial del alumno (no solo
  // esta semana), mostrando cuántas habilidades de la unidad ya domina sobre el total de esa unidad
  // (X/Y), contando HABILIDADES DISTINTAS tocadas alguna vez (ya sea resueltas directamente o
  // completadas automáticamente al aprobar el examen/cuestionario de la unidad — no cuenta
  // intentos/sesiones repetidos de la misma habilidad). "Habilidad" excluye los bancos de
  // cuestionario (_bq#) y de prueba única (_bpu), igual que el contador "N Habilidades" que ya se
  // muestra en el resto de Level Up (ver pureSkillKeys).
  const _pureSkillFilter = k => !/_bq\d/.test(k) && !k.includes('_bpu');
  const _lvlIco = {dominado:'✅', competente:'🟢', familiar:'🟡', intentado:'🟠', pendiente:'⚪'};
  const unitGroups = {};
  hist.filter(_isAssignedCourse).forEach(h=>{
    const u = _prepTopicUnit(h.topic, h.level);
    // Si la habilidad ya no pertenece a ninguna unidad del currículo actual (fue eliminada/movida),
    // no la incluimos en el reporte.
    if (!u) return;
    const editorial = u.editorial || null;
    const areaKey = u.area || null;
    const areaLbl = areaKey ? ((PREP_LEVELS[h.level]?.areas||[]).find(a=>a.key===areaKey)?.lbl || '') : '';
    const levelLbl = PREP_LEVELS[h.level]?.lbl || h.level || '';
    const grade = h.grade || '';
    const editorialInfo = editorial ? PREP_EDITORIALS[editorial] : null;
    const courseKey = h.level+'|'+grade+'|'+(editorial||'')+'|'+(areaKey||'');
    if (!unitGroups[courseKey]) {
      const gradeLevel = [grade ? grade+'°' : '', levelLbl].filter(Boolean).join(' ');
      const extras = [editorialInfo?.lbl, areaLbl].filter(Boolean).join(' - ');
      const ico = editorialInfo?.ico || '📘';
      const header = extras ? `${ico} ${gradeLevel} - ${extras}` : `${ico} ${gradeLevel}`;
      unitGroups[courseKey] = { header, units:{} };
    }
    const g = unitGroups[courseKey];

    // Código de unidad (U01, U02…): posición de la unidad dentro del curso (mismo editorial+área),
    // según el orden del currículo.
    const courseUnits = ((PREP_CURRICULUM[h.level]||{})[grade]||[])
      .filter(cu => (cu.editorial||null)===editorial && (cu.area||null)===areaKey);
    const unitIdx = courseUnits.indexOf(u);
    const unitCode = unitIdx >= 0 ? `U${String(unitIdx+1).padStart(2,'0')} - ` : '';

    const unitLbl = u.lbl || h.topicLabel || h.topic;
    if (!g.units[unitLbl]) {
      const total = u.skills.filter(_pureSkillFilter).length;
      g.units[unitLbl] = { skills:new Set(), total, unitCode, unitIdx: unitIdx>=0?unitIdx:999, unitObj:u, touched:false, quizOrExam:false };
    }
    // "touched": la unidad cuenta como practicada si el alumno hizo AL MENOS una habilidad suelta,
    // un cuestionario o un examen de esa unidad — antes solo se consideraban las habilidades sueltas,
    // así que una unidad donde solo se hizo el cuestionario/examen (ej. una partida reasignada por el
    // profesor) desaparecía por completo de esta sección aunque sí aparecía en "Actividades practicadas".
    g.units[unitLbl].touched = true;
    if (_pureSkillFilter(h.topic)) g.units[unitLbl].skills.add(h.topic);
    else g.units[unitLbl].quizOrExam = true;
  });
  // Nivel predominante de la unidad: el ícono del nivel de dominio (dominado/competente/familiar/
  // intentado/pendiente) que más se repite entre TODAS las habilidades de la unidad (incluyendo las
  // que el alumno nunca tocó, que cuentan como "pendiente"), calculado sobre TODO el historial del
  // alumno. En caso de empate, gana el nivel más alto.
  const _lvlRank = {dominado:5, competente:4, familiar:3, intentado:2, pendiente:1, sinIntentos:0};
  const _prepUnitPredominantIco = (u) => {
    const skills = u.skills.filter(_pureSkillFilter);
    if (!skills.length) return '';
    const counts = {};
    skills.forEach(sk => { const lvl = _prepMasteryLevelH(sk, hist); counts[lvl] = (counts[lvl]||0)+1; });
    let best = null, bestCount = -1;
    Object.keys(counts).forEach(lvl => {
      const c = counts[lvl];
      if (c > bestCount || (c === bestCount && (_lvlRank[lvl]||0) > (_lvlRank[best]||0))) { best = lvl; bestCount = c; }
    });
    return _lvlIco[best] || '';
  };
  const unitsLines = Object.values(unitGroups).map(g=>{
    const unitLines = Object.entries(g.units)
      .filter(([,u])=>u.touched) // se lista si tocó al menos una habilidad, un cuestionario o un examen de la unidad
      .sort((a,b)=>a[1].unitIdx-b[1].unitIdx) // de menor a mayor por número de unidad
      .map(([lbl,u])=>{
        const frac = u.skills.size>0
          ? ` (${u.skills.size}${u.total!==null?'/'+u.total:''} habilidad${u.skills.size===1?'':'es'})`
          : (u.quizOrExam ? ' (cuestionario/examen practicado)' : '');
        return `${_prepUnitPredominantIco(u.unitObj)} ${u.unitCode||''}${lbl}${frac}`;
      })
      .join('\n');
    return unitLines ? `${g.header}\n${unitLines}` : '';
  }).filter(Boolean).join('\n\n');

  // Agrupa por CURSO (nivel + grado + editorial + área) para "Habilidades, cuestionarios y
  // examenes practicadas esta semana", con cada línea prefijada por su código de unidad (U01,
  // U02…), que es la posición de esa unidad dentro del curso (mismo editorial+área), según el
  // orden del currículo.
  const courseGroups = {};
  const seenTopics = new Set();
  const touchedUnits = new Set();
  touched7.forEach(h=>{
    const u = _prepTopicUnit(h.topic, h.level);
    // Si la habilidad ya no pertenece a ninguna unidad del currículo actual (fue eliminada/movida),
    // no la incluimos en el reporte.
    if (!u) return;
    // Las habilidades auto-completadas al aprobar el examen/cuestionario de la unidad
    // (autoFromExam/autoFromQuiz) no se listan como actividad propia esta semana — no fueron
    // resueltas directamente por el alumno, y mostrarlas aquí generaba confusión. El examen o
    // cuestionario que las causó sí sigue apareciendo (esa entrada no tiene autoFromExam/autoFromQuiz).
    if (h.autoFromExam || h.autoFromQuiz) return;
    const editorial = u.editorial || null;
    const areaKey = u.area || null;
    const areaLbl = areaKey ? ((PREP_LEVELS[h.level]?.areas||[]).find(a=>a.key===areaKey)?.lbl || '') : '';
    const levelLbl = PREP_LEVELS[h.level]?.lbl || h.level || '';
    const grade = h.grade || '';
    const editorialInfo = editorial ? PREP_EDITORIALS[editorial] : null;
    const courseKey = h.level+'|'+grade+'|'+(editorial||'')+'|'+(areaKey||'');
    if (!courseGroups[courseKey]) {
      const gradeLevel = [grade ? grade+'°' : '', levelLbl].filter(Boolean).join(' ');
      const extras = [editorialInfo?.lbl, areaLbl].filter(Boolean).join(' - ');
      const ico = editorialInfo?.ico || '📘';
      const header = extras ? `${ico} ${gradeLevel} - ${extras}` : `${ico} ${gradeLevel}`;
      courseGroups[courseKey] = { header, domSkills:[] };
    }
    const g = courseGroups[courseKey];

    // Código de unidad (U01, U02…): posición de la unidad dentro del curso (mismo editorial+área),
    // según el orden del currículo.
    const courseUnits = ((PREP_CURRICULUM[h.level]||{})[grade]||[])
      .filter(cu => (cu.editorial||null)===editorial && (cu.area||null)===areaKey);
    const unitIdx = courseUnits.indexOf(u);
    const unitCode = unitIdx >= 0 ? `U${String(unitIdx+1).padStart(2,'0')} - ` : '';

    // Dominio por habilidad: una línea por habilidad distinta tocada esta semana (directa o
    // auto-completada por examen/cuestionario de unidad), con su nivel actual (calculado sobre
    // TODO el historial del alumno, no solo esta semana). Dentro de cada unidad, el orden sigue la
    // misma leyenda que el resto de Level Up: primero habilidades normales, luego cuestionario
    // (_bq#) y al final el examen de unidad (isUnitExam). Cada habilidad individual lleva al final
    // su posición dentro del total de habilidades de la unidad (X/Y); el examen de unidad se
    // muestra como "Examen: {nombre unidad}" sin esa fracción.
    if (!seenTopics.has(h.topic)) {
      seenTopics.add(h.topic);
      const lvl = _prepMasteryLevelH(h.topic, hist);
      const lbl = h.topicLabel || (BINGO_TOPICS[h.topic]||{}).lbl || h.topic;
      const isQuiz = /_bq\d/.test(h.topic);
      // Orden dentro de la unidad: el mismo orden intercalado del currículo (habilidades y
      // cuestionarios aparecen mezclados ahí, ej. 3 habilidades, cuestionario 1, 3 habilidades más,
      // cuestionario 2…), no "todas las habilidades primero y luego todos los cuestionarios". El
      // examen de unidad siempre va al final (su h.topic guardado es el de una habilidad cualquiera
      // de la unidad, no una posición real, así que se fuerza a Infinity para que no se intercale).
      let text, posInUnit = h.isUnitExam ? Infinity : u.skills.indexOf(h.topic);
      if (h.isUnitExam) {
        // El nombre de la unidad lo tomamos del currículo actual (u.lbl), no del guardado en el
        // historial (h.topicLabel), para que si renombras la unidad después el reporte ya lo refleje.
        text = `${_lvlIco[lvl]||''} ${unitCode}Examen: ${u.lbl}`;
      } else if (isQuiz) {
        // El nombre del cuestionario lo tomamos de la definición ACTUAL en BINGO_TOPICS (limpiando
        // el prefijo "Cuestionario N –" con _cleanLbl), no del guardado en el historial, para que si
        // renombras un cuestionario los reportes futuros usen el nombre nuevo y no el congelado de
        // cuando el alumno lo practicó. Algunas etiquetas además incluyen el nombre de la unidad como
        // prefijo (ej. "Monomios: Grado y Parámetros") — lo quitamos para no duplicarlo, ya que la
        // unidad ya se identifica con el código U0X y el encabezado del curso.
        const liveLbl = _cleanLbl((BINGO_TOPICS[h.topic]||{}).lbl, lbl);
        const unitPrefixRe = new RegExp('^' + u.lbl.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + ':\\s*');
        const quizLbl = liveLbl.replace(unitPrefixRe, '');
        text = `${_lvlIco[lvl]||''} ${unitCode}Cuestionario ${h.quizNum||''}: ${quizLbl}`;
      } else {
        let frac = '';
        const unitSkills = u.skills.filter(_pureSkillFilter);
        const sIdx = unitSkills.indexOf(h.topic);
        if (sIdx >= 0) frac = ` (${sIdx+1}/${unitSkills.length})`;
        text = `${_lvlIco[lvl]||''} ${unitCode}${lbl}${frac}`;
      }
      g.domSkills.push({ unitIdx: unitIdx>=0?unitIdx:999, posInUnit, text });
      touchedUnits.add(u);
    }
  });

  const skillsLines = Object.values(courseGroups).map(g=>{
    const sorted = g.domSkills.slice().sort((a,b)=>
      a.unitIdx-b.unitIdx || a.posInUnit-b.posInUnit);
    return sorted.length ? `${g.header}\n${sorted.map(x=>x.text).join('\n')}` : '';
  }).filter(Boolean).join('\n\n');

  // A reforzar: habilidades DENTRO de las unidades ya tocadas esta semana que NO están dominadas
  // (competente, familiar, intentado o pendiente — cualquier nivel distinto de "dominado"; no se
  // incluyen habilidades de unidades que el alumno nunca ha tocado).
  const reforzar = [];
  const seenReforzar = new Set();
  touchedUnits.forEach(u=>{
    (u.skills||[]).forEach(sk=>{
      if (!BINGO_TOPICS[sk] || seenReforzar.has(sk)) return;
      const lvl = _prepMasteryLevelH(sk, hist);
      if (lvl!=='dominado') {
        seenReforzar.add(sk);
        const pct = _prepLastPctH(sk, hist);
        const lbl = BINGO_TOPICS[sk].lbl || sk;
        reforzar.push({ sk, lbl, lvl, pct });
      }
    });
  });
  const reforzarLines = reforzar.slice(0,6).map(r=>
    `⚠️ ${r.lbl}${(r.lvl==='sinIntentos'||r.lvl==='pendiente') ? ' (sin empezar)' : ' ('+r.pct+'%)'}`
  ).join('\n');

  const streak = _prepCalcStreakH(hist);
  const timeSec = last7.reduce((a,h)=>a+(h.timeSec||0),0);
  const timeMin = Math.round(timeSec/60);

  // IV. Tareas asignadas al alumno con su estado de completitud
  const _myTasks = (overrides[String(uid)]?.prepTasks) || [];
  const nowSecT = Math.floor(Date.now()/1000);
  const pendingTaskNames = [];
  const taskLines = _myTasks.map(t => {
    const _isExamT = !!t.exam;
    const _from = t.assignedAt || 0;
    const _to   = t.dueAt || Infinity;
    const dueStr = t.dueAt
      ? new Date(t.dueAt*1000).toLocaleDateString('es-PE',{day:'2-digit',month:'short'})
      : '';
    const overdue = t.dueAt && t.dueAt < nowSecT;
    let name, done, pct;
    if (_isExamT) {
      name = t.label || 'Examen';
      const _firstSk = (t.skills||[]).find(sk=>BINGO_TOPICS[sk]&&!BINGO_TOPICS[sk].quiz) || (t.skills||[])[0];
      const sess = hist.filter(h=>{
        const sec=h.completedAt?.seconds||0;
        return sec>=_from && sec<=_to && h.isUnitExam && h.topic===_firstSk && !h.autoFromExam && !h.autoFromQuiz;
      });
      done = sess.length > 0;
      pct  = done ? _prepReEvalPct(sess[0]) : null;
    } else {
      const def = BINGO_TOPICS[t.topic]||{};
      name = def.lbl || t.topic;
      const sess = hist.filter(h=>{
        const sec=h.completedAt?.seconds||0;
        return sec>=_from && sec<=_to && h.topic===t.topic && !h.autoFromExam && !h.autoFromQuiz;
      });
      done = sess.length > 0;
      pct  = done ? _prepReEvalPct(sess[0]) : null;
    }
    if (!done) pendingTaskNames.push(name);
    const ico   = done ? '✅' : (overdue ? '❌' : '⏳');
    const pctTx = pct != null ? `: ${pct}%` : '';
    const dueTx = dueStr ? ` (vence ${dueStr}${overdue&&!done?' ⚠️':''})` : '';
    return `${ico} ${name}${pctTx}${dueTx}`;
  }).join('\n');

  // Desafíos de Dominio: sesiones de nivel 'especial' de los últimos 7 días
  const _desafio7 = last7.filter(h => h.level === 'especial' && !h.autoFromExam && !h.autoFromQuiz);
  const _nivelLblD = ['','Básico','Intermedio','Avanzado'];
  const _desafioGroups = {};
  _desafio7.forEach(h => {
    const _dReto = h.retoLbl || _prepDesafioRetoFromTopic(h.topic) || '?';
    const key = _dReto + '|' + (h.desafioNivel||1);
    if (!_desafioGroups[key]) _desafioGroups[key] = { retoLbl: _dReto, nivel: h.desafioNivel||1, bestPct: null };
    const p = h.pct != null ? Math.round(h.pct) : (h.total ? Math.round((h.correct||0)/h.total*100) : null);
    if (p !== null && (_desafioGroups[key].bestPct === null || p > _desafioGroups[key].bestPct)) _desafioGroups[key].bestPct = p;
  });
  const _desafioLines = Object.values(_desafioGroups).map(d => {
    const pctStr = d.bestPct !== null ? `${d.bestPct}%` : 'sin intentos';
    const ico = d.bestPct === null ? '⚪' : d.bestPct >= 100 ? '✅' : d.bestPct >= 75 ? '🟢' : d.bestPct >= 50 ? '🟡' : d.bestPct >= 25 ? '🟠' : '⚪';
    return `${ico} ${d.retoLbl} — ${_nivelLblD[d.nivel]||'Nivel '+d.nivel} (mejor intento: ${pctStr})`;
  }).join('\n');

  const recTargets = reforzar.slice(0,2).map(r=>r.lbl);
  const recParts = [];
  if (recTargets.length) recParts.push(`reforzar ${recTargets.join(' y ')}`);
  if (pendingTaskNames.length) recParts.push(`completar ${pendingTaskNames.length===1?'la tarea':'las tareas'}: ${pendingTaskNames.slice(0,2).join(' y ')}`);
  const recommendation = recParts.length
    ? `Se sugiere ${recParts.join(', y también ')} esta semana.`
    : `¡Felicitaciones! ¡Buen avance esta semana! Sigue practicando para mantener el nivel.`;

  // Habilidades dominadas esta semana
  const dominatedCount = [...new Set(touched7.map(h=>h.topic))]
    .filter(topic => _pureSkillFilter(topic) && _prepMasteryLevelH(topic, hist) === 'dominado')
    .length;

  const _lvlNombre = {dominado:'Dominado (100%)', competente:'Competente (≥75%)', familiar:'Familiar (≥50%)', intentado:'Intentado (≥25%)', pendiente:'Pendiente (0%)'};
  const leyenda = Object.keys(_lvlIco).map(k=>`${_lvlIco[k]} ${_lvlNombre[k]}`).join('\n');

  return `📊 *REPORTE SEMANAL - ${name.toUpperCase()}*\n📅 ${weekAgoStr} al ${todayStr}\n\n`
    + `*Leyenda:*\n${leyenda}\n\n`
    + `*Cursos y unidades practicadas:*\n${unitsLines || '—'}\n\n`
    + `*Actividades practicadas esta semana:*\n${skillsLines || '—'}\n\n`
    + (reforzarLines ? `*A reforzar:*\n${reforzarLines}\n\n` : '')
    + (taskLines ? `*Tareas:*\n${taskLines}\n\n` : '')
    + (_desafioLines ? `*Desafíos de Dominio:*\n${_desafioLines}\n\n` : '')
    + `🔥 Racha: ${streak} día${streak===1?'':'s'} seguido${streak===1?'':'s'}\n`
    + `⏱️ Tiempo practicado esta semana: ${timeMin} min\n\n`
    + `*Recomendación:*\n${recommendation}\n\n`
    + (dominatedCount ? `🏆 ¡${name} ha dominado ${dominatedCount} habilidad${dominatedCount===1?'':'es'} nueva${dominatedCount===1?'':'s'} esta semana! ¡Sigue así!\n\n` : '')
    + `_MATHS LEVEL UP_`;
}
async function _prepOpenWeeklyReport(uid) {
  if (typeof _snd !== 'undefined' && _snd?.click) { try { _snd.click(); } catch(e) {} }
  _prepWeeklyReportUid = uid;
  _prepWeeklyReportOpen = true;
  _prepWeeklyReportPhone = '';
  _prepWeeklyReportPhoneLoading = true;
  _prepWeeklyReportText = '';
  _renderPreparatePane();
  // Traer el historial COMPLETO de este alumno con su propia consulta (filtrada por uid), en vez de
  // usar _prepAdminHistData (que está topada a 200 documentos compartidos entre TODOs los alumnos y
  // sin orden por fecha) — así el reporte de este alumno no pierde sesiones por actividad de otros.
  let hist = [];
  try {
    const snap = await db.collection('prepHistory').where('uid','==',String(uid)).get();
    snap.forEach(doc => hist.push({ id:doc.id, ...doc.data() }));
    hist.sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  } catch(e) { console.error('weekly report history load', e); hist = []; }
  _prepWeeklyReportHist = hist;
  _prepWeeklyReportText = _prepBuildWeeklyReportText(uid, hist);
  try {
    const doc = await db.collection('padres').doc('main').get();
    const docData = doc.exists ? doc.data() : {};
    const parents = docData.parents || {};
    // padresStudents: mapa padresId → {name, ...} — sistema de IDs propio de padres, DISTINTO a DEFAULT_STUDENTS
    const padresStudents = docData.students || {};
    // Nombre del alumno actual en el sistema levelup
    const allStudents = getStudents();
    const currentStu = allStudents.find(s => String(s.id) === String(uid));
    const currentName = (currentStu && currentStu.name) || '';
    // Normalizar: sin acentos, minúsculas — para comparación robusta entre sistemas de IDs
    const _normName = n => (n||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const _curNorm = _normName(currentName);
    // Buscar el padresId del alumno actual por nombre normalizado (puente entre los dos sistemas de IDs)
    const currentPadresId = currentName
      ? Object.keys(padresStudents).find(pid => _normName(padresStudents[pid].name) === _curNorm)
      : null;
    // Encontrar la familia (entry) por padresId
    const entry = currentPadresId
      ? Object.values(parents).find(p => Array.isArray(p.children) && p.children.map(String).includes(String(currentPadresId)))
      : null;
    _prepWeeklyReportPhone = (entry && entry.phone) || '';
    // Detectar hermanos: obtener los padresIds de los hermanos, mapear a levelup IDs por nombre
    if (entry && Array.isArray(entry.children) && entry.children.length > 1) {
      const siblingPadresIds = entry.children.map(String).filter(pid => pid !== String(currentPadresId));
      _prepWeeklyReportSiblings = siblingPadresIds.map(pid => {
        const padresStu = padresStudents[pid];
        if (!padresStu || !padresStu.name) return null;
        const sibNorm = _normName(padresStu.name);
        // Buscar primero coincidencia exacta, luego normalizada
        const levelupStu = allStudents.find(s => s.name.trim() === padresStu.name.trim())
                        || allStudents.find(s => _normName(s.name) === sibNorm);
        return levelupStu ? { uid: String(levelupStu.id), name: levelupStu.name } : null;
      }).filter(Boolean);
      // Calcular apellido más frecuente del grupo familiar
      const _allFamilyNames = [currentName, ..._prepWeeklyReportSiblings.map(s=>s.name)];
      const _lnCount = {};
      _allFamilyNames.forEach(n => { const parts=n.trim().split(/\s+/); const ln=parts[parts.length-1]; _lnCount[ln]=(_lnCount[ln]||0)+1; });
      _prepWeeklyReportFamilyLastName = Object.entries(_lnCount).sort((a,b)=>b[1]-a[1])[0]?.[0] || 'Familia';
    } else {
      _prepWeeklyReportSiblings = [];
      _prepWeeklyReportFamilyLastName = 'Familia';
    }
  } catch(e) { console.error('weekly report phone lookup', e); _prepWeeklyReportPhone=''; _prepWeeklyReportSiblings=[]; _prepWeeklyReportFamilyLastName='Familia'; }
  _prepWeeklyReportPhoneLoading = false;
  _renderPreparatePane();
}
function closeWeeklyReport() {
  _prepWeeklyReportPdfTarget = null;
  _prepWeeklyReportOpen = false;
  _renderPreparatePane();
}
function _prepCopyWeeklyReport() {
  navigator.clipboard.writeText(_prepWeeklyReportText)
    .then(()=>{ if (typeof showToast==='function') showToast('Texto copiado ✅','success'); })
    .catch(()=>{ if (typeof showToast==='function') showToast('No se pudo copiar','error'); });
}
function _prepSendWeeklyReportWhatsApp() {
  const digits = (_prepWeeklyReportPhone||'').replace(/[^\d]/g,'');
  if (!digits) { if (typeof showToast==='function') showToast('Ingresa el teléfono del padre primero','error'); return; }
  const withCountry = digits.length<=9 ? '51'+digits : digits;
  window.open(`https://wa.me/${withCountry}?text=${encodeURIComponent(_prepWeeklyReportText)}`, '_blank');
}
// Convierte el texto plano del reporte (con *negritas* estilo WhatsApp y líneas en blanco) a HTML
// simple con un poco de estilo, para poder "fotografiarlo" con html2canvas y meterlo en el PDF.
function _prepReportTextToHtml(text) {
  const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const lines = String(text||'').split('\n');
  return lines.map(line=>{
    const trimmed = line.trim();
    if (!trimmed) return '<div style="height:10px"></div>';
    if (trimmed === '_MATHS LEVEL UP_') {
      return `<div style="font-size:11px;color:rgba(0,0,0,0.35);margin-top:12px;letter-spacing:0.08em;font-weight:700">MATHS LEVEL UP</div>`;
    }
    let html = esc(line).replace(/\*(.+?)\*/g, '<b>$1</b>');
    if (line.startsWith('📊')) {
      return `<div style="font-size:19px;font-weight:900;color:#7c3aed;margin-bottom:2px">${html}</div>`;
    }
    if (line.startsWith('📅')) {
      return `<div style="font-size:13px;color:rgba(0,0,0,0.55);margin-bottom:12px">${html}</div>`;
    }
    if (/^\*.+\*$/.test(trimmed)) {
      return `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">${html}</div>`;
    }
    return `<div style="font-size:13px;color:#222;line-height:1.55">${html}</div>`;
  }).join('');
}
// Construye el HTML del reporte semanal PARA EL PDF, con tablas de detalle (fecha, hora,
// ejercicios, %, tiempo) en "Cursos y unidades practicadas" y "Actividades practicadas esta
// semana" — a diferencia del texto plano de WhatsApp/copiar (_prepBuildWeeklyReportText), que no
// se toca y sigue mostrando solo íconos + nombres. Reutiliza la misma lógica de agrupación por
// curso/unidad que _prepBuildWeeklyReportText.
function _prepBuildWeeklyReportPdfHtml(uid, hist, days) {
  days = days || 7;
  const _rTitleLbl = days === 1 ? 'DIARIO' : 'SEMANAL';
  const students = getStudents();
  const stu = students.find(s=>String(s.id)===String(uid));
  const name = stu ? stu.name : 'Alumno';
  hist = Array.isArray(hist) ? hist : [];
  const esc = s => String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const nowSec = Math.floor(Date.now()/1000);
  const weekAgoSec = nowSec - days*86400;
  const last7 = hist.filter(h=>h.completedAt?.seconds && h.completedAt.seconds>=weekAgoSec);
  const _myCoursesP = _prepMyCourses(uid);
  const _isAssignedCourseP = h => {
    if (!_myCoursesP.length) return true;
    const u = _prepTopicUnit(h.topic, h.level);
    if (!u) return false;
    return _myCoursesP.some(c =>
      c.level === h.level &&
      String(c.grade||'') === String(h.grade||'') &&
      (c.editorial||null) === (u.editorial||null) &&
      (c.area||null) === (u.area||null)
    );
  };
  const direct7 = last7.filter(h=>!h.autoFromExam && !h.autoFromQuiz && _isAssignedCourseP(h));
  const touched7 = last7.filter(_isAssignedCourseP);

  const todayStr = new Date().toLocaleDateString('es-PE',{day:'2-digit',month:'long'});
  const weekAgoStr = new Date(weekAgoSec*1000).toLocaleDateString('es-PE',{day:'2-digit',month:'long'});

  const _desafio7Early = last7.filter(h => h.level === 'especial' && !h.autoFromExam && !h.autoFromQuiz);
  if (!direct7.length && !_desafio7Early.length) {
    return `<div style="font-size:19px;font-weight:900;color:#7c3aed;margin-bottom:2px">📊 REPORTE ${_rTitleLbl} - ${esc(name.toUpperCase())}</div>`
      + `<div style="font-size:13px;color:rgba(0,0,0,0.55);margin-bottom:12px">📅 ${weekAgoStr} al ${todayStr}</div>`
      + `<div style="font-size:13px;color:#222;line-height:1.55">${esc(name)} no registró actividad en Level Up esta semana.</div>`;
  }

  const _pureSkillFilter = k => !/_bq\d/.test(k) && !k.includes('_bpu');
  const _lvlIco = {dominado:'<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#7c3aed;font-size:12px;font-weight:900;color:#fff;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">A+</span>', competente:'<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#9333ea;font-size:13px;font-weight:900;color:#fff;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">A</span>', familiar:'<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#c084fc;font-size:13px;font-weight:900;color:#581c87;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">B</span>', intentado:'<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#e9d5ff;font-size:13px;font-weight:900;color:#6d28d9;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">C</span>', pendiente:'<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#fdf4ff;font-size:13px;font-weight:900;color:#9333ea;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">D</span>'};
  const _lvlRank = {dominado:5, competente:4, familiar:3, intentado:2, pendiente:1, sinIntentos:0};
  const fmtTime = sec => {
    sec = Math.max(0, Math.round(sec||0));
    const m = Math.floor(sec/60), s = sec%60;
    return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  };
  const fmtDate = sec => sec ? new Date(sec*1000).toLocaleDateString('es-PE',{day:'2-digit',month:'short'}) : '—';
  const fmtHour = sec => sec ? new Date(sec*1000).toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit'}) : '—';
  // Formato DD/MM (día primero) solo para la tabla "I. Cursos y unidades practicadas" — el resto
  // de tablas del reporte (II, III, IV) siguen usando fmtDate (día + mes abreviado) sin cambios.
  const fmtDateDMY = sec => {
    if (!sec) return '—';
    const d = new Date(sec*1000);
    return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}`;
  };
  // Badge de dominio "todo en una fila" (letra + barra + %) para la tabla "I. Cursos y unidades
  // practicadas" — mismos colores del badge de reporte (_lvlIco) pero combinado con una barra de
  // progreso y el % en línea, según el diseño "Opción A" aprobado por el usuario.
  const _domBadgeInfo = {
    dominado:  {bg:'#7c3aed', fg:'#fff',    txt:'A+'},
    competente:{bg:'#9333ea', fg:'#fff',    txt:'A'},
    familiar:  {bg:'#c084fc', fg:'#581c87', txt:'B'},
    intentado: {bg:'#e9d5ff', fg:'#6d28d9', txt:'C'},
    pendiente: {bg:'#fdf4ff', fg:'#9333ea', txt:'D'},
  };
  const _domBadgeHtml = (lvl, pct) => {
    const info = lvl && _domBadgeInfo[lvl] ? _domBadgeInfo[lvl] : {bg:'#94a3b8', fg:'#fff', txt:'—'};
    const pctStr = pct===null || pct===undefined ? '—' : `${pct}%`;
    const fillW = (pct===null || pct===undefined) ? 0 : Math.max(0, Math.min(100, pct));
    return `<div style="display:flex;align-items:center;gap:6px;min-width:96px">`
      + `<span style="display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:6px;background:${info.bg};font-size:9.5px;font-weight:900;color:${info.fg};letter-spacing:-0.4px;font-family:sans-serif;flex-shrink:0">${info.txt}</span>`
      + `<div style="flex:1;height:4px;border-radius:3px;background:#f1eafe;overflow:hidden"><div style="height:100%;border-radius:3px;background:linear-gradient(90deg,#c084fc,#7c3aed);width:${fillW}%"></div></div>`
      + `<span style="font-size:9.5px;font-weight:700;color:#7c3aed;width:26px;text-align:right;flex-shrink:0">${pctStr}</span>`
      + `</div>`;
  };
  const pctNumOf = h => {
    if (h.pct===0 || h.pct) return Math.round(h.pct);
    if (h.total) return Math.round((h.correct||0)/h.total*100);
    return null;
  };
  const pctOf = h => {
    const n = pctNumOf(h);
    return n===null ? '—' : `${n}%`;
  };
  // Nivel de dominio a partir del % de ESA sesión puntual (no del nivel vigente calculado sobre
  // todo el historial) — mismos rangos que _lvlNombre/leyenda: dominado 100, competente ≥75,
  // familiar ≥50, intentado ≥25, pendiente <25.
  const lvlFromPct = n => {
    if (n===null) return null;
    if (n>=100) return 'dominado';
    if (n>=75) return 'competente';
    if (n>=50) return 'familiar';
    if (n>=25) return 'intentado';
    return 'pendiente';
  };
  // Detecta si una unidad tiene examen disponible y en qué nivel quedó — usando el MISMO criterio
  // que el botón "Examen" real que usa el alumno (_prepUnitExam): la sesión se guarda con
  // isUnitExam:true y topic = la primera habilidad NO-cuestionario de la unidad, NO con una clave
  // "_bpu" literal (esa clave solo existe como cuestionario aparte en un puñado de unidades
  // antiguas y no es lo que el botón "Examen" universal escribe en el historial).
  const _prepUnitExamInfo = (unitObj, hist2) => {
    const validSkills = (unitObj.skills||[]).filter(sk=>BINGO_TOPICS[sk] && !BINGO_TOPICS[sk].quiz);
    if (!validSkills.length) return { hasExam:false, firstSk:null, lvl:null };
    const firstSk = validSkills[0];
    const sessions = hist2.filter(h=>h.isUnitExam && h.topic===firstSk);
    if (!sessions.length) return { hasExam:true, firstSk, lvl:null };
    const directSessions = sessions.filter(h=>!h.autoFromExam && !h.autoFromQuiz);
    const refPool = directSessions.length ? directSessions : sessions;
    const latest = refPool.slice().sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0))[0];
    const n = pctNumOf(latest);
    return { hasExam:true, firstSk, lvl: n===null ? null : lvlFromPct(n) };
  };

  // ---- "Cursos y unidades practicadas": resumen acumulado por unidad (todo el historial) ----
  const unitGroups = {};
  hist.filter(_isAssignedCourseP).forEach(h=>{
    const u = _prepTopicUnit(h.topic, h.level);
    if (!u) return;
    const editorial = u.editorial || null;
    const areaKey = u.area || null;
    const areaLbl = areaKey ? ((PREP_LEVELS[h.level]?.areas||[]).find(a=>a.key===areaKey)?.lbl || '') : '';
    const levelLbl = PREP_LEVELS[h.level]?.lbl || h.level || '';
    const grade = h.grade || '';
    const editorialInfo = editorial ? PREP_EDITORIALS[editorial] : null;
    const courseKey = h.level+'|'+grade+'|'+(editorial||'')+'|'+(areaKey||'');
    if (!unitGroups[courseKey]) {
      const gradeLevel = [grade ? grade+'°' : '', levelLbl].filter(Boolean).join(' ');
      const extras = [editorialInfo?.lbl, areaLbl].filter(Boolean).join(' - ');
      const ico = editorialInfo?.ico || '📘';
      const header = extras ? `${ico} ${gradeLevel} - ${extras}` : `${ico} ${gradeLevel}`;
      unitGroups[courseKey] = { header, units:{} };
    }
    const g = unitGroups[courseKey];
    const courseUnits = ((PREP_CURRICULUM[h.level]||{})[grade]||[])
      .filter(cu => (cu.editorial||null)===editorial && (cu.area||null)===areaKey);
    const unitIdx = courseUnits.indexOf(u);
    const unitCode = unitIdx >= 0 ? `U${String(unitIdx+1).padStart(2,'0')} - ` : '';
    const unitLbl = u.lbl || h.topicLabel || h.topic;
    if (!g.units[unitLbl]) {
      const total = u.skills.filter(_pureSkillFilter).length;
      g.units[unitLbl] = { skills:new Set(), total, unitCode, unitIdx: unitIdx>=0?unitIdx:999, unitObj:u,
        exCorrect:0, exTotal:0, timeSec:0, lastSec:0, touched:false };
    }
    const eu = g.units[unitLbl];
    // "touched": igual que en _prepBuildWeeklyReportText — la unidad cuenta como practicada con solo
    // habilidades sueltas, cuestionario o examen (antes se exigía al menos una habilidad suelta, y una
    // unidad con solo cuestionario/examen —p.ej. una partida reasignada por el profesor— desaparecía).
    eu.touched = true;
    if (_pureSkillFilter(h.topic)) eu.skills.add(h.topic);
    // Ejercicios/tiempo/última práctica solo de sesiones DIRECTAS (hechas por el alumno) — igual
    // criterio que el resto del reporte; las auto-completadas por examen/cuestionario no suman
    // ejercicios propios ni tiempo (siempre quedan en 0 en esos casos).
    if (!h.autoFromExam && !h.autoFromQuiz) {
      eu.exCorrect += (h.correct||0);
      eu.exTotal += (Array.isArray(h.answers) ? h.answers.length : (h.total||0));
      eu.timeSec += (h.timeSec||0);
      const sec = h.completedAt?.seconds||0;
      if (sec > eu.lastSec) eu.lastSec = sec;
    }
  });
  const _prepUnitPredominantLvl = (u) => {
    const skills = u.skills.filter(_pureSkillFilter);
    if (!skills.length) return null;
    const counts = {};
    // Skills no practicadas cuentan como 'pendiente'
    skills.forEach(sk => { const lvl = _prepMasteryLevelH(sk, hist) || 'pendiente'; counts[lvl] = (counts[lvl]||0)+1; });
    let best = null, bestCount = -1;
    Object.keys(counts).forEach(lvl => {
      const c = counts[lvl];
      if (c > bestCount || (c === bestCount && (_lvlRank[lvl]||0) > (_lvlRank[best]||0))) { best = lvl; bestCount = c; }
    });
    return best;
  };
  const _prepUnitAvgPct = (u) => {
    const skills = Array.from(u.skills).filter(_pureSkillFilter);
    if (!skills.length) return null;
    // Dividir entre el TOTAL de skills de la unidad, no solo las practicadas
    const sum = skills.reduce((a,sk)=>{ const p=_prepLastPctH(sk,hist); return a+(p!=null?p:0); },0);
    return Math.round(sum / skills.length);
  };
  const unitTables = Object.values(unitGroups).map(g=>{
    const rows = Object.entries(g.units)
      .filter(([,u])=>u.touched)
      .sort((a,b)=>a[1].unitIdx-b[1].unitIdx)
      .map(([lbl,u])=>{
        // "Habilidades" (columna X/Y) sigue contando sobre TODAS las habilidades de la unidad,
        // practicadas o no — es el progreso real de la unidad.
        const _pureUnitSkills = (u.unitObj.skills||[]).filter(_pureSkillFilter);
        const _domCount = _pureUnitSkills.filter(sk=>_prepMasteryLevelH(sk,hist)==='dominado').length;
        const _totalPure = _pureUnitSkills.length;
        // "Cuestionario X/Y": cuenta sobre TODAS las claves de cuestionario (_bq#) que tiene la
        // unidad en el currículo (Y), y cuántas de esas el alumno ya domina al 100% (X) — mismo
        // criterio "dominado" que la columna Habilidad. Si la unidad no tiene cuestionarios, Y=0
        // y se muestra "0/0".
        const _quizUnitSkills = (u.unitObj.skills||[]).filter(sk=>/_bq\d/.test(sk));
        const _quizDomCount = _quizUnitSkills.filter(sk=>_prepMasteryLevelH(sk,hist)==='dominado').length;
        // "Examen X/Y": Y=1 si la unidad tiene examen disponible (casi siempre, vía el botón
        // "Examen" universal — no se busca una clave "_bpu" literal, que casi nunca coincide con
        // lo que realmente guarda ese botón); X=1 si el alumno lo rindió y quedó "dominado".
        const _examInfo = _prepUnitExamInfo(u.unitObj, hist);
        const _examDomCount = _examInfo.hasExam && _examInfo.lvl==='dominado' ? 1 : 0;
        const _examTotal = _examInfo.hasExam ? 1 : 0;
        // "Dominio" (letra + %) ahora se calcula sobre las 3 actividades juntas (habilidad +
        // cuestionario + examen), no solo sobre habilidades sueltas — antes una unidad podía
        // mostrar "A+ 100%" con todas sus habilidades dominadas aunque el examen real de la
        // unidad estuviera sin dominar (columna Examen en 0/1), lo cual era engañoso.
        // - LETRA: promedio del nivel de las actividades que YA se intentaron al menos una vez
        //   (cualquier nivel menos "sin intentos"); si nada se ha intentado, no hay letra.
        // - %: sobre el TOTAL de actividades de la unidad (se hayan intentado o no), cuenta
        //   cuántas están dominadas al 100% — igual criterio que las columnas X/Y de arriba.
        const _allActLevels = [
          ..._pureUnitSkills.map(sk => _prepMasteryLevelH(sk, hist)),
          ..._quizUnitSkills.map(sk => _prepMasteryLevelH(sk, hist)),
          ...(_examInfo.hasExam ? [_examInfo.lvl || 'sinIntentos'] : []),
        ];
        const _attemptedActLevels = _allActLevels.filter(l => l !== 'sinIntentos');
        const _rankToLvl = {5:'dominado',4:'competente',3:'familiar',2:'intentado',1:'pendiente'};
        const lvl = _attemptedActLevels.length
          ? _rankToLvl[Math.max(1, Math.min(5, Math.round(_attemptedActLevels.reduce((a,l)=>a+(_lvlRank[l]||0),0)/_attemptedActLevels.length)))]
          : null;
        const pct = _allActLevels.length
          ? Math.round(_allActLevels.filter(l=>l==='dominado').length / _allActLevels.length * 100)
          : null;
        const dominioBadgeHtml = _domBadgeHtml(lvl, pct);
        const unitNumStr = u.unitIdx!==999 ? String(u.unitIdx+1).padStart(2,'0') : '';
        return {
          unidadCol: unitNumStr ? `U${unitNumStr}` : '—',
          nombreCol: lbl,
          dominioBadgeHtml,
          habilidadesCol: `${_domCount}/${_totalPure}`,
          cuestionarioCol: `${_quizDomCount}/${_quizUnitSkills.length}`,
          examenCol: `${_examDomCount}/${_examTotal}`,
          exercises: `${u.exCorrect}/${u.exTotal}`,
          pct: pct===null ? '—' : `${pct}%`,
          lastDate: fmtDateDMY(u.lastSec),
          lastHour: fmtHour(u.lastSec),
          timeStr: fmtTime(u.timeSec)
        };
      });
    return { header: g.header, rows };
  }).filter(t=>t.rows.length);

  // ---- "Actividades practicadas" (Sección II): SOLO la ventana del reporte (por defecto,
  // los últimos 7 días / "la semana anterior" — mismo weekAgoSec que el resto del reporte).
  // Antes usaba TODO el historial sin límite semanal (a pedido de un cambio anterior), pero eso
  // hacía que la sección mostrara actividad de meses atrás bajo un reporte etiquetado "semanal",
  // confundiendo qué se practicó realmente esta semana. Una tabla POR CURSO (no una tabla
  // combinada como en la Sección I), agrupada por Unidad (misma fila divisoria que Curso en la
  // Sección I) y, dentro de cada unidad, por "grupo de habilidades + su cuestionario" (usando los
  // srcKeys de cada cuestionario para saber qué habilidades componen su grupo), terminando con el
  // examen de unidad. Lo no practicado ESTA SEMANA no aparece (al no tener sesiones en la
  // ventana, ni la unidad ni el curso se agregan a _activityCourseGroups).
  const _histAssigned2 = hist.filter(_isAssignedCourseP).filter(h=>h.completedAt?.seconds && h.completedAt.seconds>=weekAgoSec);
  const _cleanQuizLbl = lbl => (lbl||'').replace(/^(Cuestionario\s*\d*\s*[–-]\s*|Examen\s*[–-]\s*)/i, '');
  const _pureUnitSkillsFor = uo => (uo.skills||[]).filter(_pureSkillFilter);
  // Estadísticas de una actividad (habilidad, cuestionario o examen) sobre TODO el historial
  // asignado — usa la sesión más reciente para Dominio/Fecha/Ejercicios, y suma el tiempo de
  // TODAS las sesiones directas para Tiempo. Para examen, topicKey debe ser la primera habilidad
  // no-cuestionario de la unidad e isExam=true (mismo criterio que _prepUnitExamInfo).
  const _activityStats = (topicKey, isExam) => {
    const sessions = isExam
      ? _histAssigned2.filter(h=>h.isUnitExam && h.topic===topicKey)
      : _histAssigned2.filter(h=>h.topic===topicKey && !h.isUnitExam);
    if (!sessions.length) return null;
    const directSessions = sessions.filter(h=>!h.autoFromExam && !h.autoFromQuiz);
    const refPool = directSessions.length ? directSessions : sessions;
    const latest = refPool.slice().sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0))[0];
    const n = pctNumOf(latest);
    const lvl = n===null ? null : lvlFromPct(n);
    const isAuto = !!(latest.autoFromExam || latest.autoFromQuiz);
    const totalTime = directSessions.reduce((a,h)=>a+(h.timeSec||0),0);
    return {
      lvl,
      pctNum: n,
      intentosCol: String(directSessions.length || sessions.length),
      dateStr: fmtDateDMY(latest.completedAt?.seconds||0),
      exercises: isAuto ? '—' : `${latest.correct||0}/${latest.total||0}`,
      timeStr: fmtTime(totalTime),
    };
  };
  const _activityCourseGroups = {};
  _histAssigned2.forEach(h=>{
    const u = _prepTopicUnit(h.topic, h.level);
    if (!u) return;
    const editorial = u.editorial || null;
    const areaKey = u.area || null;
    const areaLbl = areaKey ? ((PREP_LEVELS[h.level]?.areas||[]).find(a=>a.key===areaKey)?.lbl || '') : '';
    const levelLbl = PREP_LEVELS[h.level]?.lbl || h.level || '';
    const grade = h.grade || '';
    const editorialInfo = editorial ? PREP_EDITORIALS[editorial] : null;
    const courseKey = h.level+'|'+grade+'|'+(editorial||'')+'|'+(areaKey||'');
    if (!_activityCourseGroups[courseKey]) {
      const gradeLevel = [grade ? grade+'°' : '', levelLbl].filter(Boolean).join(' ');
      const extras = [editorialInfo?.lbl, areaLbl].filter(Boolean).join(' - ');
      const ico = editorialInfo?.ico || '📘';
      const header = extras ? `${ico} ${gradeLevel} - ${extras}` : `${ico} ${gradeLevel}`;
      _activityCourseGroups[courseKey] = { header, units:{} };
    }
    const cg = _activityCourseGroups[courseKey];
    const unitLbl = u.lbl || h.topicLabel || h.topic;
    if (!cg.units[unitLbl]) {
      const courseUnits = ((PREP_CURRICULUM[h.level]||{})[grade]||[])
        .filter(cu => (cu.editorial||null)===editorial && (cu.area||null)===areaKey);
      const unitIdx = courseUnits.indexOf(u);
      cg.units[unitLbl] = { unitIdx: unitIdx>=0?unitIdx:999, unitObj: u };
    }
  });
  const activityTablesV2 = Object.values(_activityCourseGroups).map(cg=>{
    const rows = [];
    let unitsPracticadas = 0;
    let _pctSum = 0, _pctCount = 0;
    Object.entries(cg.units)
      .sort((a,b)=>a[1].unitIdx-b[1].unitIdx)
      .forEach(([unitLbl, uinfo])=>{
        const unitObj = uinfo.unitObj;
        const unitNumStr = uinfo.unitIdx!==999 ? String(uinfo.unitIdx+1).padStart(2,'0') : '';
        rows.push({ kind:'unit', label: `${unitNumStr?`U${unitNumStr} · `:''}${unitLbl}` });
        let _unitPracticado = false;
        const totalPure = _pureUnitSkillsFor(unitObj).length;
        const quizKeys = (unitObj.skills||[]).filter(sk=>/_bq\d/.test(sk));
        const usedSkills = new Set();
        const groups = quizKeys.map((qk, gi)=>{
          const meta = _SKILL_META[qk] || {};
          const groupSkills = (meta.srcKeys||[]).filter(sk=>(unitObj.skills||[]).includes(sk));
          groupSkills.forEach(sk=>usedSkills.add(sk));
          return { n: gi+1, label: _cleanQuizLbl(meta.lbl) || `Grupo ${gi+1}`, skills: groupSkills, quizKey: qk, qIdx: gi };
        });
        // Habilidades sueltas no cubiertas por ningún cuestionario (caso raro / de seguridad): van
        // en un grupo final sin cuestionario, para no perderlas de la secuencia.
        const looseSkills = _pureUnitSkillsFor(unitObj).filter(sk=>!usedSkills.has(sk));
        if (looseSkills.length) groups.push({ n: groups.length+1, label: `Grupo ${groups.length+1}`, skills: looseSkills, quizKey: null, qIdx: -1 });
        groups.forEach(grp=>{
          rows.push({ kind:'group', label: `Grupo ${grp.n} · ${grp.label}` });
          grp.skills.slice()
            .sort((a,b)=>(unitObj.skills||[]).indexOf(a)-(unitObj.skills||[]).indexOf(b))
            .forEach(sk=>{
              const skIdx = _pureUnitSkillsFor(unitObj).indexOf(sk);
              const tipoCol = skIdx>=0 ? `H${String(skIdx+1).padStart(2,'0')}/${String(totalPure).padStart(2,'0')}` : 'H';
              const nombreCol = (BINGO_TOPICS[sk]||{}).lbl || sk;
              const stats = _activityStats(sk, false);
              if (stats) { _unitPracticado = true; if (stats.pctNum!==null) { _pctSum += stats.pctNum; _pctCount++; } }
              rows.push(stats ? { kind:'data', pending:false, tipoCol, nombreCol, ...stats } : { kind:'data', pending:true, tipoCol, nombreCol });
            });
          if (grp.quizKey) {
            const tipoCol = `C${String(grp.qIdx+1).padStart(2,'0')}/${String(quizKeys.length).padStart(2,'0')}`;
            const meta = _SKILL_META[grp.quizKey] || {};
            const nombreCol = `Cuestionario ${grp.qIdx+1}: ${_cleanQuizLbl(meta.lbl)}`;
            const stats = _activityStats(grp.quizKey, false);
            if (stats) { _unitPracticado = true; if (stats.pctNum!==null) { _pctSum += stats.pctNum; _pctCount++; } }
            rows.push(stats ? { kind:'data', pending:false, tipoCol, nombreCol, ...stats } : { kind:'data', pending:true, tipoCol, nombreCol });
          }
        });
        const examInfo = _prepUnitExamInfo(unitObj, _histAssigned2);
        if (examInfo.hasExam) {
          const tipoCol = `EU${unitNumStr}`;
          const nombreCol = `Examen: ${unitObj.lbl}`;
          const stats = _activityStats(examInfo.firstSk, true);
          if (stats) { _unitPracticado = true; if (stats.pctNum!==null) { _pctSum += stats.pctNum; _pctCount++; } }
          rows.push(stats ? { kind:'data', pending:false, isExam:true, tipoCol, nombreCol, ...stats } : { kind:'data', pending:true, isExam:true, tipoCol, nombreCol });
        }
        if (_unitPracticado) unitsPracticadas++;
      });
    const dominioProm = _pctCount ? Math.round(_pctSum / _pctCount) : null;
    return { header: cg.header, rows, unitsPracticadas, dominioProm };
  }).filter(t=>t.rows.some(r=>r.kind==='data'));

  // ---- "Actividades practicadas esta semana": una fila por actividad (últimos 7 días) ----
  // Contar intentos por topic esta semana (solo directos, para la columna Intentos)
  const _intentosPorTopic = {};
  touched7.filter(h=>!h.autoFromExam&&!h.autoFromQuiz).forEach(h=>{
    _intentosPorTopic[h.topic] = (_intentosPorTopic[h.topic]||0) + 1;
  });
  const courseGroups = {};
  const seenTopics = new Set();
  const touchedUnits = new Set();
  touched7.forEach(h=>{
    const u = _prepTopicUnit(h.topic, h.level);
    if (!u) return;
    // Las habilidades auto-completadas al aprobar el examen/cuestionario de la unidad
    // (autoFromExam/autoFromQuiz) no se listan como actividad propia esta semana — no fueron
    // resueltas directamente por el alumno, y mostrarlas aquí generaba confusión (mismo criterio que
    // en _prepBuildWeeklyReportText). El examen o cuestionario que las causó sí sigue apareciendo.
    if (h.autoFromExam || h.autoFromQuiz) return;
    const editorial = u.editorial || null;
    const areaKey = u.area || null;
    const areaLbl = areaKey ? ((PREP_LEVELS[h.level]?.areas||[]).find(a=>a.key===areaKey)?.lbl || '') : '';
    const levelLbl = PREP_LEVELS[h.level]?.lbl || h.level || '';
    const grade = h.grade || '';
    const editorialInfo = editorial ? PREP_EDITORIALS[editorial] : null;
    const courseKey = h.level+'|'+grade+'|'+(editorial||'')+'|'+(areaKey||'');
    if (!courseGroups[courseKey]) {
      const gradeLevel = [grade ? grade+'°' : '', levelLbl].filter(Boolean).join(' ');
      const extras = [editorialInfo?.lbl, areaLbl].filter(Boolean).join(' - ');
      const ico = editorialInfo?.ico || '📘';
      const header = extras ? `${ico} ${gradeLevel} - ${extras}` : `${ico} ${gradeLevel}`;
      courseGroups[courseKey] = { header, domSkills:[] };
    }
    const g = courseGroups[courseKey];
    const courseUnits = ((PREP_CURRICULUM[h.level]||{})[grade]||[])
      .filter(cu => (cu.editorial||null)===editorial && (cu.area||null)===areaKey);
    const unitIdx = courseUnits.indexOf(u);
    const unitCode = unitIdx >= 0 ? `U${String(unitIdx+1).padStart(2,'0')} - ` : '';
    if (!seenTopics.has(h.topic)) {
      seenTopics.add(h.topic);
      const lbl = h.topicLabel || (BINGO_TOPICS[h.topic]||{}).lbl || h.topic;
      const isQuiz = /_bq\d/.test(h.topic);
      // Mismo criterio de orden que en el texto de WhatsApp (_prepBuildWeeklyReportText): el orden
      // intercalado real del currículo, no todas las habilidades primero y luego los cuestionarios.
      // El examen de unidad siempre va al final (se fuerza a Infinity).
      let posInUnit = h.isUnitExam ? Infinity : u.skills.indexOf(h.topic);
      // Unidad/Tipo/Nombre van en columnas separadas en la tabla del PDF (a diferencia del texto de
      // WhatsApp, que sigue en una sola línea): Unidad = "U01"; Tipo = "H01/06" (habilidad, posición
      // dentro de las habilidades puras de la unidad / total), "C01/03" (cuestionario, su número /
      // total de cuestionarios de la unidad) o "EU01" (examen de la unidad 01); Nombre = el texto sin
      // el ícono de nivel (que ahora tiene su propia columna "Dominio") ni la fracción "(X/Y)" en
      // habilidades (ya representada en el Tipo).
      const unitNumStr = unitIdx >= 0 ? String(unitIdx+1).padStart(2,'0') : '';
      const unidadCol = unitNumStr ? `U${unitNumStr}` : '—';
      let tipoCol, nombreCol;
      if (h.isUnitExam) {
        tipoCol = `EU${unitNumStr}`;
        nombreCol = `Examen: ${u.lbl}`;
      } else if (isQuiz) {
        const liveLbl = _cleanLbl((BINGO_TOPICS[h.topic]||{}).lbl, lbl);
        const unitPrefixRe = new RegExp('^' + u.lbl.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + ':\\s*');
        const quizLbl = liveLbl.replace(unitPrefixRe, '');
        const totalQuizzes = u.skills.filter(k=>/_bq\d/.test(k)).length;
        tipoCol = `C${String(h.quizNum||0).padStart(2,'0')}/${String(totalQuizzes).padStart(2,'0')}`;
        nombreCol = `Cuestionario ${h.quizNum||''}: ${quizLbl}`;
      } else {
        const unitSkills = u.skills.filter(_pureSkillFilter);
        const sIdx = unitSkills.indexOf(h.topic);
        tipoCol = sIdx >= 0 ? `H${String(sIdx+1).padStart(2,'0')}/${String(unitSkills.length).padStart(2,'0')}` : 'H';
        nombreCol = lbl;
      }
      const sec = h.completedAt?.seconds||0;
      // Las habilidades auto-completadas al aprobar el examen/cuestionario de la unidad
      // (autoFromExam/autoFromQuiz) no tienen ejercicios ni tiempo propios reales — el "correct/total"
      // que traen es solo una proporción calculada a partir del resultado del examen/cuestionario, y
      // timeSec siempre es 0. Mostrar esos valores como si fueran datos reales de esa habilidad
      // induciría a error (parece que el alumno resolvió ejercicios en 0 segundos), así que se muestran
      // como "—" — el % sí se mantiene, porque refleja el nivel real alcanzado. (En la práctica estas
      // filas ya no llegan aquí — se filtran arriba — pero se deja el criterio por seguridad.)
      const isAuto = !!(h.autoFromExam || h.autoFromQuiz);
      // Dominio: nivel calculado a partir del % de ESTA sesión puntual, no del nivel vigente sobre
      // todo el historial — para que sea coherente con las columnas Ejercicios/%/Tiempo de la misma
      // fila (una fila representa un intento específico, no el estado actual de la habilidad; si se
      // usara el nivel vigente, una fila con 20% podría mostrar ✅ si luego se dominó por otro medio,
      // como aprobar el examen de la unidad).
      const rowPctNum = pctNumOf(h);
      const rowLvl = lvlFromPct(rowPctNum);
      g.domSkills.push({
        unitIdx: unitIdx>=0?unitIdx:999, posInUnit,
        unidadCol, intentosCol: String(_intentosPorTopic[h.topic]||1), dominioIco: rowLvl ? (_lvlIco[rowLvl]||'') : '', nombreCol,
        dateStr: fmtDate(sec), hourStr: fmtHour(sec),
        exercises: isAuto ? '—' : `${h.correct||0}/${h.total||0}`,
        pct: pctOf(h),
        timeStr: isAuto ? '—' : fmtTime(touched7.filter(h2=>h2.topic===h.topic&&!h2.autoFromExam&&!h2.autoFromQuiz).reduce((a,h2)=>a+(h2.timeSec||0),0))
      });
      touchedUnits.add(u);
    }
  });
  const activityTables = Object.values(courseGroups).map(g=>{
    const rows = g.domSkills.slice().sort((a,b)=>
      a.unitIdx-b.unitIdx || a.posInUnit-b.posInUnit);
    return { header: g.header, rows };
  }).filter(t=>t.rows.length);

  // ---- A reforzar: habilidades puras (sin cuestionarios ni bpu) de unidades tocadas esta semana
  // que aún no están dominadas (por cualquier medio, directo o indirecto).
  const reforzar = [];
  const seenReforzar = new Set();
  const reforzarCourseGroups = {};
  touchedUnits.forEach(u=>{
    const unitEntry = hist.find(h => _prepTopicUnit(h.topic, h.level) === u);
    if (!unitEntry) return;
    const ulevel = unitEntry.level, ugrade = unitEntry.grade || '';
    const editorial = u.editorial || null, areaKey = u.area || null;
    const courseUnits = ((PREP_CURRICULUM[ulevel]||{})[ugrade]||[])
      .filter(cu => (cu.editorial||null)===editorial && (cu.area||null)===areaKey);
    const unitIdx = courseUnits.indexOf(u);
    const unitNumStr = unitIdx >= 0 ? String(unitIdx+1).padStart(2,'0') : '';
    const unidadCol = unitNumStr ? `U${unitNumStr}` : '—';
    const unitSkills = (u.skills||[]).filter(_pureSkillFilter);
    const editorialInfo = editorial ? PREP_EDITORIALS[editorial] : null;
    const areaLbl = areaKey ? ((PREP_LEVELS[ulevel]?.areas||[]).find(a=>a.key===areaKey)?.lbl||'') : '';
    const levelLbl = PREP_LEVELS[ulevel]?.lbl || ulevel || '';
    const gradeLevel = [ugrade ? ugrade+'°' : '', levelLbl].filter(Boolean).join(' ');
    const extras = [editorialInfo?.lbl, areaLbl].filter(Boolean).join(' - ');
    const ico = editorialInfo?.ico || '📘';
    const courseKey = ulevel+'|'+ugrade+'|'+(editorial||'')+'|'+(areaKey||'');
    const courseHeader = extras ? `${ico} ${gradeLevel} - ${extras}` : `${ico} ${gradeLevel}`;
    unitSkills.forEach((sk, sIdx)=>{
      if (!BINGO_TOPICS[sk] || seenReforzar.has(sk)) return;
      const lvl = _prepMasteryLevelH(sk, hist);
      if (lvl === 'dominado') return;
      seenReforzar.add(sk);
      const pct = _prepLastPctH(sk, hist);
      const lbl = BINGO_TOPICS[sk].lbl || sk;
      const dominioIco = _lvlIco[lvl] || '';
      // Última sesión directa de esta habilidad (para Fecha/Hora/Ejercicios/%/Tiempo)
      const _lastSess = hist.filter(h=>h.topic===sk&&!h.autoFromExam&&!h.autoFromQuiz).sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0))[0];
      const _lSec = _lastSess?.completedAt?.seconds || 0;
      const _lPctNum = _lastSess ? pctNumOf(_lastSess) : null;
      const _lLvl = lvlFromPct(_lPctNum);
      if (!reforzarCourseGroups[courseKey]) reforzarCourseGroups[courseKey] = { header: courseHeader, rows: [] };
      reforzarCourseGroups[courseKey].rows.push({
        unidadCol,
        intentosCol: String(_intentosPorTopic[sk]||0),
        dominioIco: _lLvl ? (_lvlIco[_lLvl]||'') : dominioIco,
        nombreCol: lbl,
        dateStr: fmtDate(_lSec),
        hourStr: fmtHour(_lSec),
        exercises: _lastSess ? `${_lastSess.correct||0}/${_lastSess.total||0}` : '—',
        pct: _lPctNum !== null ? `${_lPctNum}%` : '—',
        timeStr: fmtTime(hist.filter(h2=>h2.topic===sk&&!h2.autoFromExam&&!h2.autoFromQuiz).reduce((a,h2)=>a+(h2.timeSec||0),0)),
        unitIdx: unitIdx>=0?unitIdx:999, sIdx
      });
      reforzar.push({ sk, lbl, lvl, pct });
    });
  });
  // Ordenar filas de cada curso por unidad y posición
  Object.values(reforzarCourseGroups).forEach(g => g.rows.sort((a,b)=>a.unitIdx-b.unitIdx||a.sIdx-b.sIdx));
  const reforzarList = reforzar.slice(0,6);

  const streak = _prepCalcStreakH(hist);
  const timeSecTotal = last7.reduce((a,h)=>a+(h.timeSec||0),0);
  const timeMin = Math.round(timeSecTotal/60);

  // Calcular tareas y pendientes antes de la recomendación
  const _myTasksP = (overrides[String(uid)]?.prepTasks) || [];
  const nowSecTP = Math.floor(Date.now()/1000);
  const pendingTaskNamesP = [];
  const taskRowsP = _myTasksP.map(t => {
    const _isExamT = !!t.exam;
    const _from = t.assignedAt || 0;
    const _to   = t.dueAt || Infinity;
    const overdue = t.dueAt && t.dueAt < nowSecTP;
    const dueStr = t.dueAt ? new Date(t.dueAt*1000).toLocaleDateString('es-PE',{day:'2-digit',month:'short'}) : '—';
    let nombre, done, pctVal;
    if (_isExamT) {
      nombre = t.label || 'Examen';
      const _firstSk = (t.skills||[]).find(sk=>BINGO_TOPICS[sk]&&!BINGO_TOPICS[sk].quiz)||(t.skills||[])[0];
      const sess = hist.filter(h=>{ const sec=h.completedAt?.seconds||0; return sec>=_from&&sec<=_to&&h.isUnitExam&&h.topic===_firstSk&&!h.autoFromExam&&!h.autoFromQuiz; });
      done = sess.length>0; pctVal = done ? _prepReEvalPct(sess[0]) : null;
    } else {
      nombre = (BINGO_TOPICS[t.topic]||{}).lbl || t.topic;
      const sess = hist.filter(h=>{ const sec=h.completedAt?.seconds||0; return sec>=_from&&sec<=_to&&h.topic===t.topic&&!h.autoFromExam&&!h.autoFromQuiz; });
      done = sess.length>0; pctVal = done ? _prepReEvalPct(sess[0]) : null;
    }
    if (!done) pendingTaskNamesP.push(nombre);
    const ico = done ? '✅' : (overdue ? '❌' : '⏳');
    const estado = done ? `${pctVal}%` : (overdue ? 'Vencida' : 'Pendiente');
    return { ico, nombre, estado, vence: dueStr };
  });

  const recTargets = reforzar.slice(0,2).map(r=>r.lbl);
  const recPartsP = [];
  if (recTargets.length) recPartsP.push(`reforzar ${recTargets.join(' y ')}`);
  if (pendingTaskNamesP.length) recPartsP.push(`completar ${pendingTaskNamesP.length===1?'la tarea':'las tareas'}: ${pendingTaskNamesP.slice(0,2).join(' y ')}`);
  const recommendation = recPartsP.length
    ? `Se sugiere ${recPartsP.join(', y también ')} esta semana.`
    : `¡Felicitaciones! ¡Buen avance esta semana! Sigue practicando para mantener el nivel.`;

  const tableHtml = (cols, rows) => {
    if (!rows.length) return '<div style="font-size:13px;color:rgba(0,0,0,0.5)">—</div>';
    const thead = `<tr>${cols.map(c=>`<th style="text-align:center;font-size:10px;color:#7c3aed;padding:4px 6px;border-bottom:1.5px solid #e9d5ff;white-space:nowrap">${esc(c.label)}</th>`).join('')}</tr>`;
    const tbody = rows.map((r,i)=>`<tr style="background:${i%2?'#faf5ff':'#ffffff'}">${cols.map(c=>`<td style="text-align:center;font-size:11px;color:#222;padding:4px 6px;border-bottom:1px solid #f1eafe;${c.nowrap?'white-space:nowrap':''}">${c.raw?c.get(r):esc(c.get(r))}</td>`).join('')}</tr>`).join('');
    return `<table style="width:100%;border-collapse:collapse;margin:4px 0 10px;font-variant-numeric:tabular-nums">${thead}${tbody}</table>`;
  };

  let html = '';
  html += `<div style="font-size:19px;font-weight:900;color:#7c3aed;margin-bottom:2px;text-align:center">📊 REPORTE ${_rTitleLbl} - ${esc(name.toUpperCase())}</div>`;
  html += `<div style="font-size:13px;color:rgba(0,0,0,0.55);margin-bottom:12px;text-align:center">📅 ${weekAgoStr} al ${todayStr}</div>`;

  html += `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">I. Cursos y unidades practicadas</div>`;
  if (!unitTables.length) {
    html += '<div style="font-size:13px;color:rgba(0,0,0,0.5)">—</div>';
  } else {
    // Una sola tabla combinada para todos los cursos, con filas divisoras (colspan) centradas por
    // curso — en vez de una tabla separada por curso — según el diseño "Opción A" aprobado.
    const _colsI = ['Unidad','Dominio','Hab.','Cuest.','Exam.','Fecha','Hora','Tiempo'];
    // El fondo morado del encabezado se pinta UNA sola vez sobre toda la fila (background en el
    // <tr>, celdas transparentes) en vez de celda por celda — pintar cada <th> por separado dejaba
    // huecos de 1px entre columnas al tomar la "foto" con html2canvas (redondeo de píxeles al
    // rasterizar varios rectángulos adyacentes). Las esquinas redondeadas ahora las da el
    // contenedor (overflow:hidden), no cada celda.
    let theadI = `<tr style="background:#7c3aed">${_colsI.map(c=>`<th style="text-align:center;font-size:9px;text-transform:uppercase;letter-spacing:0.05em;color:#fff;padding:6px 8px;white-space:nowrap">${esc(c)}</th>`).join('')}</tr>`;
    let bodyI = '';
    unitTables.forEach(t=>{
      bodyI += `<tr><td colspan="${_colsI.length}" style="text-align:center;font-size:10.5px;font-weight:800;letter-spacing:0.02em;color:#5b21b6;background:#efe6fc;padding:6px 8px">${esc(t.header)}</td></tr>`;
      t.rows.forEach((r,i)=>{
        const _bg = i%2 ? '#faf5ff' : '#ffffff';
        const _td = (content, extra) => `<td style="text-align:center;font-size:11px;color:#222;padding:5px 8px;border-bottom:1px solid #f1eafe;white-space:nowrap;${extra||''}">${content}</td>`;
        bodyI += `<tr style="background:${_bg}">`
          + _td(`${esc(r.unidadCol)} · ${esc(r.nombreCol)}`, 'white-space:normal')
          + `<td style="padding:5px 8px;border-bottom:1px solid #f1eafe">${r.dominioBadgeHtml}</td>`
          + _td(esc(r.habilidadesCol), 'font-weight:600')
          + _td(esc(r.cuestionarioCol), 'font-weight:600')
          + _td(esc(r.examenCol), 'font-weight:600')
          + _td(esc(r.lastDate))
          + _td(esc(r.lastHour))
          + _td(esc(r.timeStr))
          + `</tr>`;
      });
    });
    html += `<div style="border-radius:6px 6px 0 0;overflow:hidden;margin:4px 0 10px"><table style="width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums">${theadI}${bodyI}</table></div>`;
  }

  html += `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">II. Actividades practicadas</div>`;
  if (!activityTablesV2.length) html += '<div style="font-size:13px;color:rgba(0,0,0,0.5)">—</div>';
  const _actSmallBadge = lvl => {
    const info = lvl && _domBadgeInfo[lvl] ? _domBadgeInfo[lvl] : {bg:'#94a3b8', fg:'#fff', txt:'—'};
    return `<span style="display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:5px;background:${info.bg};font-size:8.5px;font-weight:900;color:${info.fg};letter-spacing:-0.4px;font-family:sans-serif;flex-shrink:0">${info.txt}</span>`;
  };
  const _actPendBadge = () => `<span style="display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:5px;background:#e5e7eb;font-size:8.5px;font-weight:900;color:#9ca3af;font-family:sans-serif;flex-shrink:0">—</span>`;
  const _actTagStyles = { hab:'background:#efe6fc;color:#7c3aed', quiz:'background:#ede9fe;color:#6d28d9', exam:'background:#fef3c7;color:#b45309', pend:'background:#f1f5f9;color:#94a3b8' };
  const _actTag = (text, kind) => `<span style="display:inline-block;padding:1.5px 6px;border-radius:5px;font-size:8.5px;font-weight:700;letter-spacing:0.02em;${_actTagStyles[kind]||_actTagStyles.hab}">${esc(text)}</span>`;
  const _colsII = ['Tipo','Dominio','Nombre','Intentos','Fecha','Ejerc.','Tiempo'];
  activityTablesV2.forEach(t=>{
    const _domPct = t.dominioProm===null ? 0 : t.dominioProm;
    const _domTxt = t.dominioProm===null ? '— dominio' : `${t.dominioProm}% dominio`;
    const _unidadesTxt = `${t.unitsPracticadas} unidad${t.unitsPracticadas===1?'':'es'} practicada${t.unitsPracticadas===1?'':'s'}`;
    html += `<div style="display:flex;align-items:center;gap:12px;padding:10px 14px;margin:16px 0 0;border-left:4px solid #7c3aed;background:#efe6fc;border-radius:0 8px 8px 0">`
      + `<span style="font-weight:800;font-size:12px;color:#241b33;flex:1">${esc(t.header)}<span style="display:block;font-weight:500;font-size:9.5px;color:rgba(36,27,51,0.62);margin-top:1px">${esc(_unidadesTxt)}</span></span>`
      + `<span style="width:90px;flex-shrink:0"><div style="height:5px;border-radius:3px;background:#ded0f7;overflow:hidden"><div style="height:100%;width:${_domPct}%;background:#7c3aed;border-radius:3px"></div></div><div style="font-size:9px;color:rgba(36,27,51,0.62);margin-top:3px;text-align:right">${esc(_domTxt)}</div></span>`
      + `</div>`;
    // Mismo criterio que en la Sección I: un solo fondo morado en el <tr> (no celda por celda) para
    // que no queden huecos de 1px entre columnas al tomar la "foto" con html2canvas.
    const theadII = `<tr style="background:#7c3aed">${_colsII.map((c,ci)=>`<th style="text-align:${ci===2?'left':'center'};font-size:9px;text-transform:uppercase;letter-spacing:0.05em;color:#fff;padding:6px 8px;white-space:nowrap">${esc(c)}</th>`).join('')}</tr>`;
    let bodyII = '';
    let _dataIdx = 0;
    t.rows.forEach(r=>{
      if (r.kind==='unit') {
        bodyII += `<tr><td colspan="${_colsII.length}" style="text-align:center;font-size:10.5px;font-weight:800;letter-spacing:0.02em;color:#5b21b6;background:#efe6fc;padding:6px 8px">${esc(r.label)}</td></tr>`;
      } else if (r.kind==='group') {
        bodyII += `<tr><td colspan="${_colsII.length}" style="text-align:left;font-size:9.5px;font-weight:700;letter-spacing:0.02em;color:#8b5cf6;background:#faf7ff;padding:5px 8px;border-left:3px solid #c4b5fd">${esc(r.label)}</td></tr>`;
      } else {
        const isPending = !!r.pending;
        const _bg = isPending ? '#ffffff' : (r.isExam ? '#fff7ed' : (_dataIdx%2 ? '#faf5ff' : '#ffffff'));
        if (!isPending) _dataIdx++;
        const _fw = r.isExam && !isPending ? 'font-weight:600;' : '';
        const _tagKind = isPending ? 'pend' : (r.isExam ? 'exam' : (r.tipoCol && r.tipoCol[0]==='C' ? 'quiz' : 'hab'));
        const _td = (content, extra) => `<td style="text-align:center;font-size:10.5px;color:${isPending?'#a3a0ac':'#222'};padding:5px 7px;border-bottom:1px solid #f1eafe;white-space:nowrap;${_fw}${extra||''}">${content}</td>`;
        bodyII += `<tr style="background:${_bg}">`
          + _td(_actTag(r.tipoCol, _tagKind))
          + `<td style="text-align:center;padding:5px 7px;border-bottom:1px solid #f1eafe;${_fw}">${isPending?_actPendBadge():_actSmallBadge(r.lvl)}</td>`
          + _td(esc(r.nombreCol), `text-align:left;white-space:normal;${isPending?'font-style:italic;':''}`)
          + _td(isPending?'—':esc(r.intentosCol))
          + _td(isPending?'—':esc(r.dateStr))
          + _td(isPending?'—':esc(r.exercises))
          + _td(isPending?'—':esc(r.timeStr))
          + `</tr>`;
      }
    });
    html += `<div style="border-radius:6px 6px 0 0;overflow:hidden;margin:12px 0 10px"><table style="width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums">${theadII}${bodyII}</table></div>`;
  });

  const _reforzarGroups = Object.values(reforzarCourseGroups).filter(g=>g.rows.length);
  if (_reforzarGroups.length) {
    html += `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">III. A reforzar</div>`;
    _reforzarGroups.forEach(g=>{
      html += `<div style="font-size:12px;font-weight:700;color:#444;margin-top:8px">${esc(g.header)}</div>`;
      html += tableHtml([
        { label:'Unidad',     get:r=>r.unidadCol,    nowrap:true },
        { label:'Intentos',   get:r=>r.intentosCol,  nowrap:true },
        { label:'Dominio',    get:r=>r.dominioIco,   nowrap:true, raw:true },
        { label:'Nombre',     get:r=>r.nombreCol },
        { label:'Fecha',      get:r=>r.dateStr,      nowrap:true },
        { label:'Hora',       get:r=>r.hourStr,      nowrap:true },
        { label:'Ejercicios', get:r=>r.exercises,    nowrap:true },
        { label:'%',          get:r=>r.pct,          nowrap:true },
        { label:'Tiempo',     get:r=>r.timeStr,      nowrap:true },
      ], g.rows);
    });
  }

  // ---- Tabla de tiempo practicado por día ----
  const _dayNames = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
  const _weekDays = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate()-i);
    const dEnd = new Date(d); dEnd.setDate(dEnd.getDate()+1);
    const dSec = Math.floor(d.getTime()/1000), dEndSec = Math.floor(dEnd.getTime()/1000);
    const daySess = last7.filter(h=>{ const s=h.completedAt?.seconds||0; return s>=dSec && s<dEndSec && !h.autoFromExam && !h.autoFromQuiz; });
    const dayTime = daySess.reduce((a,h)=>a+(h.timeSec||0),0);
    const dayMin = Math.round(dayTime/60);
    const dayCount = daySess.length;
    const practiced = dayTime > 0;
    _weekDays.push({
      name: _dayNames[d.getDay()],
      date: d.toLocaleDateString('es-PE',{day:'2-digit',month:'short'}),
      timeStr: practiced ? (dayMin < 60 ? `${dayMin} min` : `${Math.floor(dayMin/60)}h ${dayMin%60}m`) : '—',
      countStr: practiced ? `${dayCount} act.` : '—',
      practiced
    });
  }
  // ---- IV. Desafíos de Dominio ----
  const _desafio7P = last7.filter(h => h.level === 'especial' && !h.autoFromExam && !h.autoFromQuiz);
  const _nivelLblDP = ['','Básico','Intermedio','Avanzado'];
  // Contar intentos por reto+nivel esta semana
  const _desafioIntentos = {};
  _desafio7P.forEach(h => {
    const _k = (h.retoLbl || _prepDesafioRetoFromTopic(h.topic)||'?') + '|' + (h.desafioNivel||1);
    _desafioIntentos[_k] = (_desafioIntentos[_k]||0) + 1;
  });
  const _desafioRowsP = _desafio7P.map(h => {
    const _dRetoP = h.retoLbl || _prepDesafioRetoFromTopic(h.topic) || '?';
    const _dNivelStr = h.desafioNivel ? (_nivelLblDP[h.desafioNivel]||'') : '';
    const _dKey = _dRetoP + '|' + (h.desafioNivel||1);
    const rowPctNum = h.pct != null ? Math.round(h.pct) : (h.total ? Math.round((h.correct||0)/h.total*100) : null);
    const dominioIco = rowPctNum === null ? '<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#94a3b8;font-size:13px;font-weight:900;color:#fff;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">—</span>' : rowPctNum >= 100 ? '<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#7c3aed;font-size:12px;font-weight:900;color:#fff;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">A+</span>' : rowPctNum >= 75 ? '<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#9333ea;font-size:13px;font-weight:900;color:#fff;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">A</span>' : rowPctNum >= 50 ? '<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#c084fc;font-size:13px;font-weight:900;color:#581c87;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">B</span>' : rowPctNum >= 25 ? '<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#e9d5ff;font-size:13px;font-weight:900;color:#6d28d9;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">C</span>' : '<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:#fdf4ff;font-size:13px;font-weight:900;color:#9333ea;letter-spacing:-0.5px;font-family:sans-serif;flex-shrink:0">D</span>';
    const sec = h.completedAt?.seconds || 0;
    return {
      nivelCol: _dNivelStr || '—',
      intentosCol: String(_desafioIntentos[_dKey]||1),
      dominioIco,
      nombre: _dRetoP,
      dateStr: fmtDate(sec),
      hourStr: fmtHour(sec),
      exercises: `${h.correct||0}/${h.total||0}`,
      pct: rowPctNum !== null ? `${rowPctNum}%` : '—',
      timeStr: fmtTime(h.timeSec),
      _sortKey: _dRetoP
    };
  }).sort((a,b) => a._sortKey < b._sortKey ? -1 : a._sortKey > b._sortKey ? 1 : 0);
  if (_desafioRowsP.length) {
    html += `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">IV. Desafíos de Dominio</div>`;
    html += tableHtml([
      { label:'Nivel',      get:r=>r.nivelCol,     nowrap:true },
      { label:'Intentos',   get:r=>r.intentosCol,  nowrap:true },
      { label:'Dominio',    get:r=>r.dominioIco,   nowrap:true, raw:true },
      { label:'Nombre',     get:r=>r.nombre },
      { label:'Fecha',      get:r=>r.dateStr,      nowrap:true },
      { label:'Hora',       get:r=>r.hourStr,      nowrap:true },
      { label:'Ejercicios', get:r=>r.exercises,    nowrap:true },
      { label:'%',          get:r=>r.pct,          nowrap:true },
      { label:'Tiempo',     get:r=>r.timeStr,      nowrap:true },
    ], _desafioRowsP);
  }

  // ---- V. Tareas ----
  if (taskRowsP.length) {
    html += `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">V. Tareas</div>`;
    html += tableHtml([
      { label:'',       get:r=>r.ico,    nowrap:true },
      { label:'Tarea',  get:r=>r.nombre },
      { label:'Estado', get:r=>r.estado, nowrap:true },
      { label:'Vence',  get:r=>r.vence,  nowrap:true },
    ], taskRowsP);
  }

  html += `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">VI. Tiempo practicado esta semana</div>`;
  html += `<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:4px 0 10px;font-variant-numeric:tabular-nums"><colgroup>${_weekDays.map(()=>'<col style="width:14.28%">').join('')}</colgroup>`;
  // Fila de días (encabezado con color)
  html += `<tr>${_weekDays.map(d=>`<th style="text-align:center;font-size:11px;font-weight:900;padding:6px 4px;border-radius:4px 4px 0 0;background:${d.practiced?'#7c3aed':'#d1d5db'};box-shadow:0 0 0 1px ${d.practiced?'#7c3aed':'#d1d5db'};color:${d.practiced?'#fff':'#6b7280'}">${d.name}<br><span style="font-size:9px;font-weight:400">${d.date}</span></th>`).join('')}</tr>`;
  // Fila de tiempo
  html += `<tr>${_weekDays.map(d=>`<td style="text-align:center;font-size:11px;color:#222;padding:4px 2px;border-bottom:1px solid #f1eafe">⏱ ${d.timeStr}</td>`).join('')}</tr>`;
  // Fila de actividades
  html += `<tr>${_weekDays.map(d=>`<td style="text-align:center;font-size:11px;color:#222;padding:4px 2px;border-bottom:1.5px solid #e9d5ff">📚 ${d.countStr}</td>`).join('')}</tr>`;
  html += `</table>`;
  const _totalSemanaStr = timeMin < 60 ? `${timeMin} min` : `${Math.floor(timeMin/60)}h ${timeMin%60}m`;
  html += `<div style="font-size:11px;color:#222;text-align:center;margin-top:6px">🔥 Racha: ${streak} día${streak===1?'':'s'} seguido${streak===1?'':'s'}&nbsp;&nbsp;|&nbsp;&nbsp;⏱️ Total semana: ${_totalSemanaStr}</div>`;

  html += `<div style="font-size:14px;font-weight:900;color:#7c3aed;margin:14px 0 6px">VII. Recomendación</div>`;
  html += `<div style="font-size:13px;color:#222;line-height:1.55">${esc(recommendation)}</div>`;

  // VII. Habilidades dominadas esta semana
  const dominatedCountP = [...new Set(touched7.map(h=>h.topic))]
    .filter(topic => _pureSkillFilter(topic) && _prepMasteryLevelH(topic, hist) === 'dominado')
    .length;
  if (dominatedCountP) {
    html += `<div style="font-size:13px;color:#222;line-height:1.55;margin-top:10px">🏆 ¡${esc(name)} ha dominado ${dominatedCountP} habilidad${dominatedCountP===1?'':'es'} nueva${dominatedCountP===1?'':'s'} esta semana! ¡Sigue así!</div>`;
  }

  html += `<div style="font-size:11px;color:rgba(0,0,0,0.35);margin-top:12px;letter-spacing:0.08em;font-weight:700">MATHS LEVEL UP</div>`;
  return html;
}
async function _prepDownloadWeeklyReportPDF() {
  if (typeof html2canvas === 'undefined' || !(window.jspdf && window.jspdf.jsPDF)) {
    if (typeof showToast==='function') showToast('No se pudo generar el PDF (falta librería)','error');
    return;
  }
  const students = getStudents();
  const stu = students.find(s=>String(s.id)===String(_prepWeeklyReportUid));
  const name = stu ? stu.name : 'Alumno';
  const holder = document.createElement('div');
  holder.style.cssText = 'position:fixed;left:-9999px;top:0;width:600px;background:#ffffff;padding:28px;box-sizing:border-box;font-family:\'IBM Plex Sans\',Arial,Helvetica,sans-serif';
  holder.innerHTML = `<div style="font-size:12px;font-weight:900;color:#a855f7;letter-spacing:0.1em;margin-bottom:14px;text-align:center">MATHS LEVEL UP</div>`
    + _prepBuildWeeklyReportPdfHtml(_prepWeeklyReportUid, _prepWeeklyReportHist);
  document.body.appendChild(holder);
  await document.fonts.ready;
  try {
    const canvas = await html2canvas(holder, { scale:2, backgroundColor:'#ffffff' });
    const holderRect = holder.getBoundingClientRect();
    const scaleX = canvas.width / holderRect.width;
    // Bordes inferiores (en px del canvas) de cada línea/elemento del reporte Y de cada fila de
    // tabla, para nunca cortar una línea (ni una fila de tabla) a la mitad entre dos páginas.
    const breakPoints = [];
    const addBreak = function(el){
      const r = el.getBoundingClientRect();
      const bottom = Math.round((r.bottom - holderRect.top) * scaleX);
      if (bottom > 0) breakPoints.push(bottom);
    };
    Array.prototype.forEach.call(holder.children, addBreak);
    Array.prototype.forEach.call(holder.querySelectorAll('tr'), addBreak);
    breakPoints.push(canvas.height);
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF({ unit:'pt', format:'a4' });
    const pageW = pdf.internal.pageSize.getWidth();
    const pageH = pdf.internal.pageSize.getHeight();
    const margin = 28;
    const imgW = pageW - margin*2;
    const pxPerPt = canvas.width / imgW;
    const pageContentPt = pageH - margin*2;
    const pageContentPx = Math.max(1, Math.floor(pageContentPt * pxPerPt));
    let y = 0;
    let first = true;
    while (y < canvas.height) {
      const maxEnd = Math.min(y + pageContentPx, canvas.height);
      let sliceEnd = null;
      for (let i=0;i<breakPoints.length;i++){
        const bp = breakPoints[i];
        if (bp > y && bp <= maxEnd) sliceEnd = bp;
      }
      if (sliceEnd === null) sliceEnd = maxEnd; // línea más alta que una página: se corta como último recurso
      const sliceH = sliceEnd - y;
      const pageCanvas = document.createElement('canvas');
      pageCanvas.width = canvas.width;
      pageCanvas.height = sliceH;
      const ctx = pageCanvas.getContext('2d');
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, pageCanvas.width, pageCanvas.height);
      ctx.drawImage(canvas, 0, y, canvas.width, sliceH, 0, 0, canvas.width, sliceH);
      const sliceImgData = pageCanvas.toDataURL('image/png');
      const sliceHPt = sliceH / pxPerPt;
      if (!first) pdf.addPage();
      pdf.addImage(sliceImgData, 'PNG', margin, margin, imgW, sliceHPt);
      first = false;
      y = sliceEnd;
    }
    const safeName = (name||'Alumno').replace(/[^a-z0-9]+/gi,'_');
    const dateStr = new Date().toLocaleDateString('es-PE',{day:'2-digit',month:'2-digit',year:'numeric'}).replace(/\//g,'-');
    pdf.save(`Reporte_${safeName}_${dateStr}.pdf`);
  } catch(e) {
    console.error('weekly report pdf export', e);
    if (typeof showToast==='function') showToast('No se pudo generar el PDF','error');
  } finally {
    document.body.removeChild(holder);
  }
}
