function _genCombB4(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,50);v=a+k-pq;}while(v<=0);return{algo:'comb',tokens:[a,'+',r,'÷',s,'-',p,'×',q],a:String(v),q:`${a} + ${r} ÷ ${s} − ${p} × ${q}`};}
