function _genCombB7(){let p,q,s,xy,a,b,v;do{[p,q,s,xy]=_cdMulDiv();a=_dsRi(1,30);b=_dsRi(Math.max(1,xy-a+1),50);v=a-xy+b;}while(v<=0);return{algo:'comb',tokens:[a,'-',p,'×',q,'÷',s,'+',b],a:String(v),q:`${a} − ${p} × ${q} ÷ ${s} + ${b}`};}
function _genCombB8(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,50);v=a-k+pq;}while(v<=0);return{algo:'comb',tokens:[a,'-',r,'÷',s,'+',p,'×',q],a:String(v),q:`${a} − ${r} ÷ ${s} + ${p} × ${q}`};}
function _genCombB9(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(Math.max(1,k-pq+1),50);v=pq+a-k;}while(v<=0);return{algo:'comb',tokens:[p,'×',q,'+',a,'-',r,'÷',s],a:String(v),q:`${p} × ${q} + ${a} − ${r} ÷ ${s}`};}
function _genCombB10(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,pq+k-1);v=pq+k-a;}while(v<=0);return{algo:'comb',tokens:[p,'×',q,'+',r,'÷',s,'-',a],a:String(v),q:`${p} × ${q} + ${r} ÷ ${s} − ${a}`};}
function _genCombB11(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,pq);v=pq-a+k;}while(v<=0);return{algo:'comb',tokens:[p,'×',q,'-',a,'+',r,'÷',s],a:String(v),q:`${p} × ${q} − ${a} + ${r} ÷ ${s}`};}
function _genCombB12(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(Math.max(1,k-pq+1),50);v=pq-k+a;}while(v<=0);return{algo:'comb',tokens:[p,'×',q,'-',r,'÷',s,'+',a],a:String(v),q:`${p} × ${q} − ${r} ÷ ${s} + ${a}`};}
function _genCombB13(){let p,q,s,xy,a,b,v;do{[p,q,s,xy]=_cdMulDiv();a=_dsRi(1,30);b=_dsRi(1,xy+a-1);v=xy+a-b;}while(v<=0);return{algo:'comb',tokens:[p,'×',q,'÷',s,'+',a,'-',b],a:String(v),q:`${p} × ${q} ÷ ${s} + ${a} − ${b}`};}
function _genCombB14(){let p,q,s,xy,a,b,v;do{[p,q,s,xy]=_cdMulDiv();a=_dsRi(1,xy);b=_dsRi(1,50);v=xy-a+b;}while(v<=0);return{algo:'comb',tokens:[p,'×',q,'÷',s,'-',a,'+',b],a:String(v),q:`${p} × ${q} ÷ ${s} − ${a} + ${b}`};}
function _genCombB15(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(Math.max(1,pq-k+1),50);v=k+a-pq;}while(v<=0);return{algo:'comb',tokens:[r,'÷',s,'+',a,'-',p,'×',q],a:String(v),q:`${r} ÷ ${s} + ${a} − ${p} × ${q}`};}
function _genCombB16(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,k+pq-1);v=k+pq-a;}while(v<=0);return{algo:'comb',tokens:[r,'÷',s,'+',p,'×',q,'-',a],a:String(v),q:`${r} ÷ ${s} + ${p} × ${q} − ${a}`};}
function _genCombB17(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,k+pq-1);v=k-a+pq;}while(v<=0);return{algo:'comb',tokens:[r,'÷',s,'-',a,'+',p,'×',q],a:String(v),q:`${r} ÷ ${s} − ${a} + ${p} × ${q}`};}
function _genCombB18(){let p,q,pq,r,s,k,a,v;do{[p,q,pq]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(Math.max(1,pq-k+1),50);v=k-pq+a;}while(v<=0);return{algo:'comb',tokens:[r,'÷',s,'-',p,'×',q,'+',a],a:String(v),q:`${r} ÷ ${s} − ${p} × ${q} + ${a}`};}
// ─── INTERMEDIO: 6 ops (+,− ≥1; × y ÷ se repiten), 7 números ────────────────
function _genCombI1(){let p1,q1,pq1,p2,q2,pq2,r,s,k,a,v;do{[p1,q1,pq1]=_cdMul();[p2,q2,pq2]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,50);v=pq1+pq2+k-a;}while(v<=0);return{algo:'comb',tokens:[p1,'×',q1,'+',p2,'×',q2,'+',r,'÷',s,'-',a],a:String(v),q:`${p1}×${q1} + ${p2}×${q2} + ${r}÷${s} − ${a}`};}
function _genCombI2(){let p1,q1,pq1,p2,q2,pq2,r,s,k,a,v;do{[p1,q1,pq1]=_cdMul();[p2,q2,pq2]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,50);v=pq1+pq2-k+a;}while(v<=0);return{algo:'comb',tokens:[p1,'×',q1,'+',p2,'×',q2,'-',r,'÷',s,'+',a],a:String(v),q:`${p1}×${q1} + ${p2}×${q2} − ${r}÷${s} + ${a}`};}
function _genCombI3(){let r1,s1,k1,r2,s2,k2,p,q,pq,a,v;do{[r1,s1,k1]=_cdDiv();[r2,s2,k2]=_cdDiv();[p,q,pq]=_cdMul();a=_dsRi(1,50);v=k1+k2+pq-a;}while(v<=0);return{algo:'comb',tokens:[r1,'÷',s1,'+',r2,'÷',s2,'+',p,'×',q,'-',a],a:String(v),q:`${r1}÷${s1} + ${r2}÷${s2} + ${p}×${q} − ${a}`};}
function _genCombI4(){let r1,s1,k1,r2,s2,k2,p,q,pq,a,v;do{[r1,s1,k1]=_cdDiv();[r2,s2,k2]=_cdDiv();[p,q,pq]=_cdMul();a=_dsRi(1,50);v=k1+k2-pq+a;}while(v<=0);return{algo:'comb',tokens:[r1,'÷',s1,'+',r2,'÷',s2,'-',p,'×',q,'+',a],a:String(v),q:`${r1}÷${s1} + ${r2}÷${s2} − ${p}×${q} + ${a}`};}
function _genCombI5(){let p1,q1,pq1,p2,q2,pq2,r,s,k,a,v;do{[p1,q1,pq1]=_cdMul();[p2,q2,pq2]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,50);v=pq1-pq2+k+a;}while(v<=0);return{algo:'comb',tokens:[p1,'×',q1,'-',p2,'×',q2,'+',r,'÷',s,'+',a],a:String(v),q:`${p1}×${q1} − ${p2}×${q2} + ${r}÷${s} + ${a}`};}
function _genCombI6(){let r,s,k,p1,q1,pq1,p2,q2,pq2,a,v;do{[r,s,k]=_cdDiv();[p1,q1,pq1]=_cdMul();[p2,q2,pq2]=_cdMul();a=_dsRi(1,50);v=k+pq1+pq2-a;}while(v<=0);return{algo:'comb',tokens:[r,'÷',s,'+',p1,'×',q1,'+',p2,'×',q2,'-',a],a:String(v),q:`${r}÷${s} + ${p1}×${q1} + ${p2}×${q2} − ${a}`};}
function _genCombI7(){let r,s,k,p1,q1,pq1,p2,q2,pq2,a,v;do{[r,s,k]=_cdDiv();[p1,q1,pq1]=_cdMul();[p2,q2,pq2]=_cdMul();a=_dsRi(1,50);v=k-pq1+pq2+a;}while(v<=0);return{algo:'comb',tokens:[r,'÷',s,'-',p1,'×',q1,'+',p2,'×',q2,'+',a],a:String(v),q:`${r}÷${s} − ${p1}×${q1} + ${p2}×${q2} + ${a}`};}
function _genCombI8(){let p1,q1,pq1,p2,q2,pq2,p3,q3,pq3,a,v;do{[p1,q1,pq1]=_cdMul();[p2,q2,pq2]=_cdMul();[p3,q3,pq3]=_cdMul();a=_dsRi(1,50);v=pq1+pq2-pq3+a;}while(v<=0);return{algo:'comb',tokens:[p1,'×',q1,'+',p2,'×',q2,'-',p3,'×',q3,'+',a],a:String(v),q:`${p1}×${q1} + ${p2}×${q2} − ${p3}×${q3} + ${a}`};}
function _genCombI9(){let r1,s1,k1,r2,s2,k2,p,q,pq,a,v;do{[r1,s1,k1]=_cdDiv();[r2,s2,k2]=_cdDiv();[p,q,pq]=_cdMul();a=_dsRi(1,50);v=k1-k2+pq+a;}while(v<=0);return{algo:'comb',tokens:[r1,'÷',s1,'-',r2,'÷',s2,'+',p,'×',q,'+',a],a:String(v),q:`${r1}÷${s1} − ${r2}÷${s2} + ${p}×${q} + ${a}`};}
function _genCombI10(){let p,q,s1,xy,r,s2,k,a,b,v;do{[p,q,s1,xy]=_cdMulDiv();[r,s2,k]=_cdDiv();a=_dsRi(1,30);b=_dsRi(1,50);v=xy+k+a-b;}while(v<=0);return{algo:'comb',tokens:[p,'×',q,'÷',s1,'+',r,'÷',s2,'+',a,'-',b],a:String(v),q:`${p}×${q}÷${s1} + ${r}÷${s2} + ${a} − ${b}`};}
function _genCombI11(){let p1,q1,pq1,a,p2,q2,pq2,r,s,k,v;do{[p1,q1,pq1]=_cdMul();a=_dsRi(1,50);[p2,q2,pq2]=_cdMul();[r,s,k]=_cdDiv();v=pq1+a-pq2+k;}while(v<=0);return{algo:'comb',tokens:[p1,'×',q1,'+',a,'-',p2,'×',q2,'+',r,'÷',s],a:String(v),q:`${p1}×${q1} + ${a} − ${p2}×${q2} + ${r}÷${s}`};}
function _genCombI12(){let r1,s1,k1,p,q,pq,a,r2,s2,k2,v;do{[r1,s1,k1]=_cdDiv();[p,q,pq]=_cdMul();a=_dsRi(1,50);[r2,s2,k2]=_cdDiv();v=k1+pq-a+k2;}while(v<=0);return{algo:'comb',tokens:[r1,'÷',s1,'+',p,'×',q,'-',a,'+',r2,'÷',s2],a:String(v),q:`${r1}÷${s1} + ${p}×${q} − ${a} + ${r2}÷${s2}`};}
// ─── AVANZADO: agrupador obligatorio, cualquier op adentro ───────────────────
function _genCombA1(){let p1,q1,pq1,a,inn,p2,r,s,k,b,v;do{[p1,q1,pq1]=_cdMul();a=_dsRi(5,40);inn=pq1+a;p2=_dsRi(2,9);[r,s,k]=_cdDiv();b=_dsRi(1,inn*p2+k-1);v=inn*p2+k-b;}while(v<=0||inn*p2>9999);return{algo:'comb',tokens:['(',p1,'×',q1,'+',a,')','×',p2,'+',r,'÷',s,'-',b],a:String(v),q:`(${p1}×${q1}+${a})×${p2}+${r}÷${s}−${b}`};}
function _genCombA2(){let r,s,k,p1,q1,pq1,a,inn,p2,b,v;do{[r,s,k]=_cdDiv();[p1,q1,pq1]=_cdMul();a=_dsRi(1,k+pq1-1);inn=k+pq1-a;p2=_dsRi(2,9);b=_dsRi(1,50);v=inn*p2+b;}while(v<=0||inn<=0||inn*p2>9999);return{algo:'comb',tokens:['[',r,'÷',s,'+',p1,'×',q1,'-',a,']','×',p2,'+',b],a:String(v),q:`[${r}÷${s}+${p1}×${q1}−${a}]×${p2}+${b}`};}
function _genCombA3(){let p1,q1,pq1,r,s,k,a,inn,p2,b,v;do{[p1,q1,pq1]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,50);inn=pq1-k+a;p2=_dsRi(2,9);b=_dsRi(1,50);v=inn*p2-b;}while(v<=0||inn<=0||inn*p2>9999);return{algo:'comb',tokens:['{',p1,'×',q1,'-',r,'÷',s,'+',a,'}','×',p2,'-',b],a:String(v),q:`{${p1}×${q1}−${r}÷${s}+${a}}×${p2}−${b}`};}
function _genCombA4(){let p1,q1,pq1,r,s,k,a,b,inn,p2,c,v;do{[p1,q1,pq1]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,30);b=_dsRi(1,Math.max(1,k+a-1));inn=k+a-b;p2=_dsRi(2,9);c=_dsRi(1,50);v=pq1+inn*p2-c;}while(v<=0||inn<=0||inn*p2>9999);return{algo:'comb',tokens:[p1,'×',q1,'+','(',r,'÷',s,'+',a,'-',b,')','×',p2,'-',c],a:String(v),q:`${p1}×${q1}+(${r}÷${s}+${a}−${b})×${p2}−${c}`};}
function _genCombA5(){let r,s,k,p1,q1,pq1,p2,q2,pq2,a,inn,b,v;do{[r,s,k]=_cdDiv();[p1,q1,pq1]=_cdMul();[p2,q2,pq2]=_cdMul();a=_dsRi(1,pq1+pq2-1);inn=pq1+pq2-a;b=_dsRi(1,50);v=k+inn-b;}while(v<=0||inn<=0);return{algo:'comb',tokens:[r,'÷',s,'+','[',p1,'×',q1,'+',p2,'×',q2,'-',a,']','-',b],a:String(v),q:`${r}÷${s}+[${p1}×${q1}+${p2}×${q2}−${a}]−${b}`};}
function _genCombA6(){let r,s,k,a,p,q,pq,b,inn,p2,c,v;do{[r,s,k]=_cdDiv();a=_dsRi(1,30);[p,q,pq]=_cdMul();b=_dsRi(1,30);inn=k+a-pq+b;p2=_dsRi(2,9);c=_dsRi(1,50);v=inn*p2-c;}while(v<=0||inn<=0||inn*p2>9999);return{algo:'comb',tokens:['(',r,'÷',s,'+',a,'-',p,'×',q,'+',b,')','×',p2,'-',c],a:String(v),q:`(${r}÷${s}+${a}−${p}×${q}+${b})×${p2}−${c}`};}
function _genCombA7(){let p1,q1,pq1,r,s,k,a,b,c,inn,p2,d,v;do{[p1,q1,pq1]=_cdMul();[r,s,k]=_cdDiv();a=_dsRi(1,20);b=_dsRi(1,20);c=_dsRi(1,Math.max(1,pq1+k-a+b-1));inn=pq1+k-a+b-c;p2=_dsRi(2,9);d=_dsRi(1,50);v=inn*p2+d;}while(v<=0||inn<=0||inn*p2>9999);return{algo:'comb',tokens:['{',p1,'×',q1,'+',r,'÷',s,'-',a,'+',b,'-',c,'}','×',p2,'+',d],a:String(v),q:`{${p1}×${q1}+${r}÷${s}−${a}+${b}−${c}}×${p2}+${d}`};}
function _genCombA8(){let p1,q1,pq1,r,s,k,p2,q2,pq2,a,inn,b,v;do{[p1,q1,pq1]=_cdMul();[r,s,k]=_cdDiv();[p2,q2,pq2]=_cdMul();a=_dsRi(1,30);inn=pq1-k+pq2+a;b=_dsRi(1,inn-1);v=inn-b;}while(v<=0||inn<=0);return{algo:'comb',tokens:['[',p1,'×',q1,'-',r,'÷',s,'+',p2,'×',q2,'+',a,']','-',b],a:String(v),q:`[${p1}×${q1}−${r}÷${s}+${p2}×${q2}+${a}]−${b}`};}
function _genCombA9(){let r1,s1,k1,p,q,pq,a,r2,s2,k2,b,inn,p2,c,v;do{[r1,s1,k1]=_cdDiv();[p,q,pq]=_cdMul();a=_dsRi(1,20);[r2,s2,k2]=_cdDiv();b=_dsRi(1,20);p2=_dsRi(2,9);const raw=k1+pq+a-k2+b;const rem=((raw%p2)+p2)%p2;c=rem||p2;inn=raw-c;}while(inn<=0);v=inn/p2;return{algo:'comb',tokens:['(',r1,'÷',s1,'+',p,'×',q,'+',a,'-',r2,'÷',s2,'+',b,'-',c,')','÷',p2],a:String(v),q:`(${r1}÷${s1}+${p}×${q}+${a}−${r2}÷${s2}+${b}−${c})÷${p2}`};}
function _genCombA10(){let r1,s1,k1,p1,q1,pq1,a,b2,q2c,bc,r2,s2,k2,d,inn,p3,q3,pq3,v;do{[r1,s1,k1]=_cdDiv();[p1,q1,pq1]=_cdMul();a=_dsRi(1,20);b2=_dsRi(2,9);q2c=_dsRi(10,99);bc=b2*q2c;[r2,s2,k2]=_cdDiv();d=_dsRi(1,20);inn=pq1-a+bc-k2+d;[p3,q3,pq3]=_cdMul();v=k1+inn-pq3;}while(v<=0||inn<=0);return{algo:'comb',tokens:[r1,'÷',s1,'+','{',p1,'×',q1,'-',a,'+',b2,'×',q2c,'-',r2,'÷',s2,'+',d,'}','-',p3,'×',q3],a:String(v),q:`${r1}÷${s1}+{${p1}×${q1}−${a}+${b2}×${q2c}−${r2}÷${s2}+${d}}−${p3}×${q3}`};}
// ECUACIÓN
function _genDsEq1(){const x=_dsRi(1,20),a=_dsRi(1,20),b=x+a;return{algo:'eq',expr:`x + ${a} = ${b}`,a:String(x),q:`x + ${a} = ${b}`};}
function _genDsEq2(){const x=_dsRi(2,15),a=_dsRi(2,12),b=x*a;return{algo:'eq',expr:`${a} × x = ${b}`,a:String(x),q:`${a} × x = ${b}`};}
function _genDsEq3(){const a=_dsRi(2,9),x=_dsRi(2,20),b=_dsRi(1,50),c=a*x+b;return{algo:'eq',expr:`${a} × x + ${b} = ${c}`,a:String(x),q:`${a} × x + ${b} = ${c}`};}
const _desafioGens={
  'Suma':{1:_genDsSuma1,2:_genDsSuma2,3:_genDsSuma3},
  'Resta':{1:_genDsResta1,2:_genDsResta2,3:_genDsResta3},
  'Multiplicación':{1:_genDsMult1,2:_genDsMult2,3:_genDsMult3},
  'Multiplicacion':{1:_genDsMult1,2:_genDsMult2,3:_genDsMult3},
  'División':{1:_genDsDiv1,2:_genDsDiv2,3:_genDsDiv3},
  'Division':{1:_genDsDiv1,2:_genDsDiv2,3:_genDsDiv3},
  'Op. Combinada':{
    1:()=>{const p=[_genCombB1,_genCombB2,_genCombB3,_genCombB4,_genCombB5,_genCombB6,_genCombB7,_genCombB8,_genCombB9,_genCombB10,_genCombB11,_genCombB12,_genCombB13,_genCombB14,_genCombB15,_genCombB16,_genCombB17,_genCombB18,_genCombB19,_genCombB20];return p[_dsRi(0,p.length-1)]();},
    2:()=>{const p=[_genCombI1,_genCombI2,_genCombI3,_genCombI4,_genCombI5,_genCombI6,_genCombI7,_genCombI8,_genCombI9,_genCombI10,_genCombI11,_genCombI12,_genCombI13,_genCombI14];return p[_dsRi(0,p.length-1)]();},
    // Avanzado: SIEMPRE 8 operadores en total — ×,÷,+,−,^,√ garantizados (uno de cada), más 2 extra al
    // azar — así que solo estos dos generadores (que garantizan esa composición) se usan aquí, en vez
    // del pool anterior donde el exponente y la raíz solo aparecían en 2 de 12 ejercicios al azar.
    3:()=>{const p=[_genCombA13,_genCombA14];return p[_dsRi(0,p.length-1)]();}
  },
  'Ecuación':{1:_genDsEq1,2:_genDsEq2,3:_genDsEq3},
  'Ecuacion':{1:_genDsEq1,2:_genDsEq2,3:_genDsEq3}
};
function _prepDesafioExam(retoLbl,nivel,skills,uIdx){
  const gen=_desafioGens[retoLbl]?.[nivel];
  if(!gen)return;
  const total=10,qs=[];
  let att=0;
  while(qs.length<total&&att<100){att++;const q=gen();if(q)qs.push(q);}
  for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]];}
  _prep.topic=(skills||[])[0]||'';
  _prep.isUnitExam=true; _prep.examUnitSkills=[...(skills||[])];
  _prep.selectedExamLbl=retoLbl; _prep.desafioNivel=nivel;
  _prep.unitSkillList=[]; _prep.unitDone=[];
  Object.assign(_prep,{state:'exam',questions:qs,answers:[],currentIdx:0,selectedOpt:null,answered:false,startTime:Date.now(),endTime:null,timeLeft:0,showReview:false,lives:3,maxLives:3,streak:0,streakBonusAccum:0,gameStartTime:Date.now(),retryLock:false,gameOver:false,qStartTime:Date.now()});
  clearInterval(_prepTimerIntv);
  clearInterval(_prep.gameTimerIntv);_prep.gameTimerIntv=setInterval(_prepGameTimerTick,1000);
  _snd.start();_renderPreparatePane();
}
function _prepLeaderboardHtml(topic,compact,isExam){
  if(!topic) return '';
  isExam=!!isExam;
  const _cacheKey=topic+'|'+(isExam?'exam':'skill');
  if(_prepLeaderboardTopic!==_cacheKey&&!_prepLeaderboardLoading){
    _prepLeaderboard=null; _prepLeaderboardTopic=null;
  }
  if(_prepLeaderboard===null&&!_prepLeaderboardLoading){
    _prepLoadLeaderboard(topic,isExam);
    return '<div style="text-align:center;padding:10px;color:rgba(255,255,255,0.35);font-size:12px">Cargando leaderboard...</div>';
  }
  if(_prepLeaderboardLoading) return '<div style="text-align:center;padding:10px;color:rgba(255,255,255,0.35);font-size:12px">Cargando...</div>';
  if(!_prepLeaderboard||!_prepLeaderboard.length) return '<div style="text-align:center;padding:10px;color:rgba(255,255,255,0.25);font-size:12px;font-style:italic">Sin registros aun — ¡sé el primero!</div>';
  const lbMe=_bingoMe(); const myUid=lbMe?.uid;
  const fmtT=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${((s||0)%60).toString().padStart(2,'0')}`;
  const medals=['🥇','🥈','🥉'];
  const rankBonus=[1.5,1.25,1.10];
  const limit=compact?5:10;
  const _lbBaseScore = e => {
    if (e.score != null) return e.score;
    const pct = (e.correct??0)/(e.total||1);
    const tpq = e.total>0 ? (e.timeSecs||0)/e.total : (e.timeSecs||0);
    const ts  = Math.round(Math.max(0,60-tpq)/60*500*pct);
    const tm  = (e.isUnitExam||e.scoreType==='exam') ? 3 : (BINGO_TOPICS?.[e.topic]?.quiz||e.scoreType==='quiz') ? 2 : 1;
    return Math.round((Math.round(pct*1000)+ts)*tm);
  };
  const rows=_prepLeaderboard.slice(0,limit).map((e,i)=>{
    const isMe=e.uid===myUid;
    const medal=medals[i]||(i+1)+'.';
    const base=_lbBaseScore(e);
    const mult=rankBonus[i]??1;
    const finalScore=Math.round(base*mult);
    const bonusTag=i<3?`<span style="font-size:9px;font-weight:900;color:${['#fbbf24','#d1d5db','#cd7c3c'][i]};opacity:0.85;margin-left:2px">+${[50,25,10][i]}%</span>`:'';
    const delBtn=isAdmin()?`<button onclick="_prepConfirmDelete('${e.id}')" onmouseover="this.style.color='#f87171';this.style.textShadow='0 0 8px rgba(239,68,68,0.8)';this.style.transform='scale(1.25)'" onmouseout="this.style.color='rgba(239,68,68,0.5)';this.style.textShadow='none';this.style.transform='scale(1)'" style="background:none;border:none;color:rgba(239,68,68,0.5);cursor:pointer;font-size:13px;padding:0 2px;line-height:1;transition:all .15s" title="Eliminar">✕</button>`:'';
    return `<div style="display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:8px;background:${isMe?'rgba(34,211,238,0.1)':'rgba(255,255,255,0.04)'};border:1px solid ${isMe?'rgba(34,211,238,0.3)':'rgba(255,255,255,0.06)'};margin-bottom:4px">
      <span style="font-size:15px;width:26px;text-align:center;flex-shrink:0">${medal}</span>
      <span style="flex:1;font-size:12px;font-weight:700;color:${isMe?'#67e8f9':'rgba(255,255,255,0.85)'}">` + (e.name||'Alumno') + `</span>
      <span style="font-size:11px;color:rgba(255,255,255,0.35);flex-shrink:0">${e.correct??0}/${e.total??0} · ${fmtT(e.timeSecs||0)}</span>
      <span style="font-family:'Orbitron',monospace;font-size:13px;color:#fbbf24;font-weight:700;flex-shrink:0;white-space:nowrap">${finalScore}${bonusTag}</span>
      ${delBtn}
    </div>`;
  }).join('');
  const reloadBtn=isAdmin()?`<button onclick="_prepLeaderboardTopic=null;_prepLeaderboard=null;_prepLoadLeaderboard('${topic}',${isExam})" style="background:none;border:none;color:rgba(255,255,255,0.28);font-size:11px;cursor:pointer;padding:4px 0">↺ Recargar</button>`:'';
  return `<div style="margin-top:0;border-top:1px solid rgba(255,255,255,0.07);padding-top:5px">
    <div style="font-family:'Orbitron',monospace;font-size:11px;color:#fbbf24;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;margin-bottom:8px">🏆 Top Jugadores</div>
    ${rows}${reloadBtn}
  </div>`;
}
function _prepSubmitAlgo(){
  if(_prep.answered||_prep.retryLock) return;
  // Limpiar feedback anterior antes de re-evaluar
  document.querySelectorAll('.algo-dbox-correct,.algo-dbox-wrong').forEach(el=>el.classList.remove('algo-dbox-correct','algo-dbox-wrong'));
  const q = _prep.questions[_prep.currentIdx];
  if(!q||!q.algo) return;
  let correct = false;
  if(q.algo==='div'){
    // Calcular pasos para verificar intermedios
    const n1s=String(q.n1),N=n1s.length,n1d=n1s.split('').map(Number);
    const steps=[];
    let rem=0;
    for(let i=0;i<N;i++){
      rem=rem*10+n1d[i];
      if(!steps.length&&rem<q.n2&&i<N-1) continue;
      const qd=Math.floor(rem/q.n2),prod=qd*q.n2,newRem=rem-prod;
      steps.push({pStr:String(rem),subStr:String(prod),remStr:String(newRem)});
      rem=newRem;
    }
    // Verificar cociente
    const qDigits=Array.from(document.querySelectorAll('[id^="algo_q_"]')).map(i=>i.value).join('');
    correct=(parseInt(qDigits)||0)===q.cociente;
    // Verificar residuo
    if(q.residuo>0){
      const rDigits=Array.from(document.querySelectorAll('[id^="algo_rem_"]')).map(i=>i.value).join('');
      correct=correct&&((parseInt(rDigits)||0)===q.residuo);
    }
    // Verificar pasos intermedios
    for(let si=0;si<steps.length;si++){
      if(si>0){
        const bd=Array.from(document.querySelectorAll(`[id^="algo_bd${si}_"]`)).map(i=>i.value).join('');
        if(bd!==steps[si].pStr) correct=false;
      }
      const sub=Array.from(document.querySelectorAll(`[id^="algo_sub${si}_"]`)).map(i=>i.value).join('');
      if(sub!==steps[si].subStr) correct=false;
    }
  } else if(q.algo==='mul' && String(q.n2).length>1){
    // Multiplicación 2 dígitos: verificar parciales + resultado
    const n2dRev=String(q.n2).split('').reverse().map(Number);
    correct=true;
    n2dRev.forEach((d,pi)=>{
      const expected=String(q.n1*d);
      const entered=Array.from(document.querySelectorAll(`[id^="algo_p${pi}_"]`)).map(i=>i.value).join('');
      if(entered!==expected) correct=false;
    });
    const ansD=Array.from(document.querySelectorAll('[id^="algo_a_"]')).map(i=>i.value).join('');
    if(ansD!==q.a) correct=false;
  } else if(q.algo==='comb'){
    _combSubmitStep();
    return;
  } else if(q.algo==='blocks'){
    correct = _blocksState.qRef===q && _blocksState.cur===parseInt(q.a,10);
  } else {
    // Solo se verifica la fila de la diferencia/suma; la fila de llevadas es solo ayuda
    const digits = Array.from(document.querySelectorAll('[id^="algo_a_"]')).map(i=>i.value).join('');
    correct = digits === q.a;
  }
  _prepHandleAnswer(correct, q.a);
}
function _prepHandleAnswer(correct, correctAns){
  if(_prep.answered||_prep.retryLock) return;
  const q = _prep.questions[_prep.currentIdx];
  const _qt = Math.round((Date.now()-(_prep.qStartTime||Date.now()))/1000);
  _prep.answers.push({correct, given:correct?correctAns:'?', q:q.q||'', a:q.a, _src:q._src||null, timeSec:_qt});
  correct ? _snd.correct() : _snd.wrong();
  const wrap = q.algo ? document.querySelector('.algo-vert-wrap') : null;
  if(correct){
    _prep.answered = true; _prep.selectedOpt = correctAns;
    if(typeof _prep.streak==='number') _prep.streak++;
    // Bonus de tiempo por racha
    if (_prep.timeLeft > 0 && !_prep.timeUnlimited) {
      const _bMode = _prep.isUnitExam ? 'exam' : ((BINGO_TOPICS[_prep.topic]||{}).quiz ? 'quiz' : 'skill');
      const _bRate = _bMode==='exam' ? 2.5 : _bMode==='quiz' ? 5 : 10;
      const _maxStreak = _bMode==='exam' ? 5 : _bMode==='quiz' ? 4 : 3;
      const _isLevelUp = _prep.streak > _maxStreak;
      if (_isLevelUp) {
        _prep.streakBonusAccum = (_prep.streakBonusAccum||0) + 60;
        const _bW2 = Math.floor(_prep.streakBonusAccum);
        if (_bW2 > 0) { _prep.timeLeft += _bW2; _prep.streakBonusAccum -= _bW2; _prepStreakNotif('⬆️ Level UP! +60s','levelup'); }
      } else {
        _prep.streakBonusAccum = (_prep.streakBonusAccum||0) + _bRate * Math.pow(2, _prep.streak - 1);
        const _bWhole = Math.floor(_prep.streakBonusAccum);
        if (_bWhole > 0) { _prep.timeLeft += _bWhole; _prep.streakBonusAccum -= _bWhole; _prepStreakNotif('🔥 Racha ×'+_prep.streak+'  +'+_bWhole+'s','streak'); }
      }
    }
    if(wrap){
      wrap.classList.add('algo-correct');
      _algoMarkPerBox(q);
      _prepUpdateHud();
      setTimeout(()=>_prepNextQ(), 460);
    } else {
      _renderPreparatePane();
    }
  } else {
    // Fallo: quitar vida, feedback por caja, permitir reintento
    _prep.retryLock = true;
    _prep.lives = Math.max(0, (_prep.lives||1)-1);
    _prep.streak = 0; _prep.streakBonusAccum=0; if(_prep.lives>0) _prepStreakNotif('💔 Racha perdida','lose');
    if(wrap){
      wrap.classList.add('algo-shake');
      _algoMarkPerBox(q);
      _prepUpdateHud();
      setTimeout(()=>{
        wrap.classList.remove('algo-shake');
        _prep.retryLock = false;
        if(_prep.lives<=0){_prep.gameOver=true;_prepFinish();}
      }, 650);
    } else {
      _prep.answered = true; _prep.selectedOpt = '__wrong__';
      _prepUpdateHud();
      _renderPreparatePane();
    }
  }
}

function _prepKeyHandler(e) {
  const focused = document.activeElement;
  if (focused && (focused.tagName === 'INPUT' || focused.tagName === 'TEXTAREA')) return;
  if (e.key === 'Enter') {
    if (_prep.answered && typeof _prepNextQ === 'function') { _prepNextQ(); return; }
    return;
  }
  const idx = parseInt(e.key) - 1;
  if (isNaN(idx) || idx < 0 || idx > 3) return;
  if (_prep.answered) return;
  const q = _prep.questions && _prep.questions[_prep.currentIdx];
  if (!q || !q.mc || !q.opts || !q.opts[idx]) return;
  _prepSelectOpt(q.opts[idx]);
}
if (!window._prepKbBound) {
  document.addEventListener('keydown', _prepKeyHandler);
  window._prepKbBound = true;
}

function _prepApplyLivesStreak(correct) {
  const _bMode = _prep.isUnitExam ? 'exam' : ((BINGO_TOPICS[_prep.topic]||{}).quiz ? 'quiz' : 'skill');
  if (correct) {
    if (typeof _prep.streak === 'number') _prep.streak++;
    if (_prep.timeLeft > 0 && !_prep.timeUnlimited) {
      const _bRate = _bMode==='exam' ? 2.5 : _bMode==='quiz' ? 5 : 10;
      const _maxStreak = _bMode==='exam' ? 5 : _bMode==='quiz' ? 4 : 3;
      const _isLevelUp = _prep.streak > _maxStreak;
      if (_isLevelUp) {
        _prep.streakBonusAccum = (_prep.streakBonusAccum||0) + 60;
        const _bW2 = Math.floor(_prep.streakBonusAccum);
        if (_bW2 > 0) { _prep.timeLeft += _bW2; _prep.streakBonusAccum -= _bW2; _prepStreakNotif('⬆️ Level UP! +60s','levelup'); }
      } else {
        _prep.streakBonusAccum = (_prep.streakBonusAccum||0) + _bRate * Math.pow(2, _prep.streak - 1);
        const _bWhole = Math.floor(_prep.streakBonusAccum);
        if (_bWhole > 0) { _prep.timeLeft += _bWhole; _prep.streakBonusAccum -= _bWhole; _prepStreakNotif('🔥 Racha ×'+_prep.streak+'  +'+_bWhole+'s','streak'); }
      }
    }
  } else {
    _prep.lives = Math.max(0, (_prep.lives??1)-1);
    _prep.streak = 0; _prep.streakBonusAccum = 0;
    if (_prep.lives > 0) _prepStreakNotif('💔 Racha perdida','lose');
    if (_prep.lives <= 0) { _prep.gameOver = true; }
  }
  _prepUpdateHud();
}
function _prepSelectOpt(opt) {
  if (_prep.answered) return;
  _prep.selectedOpt = opt;
  _prep.answered = true;
  const q = _prep.questions[_prep.currentIdx];
  const correct = String(q.a).toLowerCase()===String(opt).toLowerCase();
  const _qt = Math.round((Date.now()-(_prep.qStartTime||Date.now()))/1000);
  _prep.answers.push({ given:opt, correct, q:q.q, a:q.a, opts:q.opts, mc:true, _src:q._src||null, timeSec:_qt });
  _prepApplyLivesStreak(correct);
  correct ? _snd.correct() : _snd.wrong();
  if (_prep.gameOver) { _renderPreparatePane(); setTimeout(()=>_prepFinish(), 1200); return; }
  _renderPreparatePane();
}
function _prepSubmitText() {
  if (_prep.answered) return;
  const inp = document.getElementById('prep-ans-input');
  const val = (inp ? inp.value : '').trim(); if (!val) return;
  _prep.answered = true;
  const q = _prep.questions[_prep.currentIdx];
  const correct = parseFloat(val) === parseFloat(q.a) || String(val).toLowerCase() === String(q.a).toLowerCase();
  const _qt = Math.round((Date.now()-(_prep.qStartTime||Date.now()))/1000);
  _prep.answers.push({ given:val, correct, q:q.q, a:q.a, mc:false, _src:q._src||null, timeSec:_qt });
  _prepApplyLivesStreak(correct);
  correct ? _snd.correct() : _snd.wrong();
  if (_prep.gameOver) { _renderPreparatePane(); setTimeout(()=>_prepFinish(), 1200); return; }
  _renderPreparatePane();
}
function _prepNextQ() {
  if (!_prep.answered) return;
  _prep.currentIdx++;
  _prep.answered = false; _prep.selectedOpt = null;
  _prep.qStartTime = Date.now();
  if (_prep.currentIdx >= _prep.questions.length) _prepFinish();
  else { _snd.next(); _renderPreparatePane(); _algoFocusFirst(); }
}
// Cierra el examen desde el botón X guardando lo respondido hasta ese momento
function _prepExitSave() {
  _snd.click();
  clearInterval(_prepTimerIntv);
  clearInterval(_prep.gameTimerIntv);
  if (_prep.answers.length > 0) {
    _prep.endTime = Date.now();
    _prepSaveHistoryPartial();
  }
  // Si se estaba resolviendo un examen de unidad, _prep.topic quedó apuntando internamente a
  // la primera habilidad válida del examen (ver _prepUnitExam) — solo para el cálculo de
  // puntaje/leaderboard, no como una habilidad "seleccionada" de verdad. Si no se limpia acá,
  // al volver al catálogo esa habilidad aparece marcada como seleccionada A LA VEZ que el
  // examen (selectedExamSkills/selectedExamUnitIdx siguen intactos desde antes de empezar), y
  // el panel de inicio de abajo termina mostrando la habilidad en vez del examen que en
  // realidad se estaba resolviendo.
  if (_prep.isUnitExam) {
    _prep.topic = '';
    _prep.isUnitExam = false;
    _prep.examUnitSkills = [];
  }
  _prep.state = 'config';
  _renderPreparatePane();
}

// Mismo saneamiento que _prepExitSave, pero para volver al catálogo DESPUÉS de terminar
// (pantalla de resultado), no al salir a mitad de camino: si se acaba de rendir un examen de
// unidad, _prep.topic quedó apuntando internamente a la primera habilidad válida del examen
// (ver _prepUnitExam) — solo para el cálculo de puntaje/leaderboard, no como una habilidad
// "seleccionada" de verdad. Si no se limpia acá, al volver al catálogo esa habilidad aparece
// marcada como seleccionada A LA VEZ que el examen (selectedExamSkills/selectedExamUnitIdx
// siguen intactos desde antes de empezar), y el panel de inicio termina mostrando "H01" junto
// con "Examen: ..." al mismo tiempo.
function _prepBackFromResult() {
  _snd.click();
  if (_prep.isUnitExam) {
    _prep.topic = '';
    _prep.isUnitExam = false;
    _prep.examUnitSkills = [];
  }
  _prep.state = 'config';
  _prep.showReview = false;
  _renderPreparatePane();
}

// Escapa '<' cuando queda pegado a una letra/dígito (ej. "3<n<4", "2<x<6") — el navegador lo
// interpreta como el inicio de una etiqueta HTML rota y trunca todo lo que sigue. Protege las
// etiquetas HTML reales que sí usamos dentro de q/opts (br, sup, sub, span, div, b, svg y sus
// hijos, etc.) para no romperlas, y solo escapa el '<' cuando NO es parte de una de ellas.
// IMPORTANTE: esto es solo para DISPLAY (innerHTML) — nunca debe aplicarse al valor que se
// compara contra la respuesta guardada (q.a) ni al que se pasa al atributo onclick, porque ahí
// el '<' crudo es seguro (dentro de un atributo con comillas el navegador no lo interpreta como
// apertura de etiqueta) y escaparlo desalinearía la comparación de respuesta correcta/incorrecta.
function _escStrayLt(str) {
  str = String(str == null ? '' : str);
  if (str.indexOf('<') === -1) return str;
  const tagRe = /<\/?(br|sup|sub|b|div|span|svg|rect|circle|path|marker|defs|line|g|table|td|th|tr|script|canvas|input|button|textarea|hr|u|strong|a|base|col|colgroup|clippath|ellipse|img|polygon|polyline|text|tspan|use|style|lineargradient|stop|filter|femerge|femergenode|fegaussianblur|feoffset|animatetransform|animate|symbol|mask|pattern|foreignobject)\b[^>]*\/?>/gi;
  const protectedRanges = [];
  let tm;
  tagRe.lastIndex = 0;
  while ((tm = tagRe.exec(str))) protectedRanges.push([tm.index, tm.index + tm[0].length]);
  const isProtected = i => protectedRanges.some(([s, e]) => i >= s && i < e);
  let out = '';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (ch === '<' && /[a-zA-Z]/.test(str[i + 1] || '') && !isProtected(i)) out += '&lt;';
    else out += ch;
  }
  return out;
}

async function _prepSaveHistoryPartial() {
  try {
    const me = _bingoMe();
    const def = BINGO_TOPICS[_prep.topic] || {};
    const answered = _prep.answers.length;
    const correct  = _prep.answers.filter(a=>a.correct).length;
    const total    = _prep.questions.length;   // total de la sesión original
    const secs     = _prep.startTime && _prep.endTime ? Math.round((_prep.endTime-_prep.startTime)/1000) : 0;
    const pct      = total>0 ? Math.round((correct/total)*100) : 0;
    const _isDesafioPartial = _prep.level === 'especial';
    const localEntry = {
      uid: me.uid, name: me.name, level: _prep.level, grade: _prep.grade||'',
      topic: _prep.topic, topicLabel: _cleanLbl(def.lbl||_prep.topic),
      isUnitExam: !!_prep.isUnitExam, quizNum: _prep.quizNum||0,
      correct, total, pct, timeSec: secs,
      partial: true,
      // true si la sesión usó una cantidad de preguntas o un tiempo distinto al que el profesor
      // vería "por defecto" para esta habilidad (o "Sin límite" de tiempo). Estas sesiones no
      // deben contar para los puntos de Progreso (ver _ptsFirstDominatedDate en student.html).
      customConfig: !!_prep.customConfig,
      answers: _prep.answers.map(a=>({q:a.q,a:a.a,given:a.given,correct:a.correct,timeSec:a.timeSec||0,_id:a._id??null,_src:a._src||null})),
      completedAt: { seconds: Math.floor(Date.now()/1000) },
      ...(_isDesafioPartial ? {retoLbl: _prep.selectedExamLbl||'', desafioNivel: _prep.desafioNivel||1} : {})
    };
    if (Array.isArray(_prepHistoryData)) _prepHistoryData.unshift(localEntry);
    else _prepHistoryData = [localEntry];
    if (Array.isArray(_prepAdminHistData)) _prepAdminHistData.unshift(localEntry);
    _prepSyncTorneoElig();
    if (typeof db !== 'undefined' && db) {
      await db.collection('prepHistory').add({
        ...localEntry,
        completedAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    }
  } catch(e) { console.error('prepSavePartial', e); }
}

function _prepFinish() {
  clearInterval(_prepTimerIntv);
  clearInterval(_prep.gameTimerIntv);
  _prep.state = 'result'; _prep.endTime = Date.now();
  _snd.finish();
  // Marcar skill actual como completado en el contexto de unidad
  if (_prep.unitSkillList.length>0 && _prep.topic && !_prep.unitDone.includes(_prep.topic)) {
    _prep.unitDone.push(_prep.topic);
  }
  _prepSaveHistory();
  // Guardar en leaderboard si completó (no game over)
  if(!_prep.gameOver){
    try{
      const _lbMe=_bingoMe();
      if(_lbMe&&_lbMe.uid){
        const _elapsed=_prep.gameStartTime?Math.floor((_prep.endTime-_prep.gameStartTime)/1000):0;
        const _isDesafio=_prep.isUnitExam&&_prep.level==='especial';
        const _lbCorrect = _prep.answers.filter(a=>a.correct).length;
        const _lbTotal   = _prep.questions.length;
        const _lbPct      = _lbTotal > 0 ? _lbCorrect / _lbTotal : 0;
        const _lbPctScore  = Math.round(_lbPct * 1000);
        const _lbTimePerQ  = _lbTotal > 0 ? _elapsed / _lbTotal : _elapsed;
        const _lbTimeScore = Math.round(Math.max(0, 60 - _lbTimePerQ) / 60 * 500 * _lbPct);
        const _lbTypeMult  = _prep.isUnitExam ? 3 : (BINGO_TOPICS[_prep.topic]?.quiz ? 2 : 1);
        const _lbScore     = Math.round((_lbPctScore + _lbTimeScore) * _lbTypeMult);
        const _entry={
          uid:_lbMe.uid, name:_lbMe.name||'Alumno',
          topic:_prep.topic, timeSecs:_elapsed,
          lives:_prep.lives??0,
          correct:_lbCorrect,
          total:_lbTotal,
          score:_lbScore, isUnitExam:!!_prep.isUnitExam, scoreType:_prep.isUnitExam?'exam':(BINGO_TOPICS[_prep.topic]?.quiz?'quiz':'skill'),
          completedAt:firebase.firestore.FieldValue.serverTimestamp(),
          ...(_isDesafio?{desafio:true,retoLbl:_prep.selectedExamLbl||'',nivel:_prep.desafioNivel||1}:{})
        };
        db.collection('prepLeaderboard').add(_entry)
          .then(()=>{
            _prepLeaderboardTopic=null;_prepLeaderboard=null;
            if(_isDesafio){_prepDesafioLb=null;_prepLoadDesafioLeaderboard();}
            else{_prepLoadLeaderboard(_prep.topic,!!_prep.isUnitExam);}
          })
          .catch(e=>console.error('leaderboard save',e));
      }
    }catch(e){console.error('leaderboard save outer',e);}
  }
  _renderPreparatePane();
}
function _prepGetQuizSkills(quizTopic) {
  // PREP_CURRICULUM[level] es objeto por grado → aplanar todos los arrays de unidades
  const levelData = PREP_CURRICULUM[_prep.level] || {};
  const allUnits = Object.values(levelData).flat();
  for (const unit of allUnits) {
    if (!Array.isArray(unit.skills)) continue;
    const idx = unit.skills.indexOf(quizTopic);
    if (idx === -1) continue;
    // Encontrar cuestionario anterior (si lo hay)
    let prevIdx = -1;
    for (let i = idx-1; i >= 0; i--) {
      if (BINGO_TOPICS[unit.skills[i]]?.quiz) { prevIdx = i; break; }
    }
    // Habilidades entre el cuestionario anterior y este (excluir quizzes)
    return unit.skills.slice(prevIdx+1, idx).filter(sk => !BINGO_TOPICS[sk]?.quiz);
  }
  return [];
}
async function _prepSaveHistory() {
  try {
    const me = _bingoMe();
    const def = BINGO_TOPICS[_prep.topic] || {};
    const correct = _prep.answers.filter(a=>a.correct).length;
    const total = _prep.questions.length;
    const secs = _prep.startTime && _prep.endTime ? Math.round((_prep.endTime-_prep.startTime)/1000) : 0;
    const pct = total>0 ? Math.round((correct/total)*100) : 0;
    // Actualización optimista: insertar resultado localmente de inmediato
    // para que los colores de dominio se refresquen sin esperar a Firestore
    // Para examen de unidad, usar la etiqueta de la unidad (no la del primer skill) — y de paso
    // guardar el objeto de la unidad completa (con sus cuestionarios incluidos) para reusarlo
    // más abajo al propagar un examen perfecto.
    const _examUnitObj = _prep.isUnitExam && (_prep.examUnitSkills||[]).length
      ? (() => {
          const levelData = PREP_CURRICULUM[_prep.level] || {};
          const allUnits = Object.values(levelData).flat();
          return allUnits.find(u=>Array.isArray(u.skills)&&u.skills.includes(_prep.examUnitSkills[0])) || null;
        })()
      : null;
    const _examUnitLabel = _prep.isUnitExam && (_prep.examUnitSkills||[]).length
      ? (_examUnitObj ? _examUnitObj.lbl : _cleanLbl(def.lbl||_prep.topic))
      : null;
    const _isDesafioSave = _prep.level === 'especial';
    const localEntry = {
      id: 'local_' + Date.now(),
      uid: me.uid, name: me.name, level: _prep.level, grade: _prep.grade||'',
      topic: _prep.topic, topicLabel: _examUnitLabel || _cleanLbl(def.lbl||_prep.topic), isUnitExam: !!_prep.isUnitExam, quizNum: _prep.quizNum||0,
      correct, total, pct, timeSec: secs,
      // true si la sesión usó una cantidad de preguntas o un tiempo distinto al que el profesor
      // vería "por defecto" para esta habilidad (o "Sin límite" de tiempo). Estas sesiones no
      // deben contar para los puntos de Progreso (ver _ptsFirstDominatedDate en student.html).
      customConfig: !!_prep.customConfig,
      answers: _prep.answers.map(a=>({q:a.q,a:a.a,given:a.given,correct:a.correct,timeSec:a.timeSec||0,_id:a._id??null,_src:a._src||null})),
      completedAt: { seconds: Math.floor(Date.now()/1000) },
      ...(_isDesafioSave ? {retoLbl: _prep.selectedExamLbl||'', desafioNivel: _prep.desafioNivel||1} : {})
    };
    if (Array.isArray(_prepHistoryData)) _prepHistoryData.unshift(localEntry);
    else _prepHistoryData = [localEntry];
    // También actualizar el historial del panel admin para que el profesor vea su propio resultado al instante
    if (Array.isArray(_prepAdminHistData)) _prepAdminHistData.unshift(localEntry);
    if (pct === 100) setTimeout(()=>_snd.dominate(), 400);
    // Si examen de unidad al 100%: marcar como dominadas TODAS las habilidades Y cuestionarios
    // de la unidad que aún no lo estén — un examen perfecto certifica que el alumno domina todo
    // el tema completo, incluidos sus cuestionarios (antes esto solo pasaba con habilidades
    // sueltas; un cuestionario solo se dominaba resolviéndolo directo). Esto es "solo para
    // bien": si algo ya estaba dominado se deja tal cual, y un examen que NO sale perfecto
    // nunca hace bajar el nivel de nada (ver el otro bloque de propagación más abajo, que sigue
    // sin tocar los cuestionarios cuando el examen es parcial).
    if (pct === 100 && _prep.isUnitExam && (_prep.examUnitSkills||[]).length) {
      const now = Math.floor(Date.now()/1000);
      // _prep.examUnitSkills solo trae las habilidades (los cuestionarios de la unidad se
      // excluyen al armar el examen para no duplicar preguntas — ver _prepUnitExam), así que
      // para también dominar sus cuestionarios hay que tomarlos aparte del objeto de unidad.
      const _examQuizSkills = (_examUnitObj?.skills||[]).filter(sk=>BINGO_TOPICS[sk]?.quiz);
      const _examAllSkills = [...(_prep.examUnitSkills||[]), ..._examQuizSkills];
      for (const sk of _examAllSkills) {
        if (_prepMasteryLevel(sk)==='dominado') continue;
        const skDef=BINGO_TOPICS[sk]||{};
        const skE={uid:me.uid,name:me.name,level:_prep.level,grade:_prep.grade||'',topic:sk,topicLabel:skDef.lbl||sk,correct:4,total:4,pct:100,timeSec:0,answers:[],autoFromExam:true,customConfig:!!_prep.customConfig,completedAt:{seconds:now}};
        if (Array.isArray(_prepHistoryData)) _prepHistoryData.unshift(skE);
        db.collection('prepHistory').add({uid:me.uid,name:me.name,level:_prep.level,grade:_prep.grade||'',topic:sk,topicLabel:skDef.lbl||sk,correct:4,total:4,pct:100,timeSec:0,answers:[],autoFromExam:true,customConfig:!!_prep.customConfig,completedAt:firebase.firestore.FieldValue.serverTimestamp()}).catch(e=>console.error('exam auto-dominate',e));
      }
    }
    // Si cuestionario completado (cualquier pct > 0): propagar nivel a cada habilidad cubierta.
    // Cada habilidad recibe su propio pct basado en cuántas de SUS preguntas se respondieron correctamente.
    // Si no hay etiqueta _src en las respuestas, se usa el pct global como fallback.
    if (BINGO_TOPICS[_prep.topic]?.quiz && pct > 0) {
      const coveredSkills = _prepGetQuizSkills(_prep.topic);
      const now = Math.floor(Date.now()/1000);
      // Agrupar respuestas por habilidad fuente (_src)
      const srcMap = {};
      for (const ans of _prep.answers) {
        const src = ans._src;
        if (!src || !coveredSkills.includes(src)) continue;
        if (!srcMap[src]) srcMap[src] = { correct: 0, total: 0 };
        srcMap[src].total++;
        if (ans.correct) srcMap[src].correct++;
      }
      for (const sk of coveredSkills) {
        const stats = srcMap[sk];
        const skPct     = stats ? Math.round((stats.correct / stats.total) * 100) : pct;
        const skCorrect = stats ? stats.correct : Math.round(pct * 4 / 100);
        const skTotal   = stats ? stats.total   : 4;
        const skDef = BINGO_TOPICS[sk]||{};
        const skEntry = {
          uid: me.uid, name: me.name, level: _prep.level, grade: _prep.grade||'',
          topic: sk, topicLabel: skDef.lbl||sk,
          correct: skCorrect, total: skTotal, pct: skPct, timeSec: 0, answers: [],
          autoFromQuiz: _prep.topic, customConfig: !!_prep.customConfig, completedAt: { seconds: now }
        };
        if (Array.isArray(_prepHistoryData)) _prepHistoryData.unshift(skEntry);
        db.collection('prepHistory').add({
          uid: me.uid, name: me.name, level: _prep.level, grade: _prep.grade||'',
          topic: sk, topicLabel: skDef.lbl||sk,
          correct: skCorrect, total: skTotal, pct: skPct, timeSec: 0, answers: [],
          autoFromQuiz: _prep.topic,
          customConfig: !!_prep.customConfig,
          completedAt: firebase.firestore.FieldValue.serverTimestamp()
        }).catch(e=>console.error('quiz-propagate save',e));
      }
    }
    // Si examen de unidad completado (cualquier pct > 0): propagar nivel per-skill igual que los cuestionarios.
    // Cada habilidad de la unidad recibe el pct basado en sus propias preguntas (via _src).
    if (_prep.isUnitExam && pct > 0 && (_prep.examUnitSkills||[]).length) {
      const coveredSkills = _prep.examUnitSkills;
      const now = Math.floor(Date.now()/1000);
      const srcMap2 = {};
      for (const ans of _prep.answers) {
        const src = ans._src;
        if (!src || !coveredSkills.includes(src)) continue;
        if (!srcMap2[src]) srcMap2[src] = { correct: 0, total: 0 };
        srcMap2[src].total++;
        if (ans.correct) srcMap2[src].correct++;
      }
      for (const sk of coveredSkills) {
        if (BINGO_TOPICS[sk]?.quiz) continue; // los cuestionarios se dominan directamente
        const stats2 = srcMap2[sk];
        const skPct2     = stats2 ? Math.round((stats2.correct / stats2.total) * 100) : pct;
        const skCorrect2 = stats2 ? stats2.correct : Math.round(pct * 4 / 100);
        const skTotal2   = stats2 ? stats2.total   : 4;
        const skDef2 = BINGO_TOPICS[sk]||{};
        const skE2 = { uid:me.uid, name:me.name, level:_prep.level, grade:_prep.grade||'', topic:sk, topicLabel:skDef2.lbl||sk, correct:skCorrect2, total:skTotal2, pct:skPct2, timeSec:0, answers:[], autoFromExam:_prep.topic, customConfig:!!_prep.customConfig, completedAt:{seconds:now} };
        if (Array.isArray(_prepHistoryData)) _prepHistoryData.unshift(skE2);
        db.collection('prepHistory').add({ uid:me.uid, name:me.name, level:_prep.level, grade:_prep.grade||'', topic:sk, topicLabel:skDef2.lbl||sk, correct:skCorrect2, total:skTotal2, pct:skPct2, timeSec:0, answers:[], autoFromExam:_prep.topic, customConfig:!!_prep.customConfig, completedAt:firebase.firestore.FieldValue.serverTimestamp() }).catch(e=>console.error('exam skill-propagate save',e));
      }
    }
    await db.collection('prepHistory').add({
      uid:        me.uid,
      name:       me.name,
      level:      _prep.level,
      grade:      _prep.grade || '',
      topic:      _prep.topic,
      topicLabel: _examUnitLabel || _cleanLbl(def.lbl || _prep.topic),
      isUnitExam: !!_prep.isUnitExam,
      quizNum:    _prep.quizNum || 0,
      correct, total, pct,
      timeSec:    secs,
      customConfig: !!_prep.customConfig,
      answers:    _prep.answers.map(a=>({q:a.q, a:a.a, given:a.given, correct:a.correct, timeSec:a.timeSec||0, _id:a._id??null, _src:a._src||null})),
      completedAt: firebase.firestore.FieldValue.serverTimestamp(),
      ...(_isDesafioSave ? {retoLbl: _prep.selectedExamLbl||'', desafioNivel: _prep.desafioNivel||1} : {})
    });
    // Actualización optimista ya aplicada arriba — no recargar desde Firestore
    // para evitar race condition con los auto-dominados (fire-and-forget)
    _prepSyncTorneoElig();
  } catch(e) { console.error('prep history save', e); }
}
async function loadPrepHistory() {
  _prepHistoryLoading = true;
  try {
    // uid: admin → 'teacher', loggeado → String(id), invitado → _bingoGuestUid
    const uid = isAdmin() ? 'teacher' : (getLoggedId() !== null ? String(getLoggedId()) : (_bingoGuestUid || null));
    if (!uid) { _prepHistoryData = []; _prepHistoryLoading = false; if (dashGamingMode==='preparate'||document.getElementById('preparate-pane')) _renderPreparatePane(); return; }
    // IMPORTANTE: antes se pedía .limit(200) SIN ordenar en el servidor ("para evitar índice
    // compuesto"), confiando en ordenar recién en el cliente después de traer los 200. Eso es
    // incorrecto: sin orderBy, Firestore devuelve un subconjunto arbitrario de hasta 200
    // documentos, no necesariamente los 200 más recientes. Para el uid 'teacher' (compartido
    // por TODO admin/profesor de toda la plataforma) el historial real supera largamente 200
    // registros, así que sesiones recién completadas podían quedar fuera de ese subconjunto
    // arbitrario, y entonces habilidades/cuestionarios seguían mostrando nivel y fecha de una
    // sesión vieja que sí entró en el lote, como si la nueva nunca se hubiera guardado.
    // Ahora se pide orderBy+limit al servidor, que sí garantiza traer los 200 MÁS RECIENTES.
    // Si el índice compuesto (uid ASC, completedAt DESC) todavía no existe en Firestore, esta
    // consulta falla con 'failed-precondition' — se cae de vuelta a la consulta anterior sin
    // romper la app mientras se crea el índice (Firestore imprime en consola un link para
    // crearlo con un clic).
    let snap;
    try {
      snap = await db.collection('prepHistory').where('uid','==',uid).orderBy('completedAt','desc').limit(1000).get();
    } catch(idxErr) {
      console.error('prepHistory orderBy query falló (¿falta índice compuesto uid+completedAt? revisa el link de Firestore en este error), usando fallback sin orden de servidor:', idxErr);
      snap = await db.collection('prepHistory').where('uid','==',uid).limit(1000).get();
    }
    _prepHistoryData = [];
    snap.forEach(doc => _prepHistoryData.push({ id:doc.id, ...doc.data() }));
    // Se mantiene el sort en cliente como red de seguridad (por si se usó el fallback, o por
    // documentos con completedAt aún no resuelto por el servidor).
    _prepHistoryData.sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  } catch(e) { _prepHistoryData = []; console.error('prep history load', e); }
  _prepHistoryLoading = false;
  _prepSyncTorneoElig();
  // Auto-abrir "Mis Cursos" si el alumno no tiene curso seleccionado y tiene cursos asignados
  if (!isAdmin() && !_prep.level && !_prep.openSelector) {
    const _lid = getLoggedId();
    if (_lid !== null && _lid !== 0 && _prepMyCourses(_lid).length > 0) {
      _prep.openSelector = 'miscursos';
    }
  }
  if (dashGamingMode==='preparate' || document.getElementById('preparate-pane')) _renderPreparatePane();
}
async function loadPrepHistoryAdmin() {
  if (!isAdmin()) return;
  _prepAdminHistLoading = true;
  try {
    // IMPORTANTE: antes este .limit(200) no tenía .orderBy(), así que Firestore devolvía 200
    // documentos "cualesquiera" de TODA la colección (de todos los alumnos, sin importar fecha) y
    // recién después se ordenaban en el cliente — para entonces ya se habían descartado al azar
    // sesiones recientes. Con .orderBy() antes del .limit(), Firestore trae directo las 200 más
    // recientes de verdad. (No requiere índice compuesto: no hay filtro where, solo orderBy.)
    const snap = await db.collection('prepHistory').orderBy('completedAt','desc').limit(200).get();
    _prepAdminHistData = [];
    snap.forEach(doc => _prepAdminHistData.push({ id:doc.id, ...doc.data() }));
    _prepAdminHistData.sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  } catch(e) { _prepAdminHistData = []; console.error('prep admin history load', e); }
  _prepAdminHistLoading = false;
  _renderPreparatePane();
  _prepAdminCheckExtraStudents(); // fire-and-forget: no bloquea el render de arriba
}
// Detecta alumnos con historial propio en prepHistory que quedaron fuera del top-200 global
// (_prepAdminHistData) — típicamente alumnos que practican con menos frecuencia que el resto del
// colegio. Para cada uno hace solo una consulta mínima (.limit(1), un único documento) para
// confirmar si existe AL MENOS un registro suyo; no trae su historial completo todavía (eso se
// carga recién bajo demanda, ver _prepAdminFetchOwnHistory, cuando el admin hace clic en su
// etiqueta). Se dispara una sola vez por apertura del panel de historial.
async function _prepAdminCheckExtraStudents() {
  if (_prepAdminExtraChecking || !Array.isArray(_prepAdminHistData)) return;
  _prepAdminExtraChecking = true;
  try {
    const known = new Set(_prepAdminHistData.map(h => String(h.uid)));
    const missing = getStudents().filter(s => !known.has(String(s.id)) && !_prepAdminExtraUids.has(String(s.id)));
    let changed = false;
    for (const s of missing) {
      try {
        const snap = await db.collection('prepHistory').where('uid','==',String(s.id)).limit(1).get();
        if (!snap.empty) { _prepAdminExtraUids.add(String(s.id)); changed = true; }
      } catch(e) { console.error('[prep-admin] check extra student', s.id, e); }
    }
    if (changed && _prepAdminShowHist) _renderPreparatePane();
  } finally { _prepAdminExtraChecking = false; }
}
// Carga el historial individual completo de un alumno que quedó fuera del top-200 global, para
// cuando el admin filtra por su etiqueta (ver _prepAdminHistoryHtml). Mismo patrón de fallback
// sin orderBy que _ptsFetchHist (student.html) por si falta el índice compuesto uid+completedAt.
async function _prepAdminFetchOwnHistory(uid) {
  if (_prepAdminExtraHist[uid] || _prepAdminExtraHistLoading[uid]) return;
  _prepAdminExtraHistLoading[uid] = true;
  try {
    let snap;
    try {
      // Límite alto (antes 200): un alumno muy activo (ej. Lucio) puede superar fácilmente
      // las 200 actividades totales, y cuando eso pasa Y además falla la consulta ordenada
      // (ver catch de abajo, típico por faltar el índice compuesto uid+completedAt), el
      // fallback sin orden le devolvía "200 cualquiera" de Firestore — ni siquiera las 200 más
      // recientes — lo que hacía que faltaran actividades sueltas y salteadas de un mismo día
      // en vez de faltar solo las más antiguas. Con 3000 (mismo tope que usa el propio alumno
      // en _ptsFetchHist para su cálculo de Horas) esto ya no debería recortar a nadie.
      snap = await db.collection('prepHistory').where('uid','==',uid).orderBy('completedAt','desc').limit(3000).get();
    } catch(idxErr) {
      console.error('[prep-admin] orderBy query falló (¿falta índice compuesto uid+completedAt? revisa el link de Firestore en este error para crearlo), usando fallback sin orden:', idxErr);
      snap = await db.collection('prepHistory').where('uid','==',uid).limit(3000).get();
    }
    const arr = [];
    snap.forEach(doc => arr.push({ id: doc.id, ...doc.data() }));
    arr.sort((a,b) => (b.completedAt?.seconds||0) - (a.completedAt?.seconds||0));
    _prepAdminExtraHist[uid] = arr;
  } catch(e) { console.error('[prep-admin] fetch own history', uid, e); _prepAdminExtraHist[uid] = []; }
  _prepAdminExtraHistLoading[uid] = false;
  _renderPreparatePane();
}
// Muestra el modal propio (estilo app, sin el cuadro nativo del navegador) para confirmar
// la reasignación de una partida del historial de 'teacher' a un alumno real.
function _prepConfirmReassign(histId, studentId, studentName, studentIcon, studentColor) {
  const old = document.getElementById('_prepReassignModal');
  if (old) old.remove();
  const firstName = String(studentName).split(' ')[0];
  const safeName = String(studentName).replace(/'/g, "\\'");
  const m = document.createElement('div');
  m.id = '_prepReassignModal';
  m.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(7,7,20,0.85);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box';
  m.innerHTML = `<div style="background:#141726;border:1px solid rgba(255,255,255,0.08);border-radius:18px;padding:22px 20px 20px;max-width:300px;width:100%">
    <div style="display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:18px">
      <div style="display:flex;flex-direction:column;align-items:center;gap:7px;width:84px">
        <div style="width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:23px;background:rgba(255,255,255,0.06);border:1.5px dashed rgba(255,255,255,0.25)">🎓</div>
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:12px;font-weight:700;color:rgba(255,255,255,0.8);text-align:center">Tú</div>
      </div>
      <div style="color:#6366f1;font-size:20px;margin-top:-20px">→</div>
      <div style="display:flex;flex-direction:column;align-items:center;gap:7px;width:84px">
        <div style="width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:23px;background:${studentColor}22;border:1.5px solid ${studentColor}">${studentIcon}</div>
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:12px;font-weight:700;color:rgba(255,255,255,0.8);text-align:center">${firstName}</div>
      </div>
    </div>
    <div style="font-family:'Barlow Condensed',sans-serif;font-size:19px;font-weight:800;color:#fff;text-align:center;margin:0 0 8px">¿Asignar esta partida?</div>
    <hr style="border:none;border-top:1px dashed rgba(255,255,255,0.12);margin:12px 0">
    <div style="font-size:12px;line-height:1.55;color:rgba(255,255,255,0.5);text-align:left;display:flex;gap:7px;align-items:flex-start">
      <span style="flex-shrink:0;font-size:13px;margin-top:1px">📲</span><span>Cuenta en el historial y el reporte semanal de ${firstName}.</span>
    </div>
    <div style="font-size:12px;line-height:1.55;color:rgba(255,255,255,0.5);text-align:left;display:flex;gap:7px;align-items:flex-start;margin-top:6px">
      <span style="flex-shrink:0;font-size:13px;margin-top:1px">🏆</span><span>El ranking de la habilidad no se modifica.</span>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1.3fr;gap:10px;margin-top:16px">
      <button onclick="document.getElementById('_prepReassignModal').remove()" style="font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:13.5px;background:rgba(255,255,255,0.05);color:rgba(255,255,255,0.55);border:1px solid rgba(255,255,255,0.1);border-radius:22px;padding:10px 0;cursor:pointer">Cancelar</button>
      <button onclick="document.getElementById('_prepReassignModal').remove();_prepDoReassignHistoryToStudent('${histId}','${String(studentId)}','${safeName}')" style="font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:13.5px;background:rgba(99,102,241,0.9);color:#fff;border:1px solid rgba(99,102,241,0.9);border-radius:22px;padding:10px 0;cursor:pointer">Asignar a ${firstName}</button>
    </div>
  </div>`;
  m.addEventListener('click', e => { if (e.target === m) m.remove(); });
  document.body.appendChild(m);
}
// Reasigna una partida del historial (guardada con la cuenta 'teacher', p.ej. cuando el
// profesor resolvió algo en clase con su propia cuenta) al historial real de un alumno,
// para que cuente en su reporte semanal y en su nivel de dominio. Solo mueve el registro
// de prepHistory (uid + name); NO toca el ranking/leaderboard de esa habilidad/cuestionario/examen.
async function _prepDoReassignHistoryToStudent(histId, studentId, studentName) {
  if (_prepAdminReassignBusyId) return;
  _prepAdminReassignBusyId = histId;
  _renderPreparatePane();
  try {
    const rec = (_prepAdminHistData||[]).find(h => h.id === histId);
    const originalUid = rec ? String(rec.uid) : null;
    await db.collection('prepHistory').doc(histId).update({ uid: String(studentId), name: studentName, reassignedFromTeacher: true });
    if (rec) { rec.uid = String(studentId); rec.name = studentName; rec.reassignedFromTeacher = true; }

    // Si lo reasignado es un cuestionario o un examen de unidad, también hay que reasignar los
    // registros de habilidad que ese cuestionario/examen generó automáticamente al completarse
    // (autoFromQuiz/autoFromExam — ver _prepSaveHistory), para que influyan en el dominio de esas
    // habilidades exactamente igual que cuando el alumno lo completa él mismo. Sin esto, esos
    // registros quedaban con el uid del profesor y el alumno nunca recibía ese avance, aunque el
    // cuestionario/examen en sí ya apareciera bien asignado.
    if (rec && originalUid) {
      const isQuizTopic = /_bq\d/.test(rec.topic || '');
      const isExamRec = !!rec.isUnitExam;
      if (isQuizTopic || isExamRec) {
        try {
          const snap = await db.collection('prepHistory').where('uid', '==', originalUid).get();
          const recSec = rec.completedAt?.seconds || 0;
          const unit = isExamRec ? _prepTopicUnit(rec.topic, rec.level) : null;
          const linkedIds = [];
          snap.forEach(doc => {
            const d = doc.data();
            if (String(d.level || '') !== String(rec.level || '')) return;
            if (String(d.grade || '') !== String(rec.grade || '')) return;
            const sec = d.completedAt?.seconds || 0;
            // Misma "tanda" de guardado que el cuestionario/examen reasignado, no una coincidencia
            // lejana en el tiempo con otra actividad distinta.
            if (Math.abs(sec - recSec) > 120) return;
            if (isQuizTopic && d.autoFromQuiz === rec.topic) { linkedIds.push(doc.id); return; }
            if (isExamRec && (d.autoFromExam === true || d.autoFromExam === rec.topic)) {
              // La habilidad propagada debe pertenecer a la misma unidad que el examen reasignado
              // (evita arrastrar de un examen distinto completado casi al mismo tiempo).
              if (unit && _prepTopicUnit(d.topic, d.level) === unit) linkedIds.push(doc.id);
            }
          });
          if (linkedIds.length) {
            await Promise.all(linkedIds.map(id =>
              db.collection('prepHistory').doc(id).update({ uid: String(studentId), name: studentName, reassignedFromTeacher: true })
            ));
            (_prepAdminHistData || []).forEach(h => {
              if (linkedIds.includes(h.id)) { h.uid = String(studentId); h.name = studentName; h.reassignedFromTeacher = true; }
            });
          }
        } catch (e2) { console.error('reasignar habilidades vinculadas al cuestionario/examen', e2); }
      }
    }
    _prepAdminReassignOpenId = null;
  } catch(e) {
    console.error('reasignar partida a alumno', e);
    alert('No se pudo asignar la partida. Intenta de nuevo.');
  }
  _prepAdminReassignBusyId = null;
  _renderPreparatePane();
}
// Corrección de una sola vez para cuestionarios/exámenes que ya se habían reasignado a un alumno
// ANTES de que _prepDoReassignHistoryToStudent empezara también a reasignar las habilidades que
// generaron automáticamente (autoFromQuiz/autoFromExam). Esas reasignaciones viejas solo movieron
// el cuestionario/examen en sí, así que las habilidades vinculadas seguían con uid:'teacher' y no
// influían en el dominio del alumno. Este botón recorre todo lo ya reasignado y aplica el mismo
// criterio de "misma tanda de guardado" que usa la reasignación en vivo, ahora en retrospectiva.
// Es seguro ejecutarlo varias veces: una vez corregida una habilidad, ya no vuelve a aparecer en
// la búsqueda (su uid ya no es 'teacher').
async function _prepBackfillReassignedPropagation() {
  if (!isAdmin() || _prepBackfillBusy) return;
  _prepBackfillBusy = true;
  _renderPreparatePane();
  let checkedRecords = 0, fixedSkills = 0;
  try {
    const [snapReassigned, snapTeacher] = await Promise.all([
      db.collection('prepHistory').where('reassignedFromTeacher', '==', true).get(),
      db.collection('prepHistory').where('uid', '==', 'teacher').get(),
    ]);
    const candidates = [];
    snapReassigned.forEach(doc => {
      const d = doc.data();
      if (/_bq\d/.test(d.topic || '') || d.isUnitExam) candidates.push({ id: doc.id, ...d });
    });
    const teacherDocs = [];
    snapTeacher.forEach(doc => teacherDocs.push({ id: doc.id, ...doc.data() }));

    for (const rec of candidates) {
      checkedRecords++;
      const isQuizTopic = /_bq\d/.test(rec.topic || '');
      const isExamRec = !!rec.isUnitExam;
      const recSec = rec.completedAt?.seconds || 0;
      const unit = isExamRec ? _prepTopicUnit(rec.topic, rec.level) : null;
      const linkedIds = [];
      teacherDocs.forEach(d => {
        if (String(d.level || '') !== String(rec.level || '')) return;
        if (String(d.grade || '') !== String(rec.grade || '')) return;
        const sec = d.completedAt?.seconds || 0;
        if (Math.abs(sec - recSec) > 120) return;
        if (isQuizTopic && d.autoFromQuiz === rec.topic) { linkedIds.push(d.id); return; }
        if (isExamRec && (d.autoFromExam === true || d.autoFromExam === rec.topic)) {
          if (unit && _prepTopicUnit(d.topic, d.level) === unit) linkedIds.push(d.id);
        }
      });
      if (linkedIds.length) {
        await Promise.all(linkedIds.map(id =>
          db.collection('prepHistory').doc(id).update({ uid: rec.uid, name: rec.name, reassignedFromTeacher: true })
        ));
        fixedSkills += linkedIds.length;
      }
    }
    alert('Listo: revisé ' + checkedRecords + ' cuestionario(s)/examen(es) ya asignados y corregí ' + fixedSkills + ' registro(s) de habilidad vinculados.');
    _prepAdminHistData = null; // forzar recarga para reflejar los cambios ya en esta sesión
    loadPrepHistoryAdmin();
  } catch(e) {
    console.error('backfill reasignación de habilidades vinculadas', e);
    alert('Ocurrió un error al corregir. Revisa la consola.');
  }
  _prepBackfillBusy = false;
  _renderPreparatePane();
}
// Formatea segundos como "1h 17m 4s" / "17m 4s" / "4s" (omite unidades en cero, salvo que el
// total sea 0). Usada en el historial de alumnos para mostrar cuánto duró cada intento y el
// total del listado filtrado — mismo campo timeSec que usa el cálculo automático de Puntos
// (_ptsSecondsForDate en student.html), así ambos lados se pueden comparar directamente.
function _prepFmtDur(totalSec) {
  const sec = Math.max(0, Math.round(Number(totalSec)||0));
  const h = Math.floor(sec/3600), m = Math.floor((sec%3600)/60), s = sec%60;
  const parts = [];
  if (h) parts.push(h+'h');
  if (m) parts.push(m+'m');
  if (s || !parts.length) parts.push(s+'s');
  return parts.join(' ');
}
